#define SAMPLES 12
// HOLM 35 f/1.4: a camera lens in a photographer's studio, raymarched.
// Units are centimetres. The lens stands on its mount at the origin with its
// optical axis up (+y); the studio is three softboxes, two strip lights and a
// black acrylic floor. Every animated value is a param:
//    0  1  2   camera orbit: azimuth, elevation (degrees), distance
//    3  4  5   camera target
//    6         vertical field of view (degrees)
//    7         focus distance (cm)        8  blur: CoC in px at twice the focus distance
//    9         exposure                   10 explode 0..1 (the optics slide out)
//    11        focus ring turn (degrees)  12 iris, stops closed from f/1.4 (0..7)
//    13        light: 0 dark, 1 the sweep crosses, 2 full studio
//    14        lens tilt about z (deg)    15 lens spin about its axis (deg)
// The image's alpha carries the signed circle of confusion for the dof pass.

static const float PI = 3.14159265;
static const float TAU = 6.28318531;

// ------------------------------------------------------------------ helpers
float3 rotY(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }
float3 rotZ(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x - s * p.y, s * p.x + c * p.y, p.z); }
float hash12(float2 p) { float3 p3 = frac(float3(p.x, p.y, p.x) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return frac((p3.x + p3.y) * p3.z); }
float box2(float2 p, float2 b, float r) { float2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
// A ring turned on a lathe: radii r0..r1, heights y0..y1, its edges broken by e.
float ring(float2 ry, float r0, float r1, float y0, float y1, float e) {
  return box2(ry - float2((r0 + r1) * 0.5, (y0 + y1) * 0.5), float2((r1 - r0) * 0.5, (y1 - y0) * 0.5), e);
}
float2 opU(float2 a, float2 b) { return a.x < b.x ? a : b; }
float fbm2(float2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { s += a * snoise(float3(p, 0.37 * float(i))); p = p * 2.1 + float2(1.7, 9.2); a *= 0.5; } return s; }
float tri(float x) { return abs(frac(x) - 0.5) * 2.0; }        // 1 at integers, 0 halfway
// polynomial smooth min / max: blends a and b over a band k wide
float smin(float a, float b, float k) { float h = max(k - abs(a - b), 0.0) / k; return min(a, b) - h * h * k * 0.25; }
float smax(float a, float b, float k) { return -smin(-a, -b, k); }
float ease(float x) { x = saturate(x); return x * x * (3.0 - 2.0 * x); }

// ------------------------------------------------------------------ materials
#define M_SILVER 1.0
#define M_KNURL 2.0
#define M_BLACK 3.0
#define M_CHROME 4.0
#define M_GLASS 5.0
#define M_FLOCK 6.0
#define M_IRIS 7.0
#define M_FLOOR 8.0
#define M_EDGE 9.0
#define M_RIDGE 10.0
#define M_GOLD 11.0
#define M_ORANGE 12.0
#define M_GROUND 13.0

// ------------------------------------------------------------------ per-pixel camera state
static float3 gEye;
static float gPix;      // world size of one pixel at unit distance

float tilt() { return radians(param(14)); }
float spin() { return radians(param(15)); }
float explode() { return param(10); }

static const float3 LENS_ORIGIN = float3(0.0, 0.52, 0.0);   // the mount flange, in the world
static const float PIVOT_Y = 3.3;                            // where the lens turns when it tilts
float3 toLens(float3 p) {
  float3 q = p - LENS_ORIGIN - float3(0.0, PIVOT_Y, 0.0);
  q = rotZ(q, -tilt());
  q.y += PIVOT_Y;
  return rotY(q, -spin());
}
float3 lensToWorldDir(float3 v) { return rotZ(rotY(v, spin()), tilt()); }

// ------------------------------------------------------------------ the optics
// Eight elements in six groups, front to back. Each: centre height, centre
// thickness, front radius (+ convex), back radius (+ convex), clear radius.
// Exploded, each group slides forward to its own place on the axis.
static const float EXPLODE_BARREL = 3.4;
float groupShift(int g) {
  // front groups leave first; each eases out on its own beat
  static const float DY[7] = { 13.6, 11.9, 10.3, 9.0, 7.7, 6.6, 5.4 };
  float e = explode();
  float k = ease(e * 1.45 - float(g) * 0.075);
  return DY[g] * k;
}
float barrelShift() { return -EXPLODE_BARREL * ease(explode() * 1.3); }

// a spherical surface: + convex toward its side, - concave
float surfFront(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv - R)) - R;
  return max(-R - length(ry - float2(0.0, yv - R)), ry.y - (yv - R));
}
float surfBack(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv + R)) - R;
  return max(-R - length(ry - float2(0.0, yv + R)), (yv + R) - ry.y);
}
float element(float2 ry, float yc, float t, float Rf, float Rb, float a, out float edge) {
  float f = surfFront(ry, yc + t * 0.5, Rf);
  float b = surfBack(ry, yc - t * 0.5, Rb);
  float c = ry.x - a;
  float d = max(max(f, b), c);
  edge = c > max(f, b) - 0.002 ? 1.0 : 0.0;
  return d;
}

// The glass alone (for marching inside it). id = 5 glass, 9 inked edge.
float2 glassMap(float3 q) {
  float r = length(q.xz);
#ifdef CLEAR_EDGES
  const float EDGE_ID = M_GROUND;
#else
  const float EDGE_ID = M_EDGE;
#endif
  if (r > 2.3) return float2(r - 2.2, M_GLASS);
  float2 res = float2(1e5, M_GLASS);
  float edge;
  float y;
  // G1: E1 positive meniscus
  y = q.y - groupShift(0);
  float d = element(float2(r, y), 6.75, 0.5, 4.8, -9.0, 2.12, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G2: E2 + E3 cemented
  y = q.y - groupShift(1);
  d = element(float2(r, y), 6.0, 0.5, 3.4, -6.0, 1.85, edge);
  float e3 = max(max(max(length(float2(r, y) - float2(0.0, -0.25)) - 6.0, 2.4 - length(float2(r, y) - float2(0.0, 3.05))), r - 1.85), 3.05 - y);
  float edge3 = (r - 1.85) > -0.002 ? 1.0 : 0.0;
  d = min(d, e3);
  res = opU(res, float2(d, (edge > 0.5 || edge3 > 0.5) && r > 1.83 ? EDGE_ID : M_GLASS));
  // G3: E4 meniscus
  y = q.y - groupShift(2);
  d = element(float2(r, y), 5.0, 0.4, 2.6, -2.0, 1.5, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G4: E5 + E6 cemented (concave toward the iris)
  y = q.y - groupShift(4);
  float e5 = max(max(2.2 - length(float2(r, y) - float2(0.0, 5.5)), length(float2(r, y) - float2(0.0, 8.05)) - 5.0), r - 1.45);
  float e6 = max(max(5.0 - length(float2(r, y) - float2(0.0, 8.05)), length(float2(r, y) - float2(0.0, 5.7)) - 3.2), r - 1.45);
  e5 = max(e5, y - 3.95);
  d = min(e5, e6);
  res = opU(res, float2(d, r > 1.43 ? EDGE_ID : M_GLASS));
  // G5: E7 biconvex
  y = q.y - groupShift(5);
  d = element(float2(r, y), 1.6, 0.9, 4.0, 3.5, 1.55, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G6: E8, the rear element: its back face aspherical (a fourth-order term
  // flattens it toward the edge)
  y = q.y - groupShift(6);
  float f8 = surfFront(float2(r, y), 0.75, -6.0);
  float b8 = length(float2(r, y) - float2(0.0, 2.35)) - 2.2 + 0.012 * r * r * r * r;
  float c8 = r - 1.4;
  d = max(max(f8, b8), c8);
  res = opU(res, float2(d, c8 > max(f8, b8) - 0.002 ? EDGE_ID : M_GLASS));
  return res;
}

// The iris: eleven rounded blades between G3 and G4.
float irisRadius() { return 1.0 * 1.4 / (1.4 * pow(2.0, param(12) * 0.5)); }
float irisHole(float2 xz) {
  float a = irisRadius();
  float ang = atan2(xz.y, xz.x) + param(12) * 0.06;
  float sec = TAU / 11.0;
  float f = (frac(ang / sec) - 0.5) * sec;
  float rr = length(xz);
  float poly = rr * cos(f) - a;
  return lerp(poly, rr - a * 1.04, 0.55);     // blades are curved: rounder than a polygon
}
float irisMap(float3 q) {
  float y = q.y - 3.95 - groupShift(3);
  float r = length(q.xz);
  float disc = max(abs(y) - 0.022, r - 2.08);
  return max(disc, -irisHole(q.xz));
}

// ------------------------------------------------------------------ the barrel
// Diamond knurl on the focus ring, straight ridges on the aperture ring; both
// fade into a flat average where a pixel is wider than their pitch.
float knurlH(float3 q, float y, float fade) {
  float th = atan2(q.z, q.x) + radians(param(11));
  float u = th * (96.0 / TAU);
  float v = y / 0.2;
  // rolled, not cut: the crests, the valleys and the edges between facets are
  // rounded, so a crest catches the light as a soft line a few pixels wide
  // rather than a sub-pixel glint that flickers as the ring turns
  float h = smin(tri(u + v), tri(u - v), 0.08);
  h = smax(smin(h, 0.93, 0.12), 0.04, 0.08);
  return (h * 0.9 - 0.45) * 0.05 * fade;
}
float ridgeH(float3 q, float fade) {
  float th = atan2(q.z, q.x) + radians(param(12) * 12.0);
  float u = th * (180.0 / TAU);
  float h = smoothstep(0.0, 1.0, tri(u));
  return (h - 0.5) * 0.016 * fade;
}
float lodFade(float3 q, float pitch) {
  float3 e = toLens(gEye) - q;
  float d = length(e);
  float graze = abs(dot(normalize(float3(q.x, 0.0, q.z)), e / d));
  float foot = d * gPix / max(graze, 0.12);
  return smoothstep(pitch * 1.1, pitch * 0.45, foot);
}

float2 barrelMap(float3 q) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float2 ry = float2(r, y);
  float bound = ring(ry, 1.85, 3.25, -0.62, 7.3, 0.0);
  if (bound > 0.25) return float2(bound, M_SILVER);
  float2 res = float2(1e5, M_SILVER);
  // mount: chrome tube, flange and three bayonet lugs
  float th = atan2(q.z, q.x);
  float sector = abs(frac(th * 3.0 / TAU + 0.083) - 0.5) * (TAU / 3.0) * r;
  float lug = max(ring(ry, 1.98, 2.44, -0.52, -0.40, 0.02), sector - 0.95);
  float tube = ring(ry, 1.95, 2.33, -0.40, 0.02, 0.03);
  float flange = ring(ry, 2.2, 2.6, -0.09, 0.0, 0.02);
  res = opU(res, float2(min(min(lug, tube), flange), M_CHROME));
  // rear barrel: narrower than the rings above it, its foot broken wide
  res = opU(res, float2(ring(ry, 2.2, 2.78, 0.03, 1.36, 0.1), M_SILVER));
  // aperture ring with its ridged grip
  float ar = ring(ry, 2.25, 2.95, 1.42, 2.52, 0.05);
  if (y > 1.5 && y < 1.98 && r > 2.75) ar += ridgeH(q, lodFade(q, 0.105)) * smoothstep(1.5, 1.56, y) * smoothstep(1.98, 1.92, y);
  res = opU(res, float2(ar, (y > 1.49 && y < 1.99 && r > 2.85) ? M_RIDGE : M_SILVER));
  // the fixed scale ring (black anodised)
  res = opU(res, float2(ring(ry, 2.25, 2.84, 2.58, 3.04, 0.035), M_BLACK));
  // focus ring: a smooth scale band, a step, the knurl: the widest part
  float fr = ring(ry, 2.25, 3.08, 3.10, 5.62, 0.06);
  float step = ring(ry, 2.25, 3.13, 3.80, 5.46, 0.05);
  fr = min(fr, step);
  if (y > 3.8 && y < 5.46 && r > 2.95) fr += knurlH(q, y, lodFade(q, 0.2)) * smoothstep(3.84, 3.9, y) * smoothstep(5.42, 5.36, y);
  res = opU(res, float2(fr, (y > 3.83 && y < 5.43 && r > 3.03) ? M_KNURL : M_SILVER));
  // front barrel: tapering toward the front, two fine turned grooves
  float R = 3.0 - (clamp(y, 5.68, 6.96) - 5.68) * 0.055;
  float fb = box2(ry - float2((2.2 + R) * 0.5, 6.32), float2((R - 2.2) * 0.5, 0.64), 0.06);
  float gr = min(box2(ry - float2(R, 6.5), float2(0.02, 0.012), 0.008), box2(ry - float2(R, 6.64), float2(0.02, 0.012), 0.008));
  fb = max(fb, -gr);
  res = opU(res, float2(fb, M_SILVER));
  // a thin ring of orange anodising under the name ring
  res = opU(res, float2(ring(ry, 2.6, 2.935, 6.965, 7.055, 0.012), M_ORANGE));
  // the name ring: black, its front face engraved
  float nr = ring(ry, 2.22, 2.92, 7.06, 7.24, 0.04);
  res = opU(res, float2(nr, M_BLACK));
  // the inside: a light trap lining the metal (the innermost surface)
  float inner = ring(ry, 2.15, 2.27, 0.05, 7.2, 0.01);
  res = opU(res, float2(inner, M_FLOCK));
  return res;
}

// ------------------------------------------------------------------ the scene
static const float FLOOR_Y = 0.0;
float2 mapScene(float3 p, bool withGlass) {
  float2 res = float2(p.y - FLOOR_Y, M_FLOOR);
#ifdef NO_FLOOR
  res.x = 1e5;
#endif
  float3 q = toLens(p);
  res = opU(res, barrelMap(q));
  float rq = length(q.xz);
  if (rq < 2.4) {
    res = opU(res, float2(irisMap(q), M_IRIS));
    // the G1 retaining ring travels with the front element
    float y1 = q.y - groupShift(0);
    res = opU(res, float2(ring(float2(rq, y1), 2.02, 2.2, 6.58, 6.68, 0.01), M_FLOCK));
    if (withGlass) res = opU(res, glassMap(q));
  } else if (withGlass) {
    res = opU(res, float2(rq - 2.3, M_GLASS));
  }
  return res;
}
float2 map(float3 p) { return mapScene(p, true); }

float3 calcNormal(float3 p) {
  float2 e = float2(0.0007, -0.0007);
  return normalize(e.xyy * map(p + e.xyy).x + e.yyx * map(p + e.yyx).x + e.yxy * map(p + e.yxy).x + e.xxx * map(p + e.xxx).x);
}
float3 glassNormal(float3 p) {
  float2 e = float2(0.0006, -0.0006);
  float3 q = toLens(p);
  // gradient in lens space, turned back to the world
  float3 n = e.xyy * glassMap(q + e.xyy).x + e.yyx * glassMap(q + e.yyx).x + e.yxy * glassMap(q + e.yxy).x + e.xxx * glassMap(q + e.xxx).x;
  return normalize(lensToWorldDir(n));
}
float2 march(float3 ro, float3 rd, float maxd, bool withGlass) {
  float t = 0.0;
  for (int i = 0; i < 200; i++) {
    float2 h = mapScene(ro + rd * t, withGlass);
    if (abs(h.x) < 0.00025 * t + 0.0004) return float2(t, h.y);
    t += h.x * 0.85;
    if (t > maxd) break;
  }
  return float2(-1.0, 0.0);
}

// ------------------------------------------------------------------ the studio
// A softbox seen in direction d: a rounded rectangle on the plane facing the
// lens, its edges softened by `blur` (roughness widens it, keeping its energy).
float window1(float x, float a, float e) { return smoothstep(-a - e, -a + e, x) - smoothstep(a - e, a + e, x); }
// A softbox seen in direction d: a rectangle on the plane facing the lens,
// brighter at its centre, its edges softened by `blur` (roughness widens
// them, keeping the energy).
float softbox(float3 d, float3 c, float3 up, float2 half_, float blur) {
  float k = dot(d, c);
  if (k <= 0.02) return 0.0;
  float3 rt = normalize(cross(up, c));
  float3 u2 = cross(c, rt);
  float2 uv = float2(dot(d, rt), dot(d, u2)) / k;
  float fall = 1.0 - 0.45 * dot(uv / half_, uv / half_) * 0.5;
  return window1(uv.x, half_.x, 0.012 + blur) * window1(uv.y, half_.y, 0.012 + blur) * max(fall, 0.3);
}
// The light cue (param 13): 0..1 the rim strips outline the lens, 1..2 a
// strip sweeps across its front, 1.8..3 the studio comes up (overlapping it).
float rimAmt() { return saturate(param(13)); }
float sweepAmt() { return saturate(param(13) - 1.0); }
float studioAmt() { return saturate((param(13) - 1.8) / 1.2); }
#ifndef ENV_YAW
#define ENV_YAW 0.0
#endif
float3 env(float3 d, float blur) {
  d = rotY(d, radians(ENV_YAW));
  float s = studioAmt();
  float rim = rimAmt();
#ifdef STUDIO_SCALE
  float big = s * STUDIO_SCALE;
#else
  float big = s;
#endif
#ifdef RIM_SCALE
  rim *= RIM_SCALE;
#endif
  // the dark room: a little light up high, nearly black low down
  float3 c = lerp(float3(0.004, 0.004, 0.0042), float3(0.02, 0.0195, 0.019), saturate(d.y * 0.8 + 0.3)) * (0.15 + 0.85 * s);
  // key: a big box front left, high
  c += float3(1.0, 0.975, 0.94) * 2.6 * big * softbox(d, normalize(float3(-0.62, 0.5, 0.6)), float3(0, 1, 0), float2(0.55, 0.62), blur);
  // overhead scrim: broad and soft
  c += float3(0.95, 0.965, 1.0) * 1.5 * big * softbox(d, float3(0.0, 1.0, 0.0), float3(0, 0, -1), float2(1.1, 0.8), blur);
  // fill: a white card front right
  c += float3(1.0, 0.99, 0.97) * 0.75 * big * softbox(d, normalize(float3(0.7, 0.12, 0.7)), float3(0, 1, 0), float2(0.42, 0.55), blur);
  // two tall strips behind, one each side: the rims
  c += float3(0.93, 0.96, 1.0) * 6.5 * rim * softbox(d, normalize(float3(-0.9, 0.1, -0.42)), float3(0, 1, 0), float2(0.07, 1.0), blur);
  c += float3(1.0, 0.97, 0.94) * 5.5 * rim * softbox(d, normalize(float3(0.88, 0.14, -0.46)), float3(0, 1, 0), float2(0.055, 1.0), blur);
#ifdef LIGHTBOX
  // a small square box just over the camera's shoulder: the glints in the glass
  c += float3(1.0, 0.98, 0.95) * LIGHTBOX * softbox(d, normalize(LIGHTBOX_DIR), float3(0, 1, 0), float2(0.085, 0.085), blur);
#endif
#ifdef BACKLIGHT
#ifndef BACKLIGHT_COLOR
#define BACKLIGHT_COLOR float3(1.0, 0.9, 0.78)
#endif
  // a round light hidden behind the lens: seen only through it
  float bl = dot(d, normalize(BACKLIGHT_DIR));
  c += BACKLIGHT_COLOR * BACKLIGHT * smoothstep(0.3, 0.85, bl) * (0.6 + 0.4 * smoothstep(0.85, 1.0, bl));
#endif
  // the sweep: one strip that travels round the front of the lens
  float sw = sweepAmt();
  if (sw > 0.0 && sw < 1.0) {
    float a = lerp(-1.9, 1.6, sw);
    float3 sd = normalize(float3(sin(a), 0.22, cos(a)));
    c += float3(1.0, 0.98, 0.95) * 9.0 * softbox(d, sd, float3(0, 1, 0), float2(0.07, 1.2), blur) * smoothstep(0.0, 0.1, sw) * smoothstep(1.0, 0.8, sw) * (1.0 - s);
  }
  return c;
}
float3 envKeyDir() { return rotY(normalize(float3(-0.62, 0.5, 0.6)), -radians(ENV_YAW)); }

// What the camera sees past everything: a dark seamless sweep with a soft
// pool of light behind the lens.
float3 backdrop(float3 rd) {
  float s = max(studioAmt(), rimAmt() * 0.25);
  float3 base = float3(0.006, 0.0062, 0.0068);
  float3 toL = normalize(float3(0.0, 4.6, 0.0) - gEye);
  float halo = exp(-(1.0 - dot(rd, toL)) * 7.0);
  float3 c = base * (0.35 + 0.65 * s) + float3(0.03, 0.029, 0.028) * halo * s;
#ifdef BACKLIGHT
  // the panel behind lights the wall a little too
  c += float3(0.92, 0.93, 0.95) * BACKLIGHT * 0.03 * exp(-(1.0 - dot(rd, toL)) * 4.0);
#endif
  return c;
}

// ------------------------------------------------------------------ engravings
// Input 0 is an atlas of the engraved scales, drawn as ordinary text: four
// bands, each a range of ring angles across the frame's width and a range of
// heights (or radii) down its rows (BANDS in product.py holds the same numbers).
float wrapInto(float a, float a0) { return a0 + fmod(fmod(a - a0, 360.0) + 360.0, 360.0); }
float4 atlasBand(float alpha, float h, float a0, float a1, float h0, float h1, float r0, float r1, bool ltr) {
  float a = wrapInto(alpha, a0);
  if (a > a1) return float4(0.0, 0.0, 0.0, 0.0);
  float t = (h0 - h) / (h0 - h1);
  if (t < 0.0 || t > 1.0) return float4(0.0, 0.0, 0.0, 0.0);
  float x = ltr ? (a - a0) / (a1 - a0) : (a1 - a) / (a1 - a0);
  return input(0, float2(x * 1920.0, r0 + t * (r1 - r0)));
}
float4 engraving(float3 q, float3 n, float id) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float th = degrees(atan2(q.z, q.x));
  if (id < 1.5) {
    if (r > 3.0 && y > 3.12 && y < 3.78) return atlasBand(th + param(11), y, 60.0, 260.0, 3.76, 3.14, 0.0, 111.0, false);
    if (r > 2.92 && y > 2.0 && y < 2.5) return atlasBand(th + param(12) * 12.0, y, 70.0, 200.0, 2.47, 2.02, 130.0, 257.0, false);
  } else if (id < 3.5) {
    if (r > 2.8 && y > 2.58 && y < 3.04) return atlasBand(th, y, 50.0, 130.0, 3.02, 2.60, 300.0, 521.0, false);
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    if (y > 7.15 && ax > 0.9) return atlasBand(th, r, 150.0, 390.0, 2.88, 2.40, 540.0, 620.0, true);
  }
  return float4(0.0, 0.0, 0.0, 0.0);
}

// ------------------------------------------------------------------ surfaces
struct Surf { float3 albedo; float metal; float rough; float aniso; float cavity; };

Surf surface(float id, float3 p, float3 q, float3 n) {
  Surf s;
  s.albedo = float3(0.8, 0.8, 0.8); s.metal = 0.0; s.rough = 0.5; s.aniso = 0.0; s.cavity = 0.0;
  float r = length(q.xz);
  float y = q.y - barrelShift();
  if (id < 1.5) {               // turned, bead-blasted aluminium, clear anodised
    // bead-blasted, clear anodised; the edges are diamond-cut and polished
    s.albedo = float3(0.9, 0.905, 0.91); s.metal = 1.0; s.aniso = 0.8;
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    float chamfer = smoothstep(0.12, 0.3, ax) * smoothstep(0.995, 0.95, ax);
    s.rough = lerp(0.5 + 0.06 * snoise(q * 40.0), 0.12, chamfer);
    s.aniso = lerp(0.8, 0.2, chamfer);
    // the mounting index: an orange dot on the rear barrel, facing the scales
    float dotd = length(float2((atan2(q.z, q.x) - 1.5708) * r, y - 0.72));
    float dotc = smoothstep(0.075, 0.062, dotd) * step(r, 2.8) * step(2.7, r);
    s.albedo = lerp(s.albedo, float3(0.8, 0.14, 0.035), dotc); s.metal = lerp(s.metal, 0.0, dotc); s.rough = lerp(s.rough, 0.6, dotc);
  } else if (id < 2.5) {        // knurl: same metal, sharper facets
    s.albedo = float3(0.86, 0.865, 0.87); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.2));
  } else if (id < 3.5) {        // black anodised: a dielectric skin over metal
    s.albedo = float3(0.02, 0.02, 0.022); s.metal = 0.0; s.rough = 0.42 + 0.04 * snoise(q * 30.0);
  } else if (id < 4.5) {        // chrome-plated brass mount
    s.albedo = float3(0.95, 0.95, 0.96); s.metal = 1.0; s.rough = 0.06;
  } else if (id < 5.5) {        // glass (handled by the glass path)
    s.albedo = float3(1.0, 1.0, 1.0); s.metal = -1.0; s.rough = 0.0;
  } else if (id < 6.5) {        // flocking: the inside eats light
    s.albedo = float3(0.006, 0.006, 0.007); s.metal = 0.0; s.rough = 0.9;
  } else if (id < 7.5) {        // iris blades: blackened steel with a sheen
    s.albedo = float3(0.035, 0.035, 0.04); s.metal = 0.0; s.rough = 0.26;
    float ang = atan2(q.z, q.x);
    float x = (ang / TAU) * 11.0 + log(max(r, 0.05)) * 1.9;
    float seam = tri(x);
    float blade = floor(x + 0.5);
    s.albedo = float3(0.03, 0.03, 0.034) * (0.6 + 0.8 * frac(sin(blade * 12.9898) * 43758.5453));
    s.rough = 0.22;
    s.albedo *= 0.35 + 0.65 * smoothstep(0.0, 0.1, seam);
  } else if (id < 8.5) {        // black acrylic floor
    s.albedo = float3(0.014, 0.014, 0.015) * (0.9 + 0.1 * fbm2(p.xz * 0.6)); s.metal = 0.0; s.rough = 0.28;
  } else if (id < 9.5) {        // inked edges of the glass
    s.albedo = float3(0.012, 0.012, 0.013); s.metal = 0.0; s.rough = 0.6;
  } else if (id > 12.5 && id < 13.5) {  // a ground glass edge, milky
    s.albedo = float3(0.42, 0.45, 0.44); s.metal = 0.0; s.rough = 0.55;
  } else if (id > 11.5 && id < 12.5) {  // orange anodised aluminium
    s.albedo = float3(0.92, 0.3, 0.085); s.metal = 1.0; s.rough = 0.3; s.aniso = 0.5;
  } else if (id < 10.5) {       // ridges of the aperture ring
    s.albedo = float3(0.88, 0.885, 0.89); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.105));
  }
  // engraved and filled with paint
  if (id < 3.5 && id != 2.0) {
    float4 e = engraving(q, n, id);
    if (e.a > 0.002) {
      // white in the atlas is the primary fill: black on silver, white on black
      float3 ink = e.rgb / e.a;
      float white = saturate((ink.b - 0.5) * 4.0);
      float3 primary = id < 1.5 ? float3(0.005, 0.005, 0.0055) : float3(0.78, 0.78, 0.76);
      ink = lerp(ink * 0.85, primary, white);
      s.albedo = lerp(s.albedo, ink, e.a);
      s.metal = lerp(s.metal, 0.0, e.a);
      s.rough = lerp(s.rough, 0.85, e.a);
      s.aniso *= 1.0 - e.a;
      s.cavity = e.a;
      s.albedo *= 1.0 - 2.0 * e.a * (1.0 - e.a);     // the walls of the cut
    }
  }
  return s;
}

// ------------------------------------------------------------------ light
float softShadow(float3 ro, float3 rd, float k) {
  float res = 1.0, t = 0.02;
  for (int i = 0; i < 48; i++) {
    float h = mapScene(ro + rd * t, false).x;
    res = min(res, k * h / t);
    t += clamp(h, 0.02, 0.6);
    if (res < 0.002 || t > 30.0) break;
  }
  return saturate(res);
}
float ambientOcc(float3 p, float3 n) {
  float occ = 0.0, sca = 1.0;
  for (int i = 0; i < 5; i++) {
    float h = 0.02 + 0.12 * float(i);
    occ += (h - map(p + n * h).x) * sca;
    sca *= 0.7;
  }
  return saturate(1.0 - 1.6 * occ);
}
float3 fresnelS(float3 f0, float nv, float rough) {
  return f0 + (max(float3(1.0 - rough, 1.0 - rough, 1.0 - rough), f0) - f0) * pow(1.0 - nv, 5.0);
}

// Light reflected by a surface (one bounce of the studio): simple, for what
// glass and mirrors see.
float3 shadeSimple(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float3 r = reflect(-v, n);
  float3 kd = s.albedo * (1.0 - max(s.metal, 0.0));
  float key = studioAmt() * saturate(dot(n, envKeyDir()));
  if (id > 7.5 && id < 8.5 && abs(param(14)) < 1.0) kd *= smoothstep(2.4, 3.4, length(p.xz - LENS_ORIGIN.xz));
  if (id > 7.5 && id < 8.5 && key > 0.0) key *= softShadow(p + n * 0.01, envKeyDir(), 6.0);
  float3 diff = kd * (env(n, 0.9) * 1.2 + float3(1.0, 0.97, 0.94) * 2.2 * key);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, max(s.metal, 0.0));
  float3 spec = env(r, s.rough * s.rough * 3.2) * fresnelS(f0, saturate(dot(n, v)), s.rough);
  return diff + spec;
}

// Thin-film anti-reflection coating: a faint reflection that leans green
// head-on and magenta toward the edge, a different cast on each surface.
float3 coatF(float cosi, float k) {
  float h = frac(k * 0.37 + (1.0 - cosi) * 0.6);
  float3 tint = h < 0.5 ? lerp(float3(0.3, 1.0, 0.5), float3(0.9, 0.4, 1.0), h * 2.0) : lerp(float3(0.9, 0.4, 1.0), float3(0.3, 1.0, 0.5), h * 2.0 - 1.0);
  float3 r0 = 0.004 + 0.02 * tint;
  return r0 + (1.0 - r0) * pow(1.0 - cosi, 5.0);
}

#define GLASS_IOR 1.62
// Light through the optics: refract in, cross each element, refract out,
// gathering each surface's coated reflection of the studio on the way.
float3 glassPath(float3 pos, float3 dir, float3 n) {
  float3 col = float3(0.0, 0.0, 0.0);
  float3 thr = float3(1.0, 1.0, 1.0);
  float3 dir0 = dir;
  bool inside = false;
  float3 nn = n;                 // faces against the ray
  float3 axis = lensToWorldDir(float3(0.0, 1.0, 0.0));
  float open = ease(explode() * 3.0);
  for (int k = 0; k < 16; k++) {
    float cosi = saturate(-dot(dir, nn));
    float3 F = coatF(cosi, float(k));
    float3 rdir = reflect(dir, nn);
    // inside the barrel a reflection only sees the studio through the front
    float esc = k == 0 ? 1.0 : lerp(smoothstep(0.8, 0.97, dot(rdir, axis)), 1.0, open);
    col += thr * F * (inside ? 0.35 : 1.0) * env(rdir, 0.0) * esc;
    thr *= 1.0 - F;
    float3 t = refract(dir, nn, inside ? GLASS_IOR : 1.0 / GLASS_IOR);
    bool tir = dot(t, t) < 1e-5;
    if (tir) { dir = rdir; } else { dir = t; inside = !inside; }
    // step off the surface to the side the ray now travels
    pos += (dot(dir, nn) < 0.0 ? -nn : nn) * 0.0025;
    if (inside) {
      // through the glass to where the ray leaves it
      float s = 0.0;
      float2 g = float2(-1.0, M_GLASS);
      for (int i = 0; i < 80; i++) {
        g = glassMap(toLens(pos + dir * s));
        if (-g.x < 0.0003 || s > 8.0) break;
        s += max(-g.x, 0.0015);
      }
      pos += dir * s;
      if (g.y > 8.5) return col;          // out through an edge: lost
      nn = -glassNormal(pos);
      thr *= float3(0.985, 0.99, 0.982);  // a whisper of green from the glass itself
#ifndef FULL_TRACE
      if (explode() < 0.001) {
        // leave the front element, then the inside of the lens; light
        // trapped in the glass is lost
        float3 t2 = refract(dir, nn, GLASS_IOR);
        if (dot(t2, t2) < 1e-5) return col;
        float c2 = saturate(-dot(dir, nn));
        float3 F2 = coatF(c2, 1.0);
        col += thr * min(F2, float3(0.03, 0.03, 0.03)) * 0.35 * env(reflect(dir, nn), 0.0) * smoothstep(0.8, 0.97, dot(reflect(dir, nn), axis));
        return col + thr * (1.0 - F2) * lensInterior(pos - nn * 0.003, t2);
      }
#endif
    } else {
      float2 h = march(pos, dir, 60.0, true);
      if (h.x < 0.0) {
        // out of the lens into the studio, split by wavelength
        float3 dev = (dir - dir0) * 0.06;
        col += thr * float3(env(dir - dev, 0.0).r, env(dir, 0.0).g, env(dir + dev, 0.0).b);
        return col;
      }
      pos = pos + dir * h.x;
      if (h.y > 4.5 && h.y < 5.5) {
        nn = glassNormal(pos);
      } else {
        col += thr * shadeSimple(pos, calcNormal(pos), -dir, h.y);
        return col;
      }
    }
  }
  return col;
}


// ------------------------------------------------------------------ inside the assembled lens
// Past the front element the light is followed along a straight line: every
// inner surface it crosses adds its coated ghost of the studio, the iris
// stops it or lets it through, the barrel's black walls swallow the rest.
// (A full trace through eight curved elements is correct and unreadable.)
float3 dirToLens(float3 v) { return rotY(rotZ(v, -tilt()), -spin()); }
// sphere surfaces of the inner elements: centre height, radius, clear radius, coating hue
static const float4 GHOSTS[10] = {
  float4(2.85, 3.4, 1.85, 0.1), float4(3.05, 2.4, 1.85, 0.55), float4(2.6, 2.6, 1.5, 0.8), float4(2.8, 2.0, 1.5, 0.3),
  float4(5.5, 2.2, 1.45, 0.65), float4(5.7, 3.2, 1.45, 0.2), float4(-1.95, 4.0, 1.55, 0.9), float4(4.65, 3.5, 1.55, 0.45),
  float4(6.75, 6.0, 1.4, 0.7), float4(2.35, 2.2, 1.4, 0.05) };
static const float2 GHOST_Y[10] = {           // the y range each surface occupies
  float2(5.7, 6.26), float2(4.57, 5.46), float2(4.7, 5.21), float2(4.1, 4.81),
  float2(3.29, 3.86), float2(2.49, 2.86), float2(1.73, 2.06), float2(1.14, 1.52), float2(0.74, 0.93), float2(0.14, 0.66) };
float3 lensInterior(float3 pw, float3 dw) {
  float3 o = toLens(pw);
  float3 d = normalize(dirToLens(dw));
  float3 col = float3(0.0, 0.0, 0.0);
  float yIris = 3.95;
  // where the ray meets the black inner wall (r = 2.12)
  float a = dot(d.xz, d.xz), b = dot(o.xz, d.xz), c = dot(o.xz, o.xz) - 2.12 * 2.12;
  float tWall = a > 1e-6 ? (-b + sqrt(max(b * b - a * c, 0.0))) / a : 1e5;
  float tIris = d.y < -1e-4 ? (yIris - o.y) / d.y : 1e5;
  float3 axisW = lensToWorldDir(float3(0.0, 1.0, 0.0));
  for (int i = 0; i < 10; i++) {
    float4 g = GHOSTS[i];
    float3 oc = o - float3(0.0, g.x, 0.0);
    float bb = dot(oc, d), cc = dot(oc, oc) - g.y * g.y;
    float disc = bb * bb - cc;
    if (disc < 0.0) continue;
    float sq = sqrt(disc);
    for (int k = 0; k < 2; k++) {
      float t = -bb + (k == 0 ? -sq : sq);
      if (t <= 0.0 || t > tWall) continue;
      float3 h = o + d * t;
      if (h.y < GHOST_Y[i].x || h.y > GHOST_Y[i].y || length(h.xz) > g.z) continue;
      // behind the iris only what the iris lets through counts
      if (h.y < yIris && (t > tIris && irisHole(o.xz + d.xz * tIris) > 0.0)) continue;
      float3 n = normalize(h - float3(0.0, g.x, 0.0));
      if (dot(n, d) > 0.0) n = -n;
      float3 rw = lensToWorldDir(reflect(d, n));
      float cosi = saturate(-dot(d, n));
      // coatings leave green, magenta or amber, shifting a little with angle
      float hue = frac(g.w + (1.0 - cosi) * 0.25);
      float3 tint = hue < 0.33 ? lerp(float3(0.25, 1.0, 0.45), float3(0.95, 0.35, 1.0), hue * 3.0)
                  : hue < 0.66 ? lerp(float3(0.95, 0.35, 1.0), float3(1.0, 0.62, 0.22), hue * 3.0 - 1.0)
                               : lerp(float3(1.0, 0.62, 0.22), float3(0.25, 1.0, 0.45), hue * 3.0 - 2.0);
      float esc = smoothstep(0.82, 0.97, dot(rw, axisW));
      col += tint * 0.022 * env(rw, 0.035) * esc;
    }
  }
  if (tIris < tWall) {
    float3 h = o + d * tIris;
    if (irisHole(h.xz) > 0.0) {
      // a blade: blackened steel, lit by what comes in through the front
      float3 hw = LENS_ORIGIN + float3(0.0, PIVOT_Y, 0.0) + rotZ(rotY(h, spin()) - float3(0.0, PIVOT_Y, 0.0), tilt());
      float blade = floor(atan2(h.z, h.x) / TAU * 11.0 + log(max(length(h.xz), 0.05)) * 1.9 + 0.5);
      float3 rad = normalize(float3(h.x, 0.0, h.z) + 1e-5);
      float3 tan_ = float3(-rad.z, 0.0, rad.x);
      float3 nb = normalize(float3(0.0, 1.0, 0.0) + tan_ * (0.16 * sin(blade * 2.39)) + rad * 0.07);
      return col + shadeSimple(hw, lensToWorldDir(nb), -dw, M_IRIS) * 0.9;
    }
    // through the opening and out of the back: the floor under a standing
    // lens is dark; otherwise whatever lies behind
    if (abs(param(14)) < 1.0) return col;
    float3 dd = dw * 1.0;
    return col + env(dd, 0.0) * 0.9;
  }
  return col;     // the inner wall
}

// The full light at a surface the camera sees.
float3 shadeFull(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float nv = saturate(dot(n, v));
  float occ = ambientOcc(p, n);
  float3 kd = s.albedo * (1.0 - s.metal);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, s.metal);
  float3 F = fresnelS(f0, nv, s.rough);
  // diffuse: the key box (with its shadow) and the room
  float3 L = envKeyDir();
  float nl = saturate(dot(n, L));
  float sh = nl > 0.0 ? softShadow(p + n * 0.004, L, 6.0) : 0.0;
  float pool = id > 7.5 && id < 8.5 ? exp(-dot(p.xz, p.xz) / 260.0) : 1.0;
  float3 diff = kd * (float3(1.0, 0.975, 0.94) * 2.4 * studioAmt() * nl * sh + env(n, 0.9) * 1.3 * occ) * pool;
  // specular: the studio, blurred by roughness; turned metal smears it
  // along the axis of the lens
  float3 r = reflect(-v, n);
  float blur = s.rough * s.rough * 3.2;
  float3 spec;
  if (s.aniso > 0.0) {
    float3 ax = lensToWorldDir(float3(0.0, 1.0, 0.0));
    float3 rad = lensToWorldDir(normalize(float3(q.x, 0.0, q.z) + 1e-5));
    float3 tg = normalize(cross(ax, rad));
    float3 b = normalize(cross(n, tg) + 1e-5);
    spec = float3(0.0, 0.0, 0.0);
    for (int i = -2; i <= 2; i++) {
      float3 nn = normalize(n + b * (float(i) * 0.09 * s.aniso));
      spec += env(reflect(-v, nn), blur * 0.7);
    }
    spec *= 0.2;
  } else {
    spec = env(r, blur);
  }
  // glossy things see the scene, not just the studio
  if (s.rough < 0.3 || (id > 7.5 && id < 8.5)) {
    float2 h = march(p + n * 0.006, r, 40.0, true);
    if (h.x > 0.0) {
      float3 hp = p + n * 0.006 + r * h.x;
      float3 hn = calcNormal(hp);
      float3 hit = (h.y > 4.5 && h.y < 5.5) ? env(reflect(r, hn), 0.0) * 0.1 : shadeSimple(hp, hn, -r, h.y);
      // a rough floor blurs what it reflects the farther it is
      float keep = id > 7.5 && id < 8.5 ? exp(-h.x * 1.1) * 0.35 : 1.0;
      spec = lerp(spec, hit, keep);
    }
  }
  float specOcc = lerp(occ, 1.0, 0.35) * (1.0 - 0.7 * s.cavity);
  return diff * (1.0 - 0.5 * s.cavity) + spec * F * specOcc;
}

// ------------------------------------------------------------------ camera, samples, focus
#ifndef SAMPLES
#define SAMPLES 2
#endif
#ifndef FILTER_SIGMA
#define FILTER_SIGMA 0.5
#endif
// filmic tone curve
float3 filmic(float3 c) {
  return saturate((c * (2.51 * c + 0.03)) / (c * (2.43 * c + 0.59) + 0.14));
}
float4 shade(float2 pos, float px) {
  float2 sz = size();
  float3 target = float3(param(3), param(4), param(5));
  float az = radians(param(0)), el = radians(param(1));
  float3 eye = target + param(2) * float3(sin(az) * cos(el), sin(el), cos(az) * cos(el));
  gEye = eye;
  float3 fw = normalize(target - eye);
  float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
  float3 up = cross(rt, fw);
  float focal = 1.0 / tan(radians(param(6)) * 0.5);
  gPix = 2.0 / (focal * sz.y);
  float3 acc = float3(0.0, 0.0, 0.0);
  float depth = 1e4;
  float jit = hash12(pos * 0.37 + frac(time() * 7.13));
  // The pixel's footprint is a Gaussian (sigma FILTER_SIGMA px, cut at 3 sigma),
  // sampled on a golden-angle spiral with radii drawn from its distribution:
  // edges roll off over about a pixel, as through real glass and a sensor's
  // low-pass filter, instead of stepping. Each sample is tone-mapped before
  // the average, so a sub-pixel glint on a knurl ridge adds its share of the
  // pixel instead of flashing the whole pixel white from one frame to the next.
  float cut = 1.0 - exp(-4.5);
  for (int s = 0; s < SAMPLES; s++) {
    float u = (float(s) + 0.5) / float(SAMPLES);
    float rr = FILTER_SIGMA * sqrt(-2.0 * log(1.0 - u * cut));
    float a = float(s) * 2.39996323 + jit * TAU;
    float2 o = SAMPLES > 1 ? float2(cos(a), sin(a)) * rr : float2(0.0, 0.0);
    float2 qq = (pos + o - sz * 0.5) / (sz.y * 0.5);
    float3 rd = normalize(fw * focal + rt * qq.x - up * qq.y);
    float2 hit = march(eye, rd, 400.0, true);
    float3 c;
    if (hit.x < 0.0) {
      c = backdrop(rd);
    } else {
      float3 p = eye + rd * hit.x;
      if (s == 0) depth = hit.x;
      if (hit.y > 4.5 && hit.y < 5.5) {
        c = glassPath(p, rd, glassNormal(p));
      } else {
        float3 n = calcNormal(p);
        c = shadeFull(p, n, -rd, hit.y);
        // the floor melts into the backdrop with distance
        if (hit.y > 7.5 && hit.y < 8.5) c = lerp(c, backdrop(rd), saturate((hit.x - 40.0) / 80.0));
      }
    }
    acc += filmic(c * param(9));
  }
  float3 col = acc / float(SAMPLES);
  float coc = param(8) * (1.0 - param(7) / max(depth, 0.01));
  return float4(col, clamp(coc, -48.0, 48.0));
}

// Depth of field after the render: the scene's alpha is its signed circle of
// confusion in px (+ behind the focus plane, - in front of it). Each pixel
// gathers the pixels whose discs reach it, on a golden-angle spiral; what lies
// behind may not bleed over what is sharper in front. Bright points open into
// discs, as through a fast lens.
static const float GOLDEN = 2.39996323;
static const float TAU = 6.28318531;
float4 shade(float2 pos, float px) {
  float4 c0 = input(0, pos);
  float coc0 = abs(c0.a);
  // How far this pixel must look: its own disc, or a neighbour's that reaches it.
  float reach = coc0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * (TAU / 16.0) + 0.3;
    float d = (i & 1) == 0 ? 14.0 : 30.0;
    float n = input(0, pos + float2(cos(a), sin(a)) * d).a;
    float c = n > c0.a ? min(abs(n), coc0 * 2.0) : abs(n);
    if (c > d * 0.6) reach = max(reach, c);
  }
  if (reach < 0.75) return float4(c0.rgb, 1.0);
  float3 acc = c0.rgb;
  float tot = 1.0;
  float ang = frac(sin(dot(pos, float2(12.9898, 78.233))) * 43758.5453) * TAU;
  float r = 0.75;
  float scale = reach > 20.0 ? 1.6 : 0.9;
  for (int k = 0; k < 420; k++) {
    if (r > reach + 0.5) break;
    float2 tp = pos + float2(cos(ang), sin(ang)) * r;
    float4 s = input(0, tp);
    float sc = abs(s.a);
    if (s.a > c0.a) sc = min(sc, coc0 * 2.0);
    float m = smoothstep(r - 0.75, r + 0.75, sc);
    // wide discs of bright points carry more weight: bokeh
    float hot = smoothstep(0.8, 1.0, max(s.r, max(s.g, s.b))) * smoothstep(6.0, 16.0, sc);
    float w = m * (1.0 + 2.0 * hot);
    acc += s.rgb * w;
    tot += w;
    ang += GOLDEN;
    r += scale / r;
  }
  float3 col = acc / tot;
  return float4(min(col, float3(1.0, 1.0, 1.0)), 1.0);
}

#define SAMPLES 4
// HOLM 35 f/1.4: a camera lens in a photographer's studio, raymarched.
// Units are centimetres. The lens stands on its mount at the origin with its
// optical axis up (+y); the studio is three softboxes, two strip lights and a
// black acrylic floor. Every animated value is a param:
//    0  1  2   camera orbit: azimuth, elevation (degrees), distance
//    3  4  5   camera target
//    6         vertical field of view (degrees)
//    7         focus distance (cm)        8  blur: CoC in px at twice the focus distance
//    9         exposure                   10 explode 0..1 (the optics slide out)
//    11        focus ring turn (degrees)  12 iris, stops closed from f/1.4 (0..7)
//    13        light: 0 dark, 1 the sweep crosses, 2 full studio
//    14        lens tilt about z (deg)    15 lens spin about its axis (deg)
// The image's alpha carries the signed circle of confusion for the dof pass.

static const float PI = 3.14159265;
static const float TAU = 6.28318531;

// ------------------------------------------------------------------ helpers
float3 rotY(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }
float3 rotZ(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x - s * p.y, s * p.x + c * p.y, p.z); }
float hash12(float2 p) { float3 p3 = frac(float3(p.x, p.y, p.x) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return frac((p3.x + p3.y) * p3.z); }
float box2(float2 p, float2 b, float r) { float2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
// A ring turned on a lathe: radii r0..r1, heights y0..y1, its edges broken by e.
float ring(float2 ry, float r0, float r1, float y0, float y1, float e) {
  return box2(ry - float2((r0 + r1) * 0.5, (y0 + y1) * 0.5), float2((r1 - r0) * 0.5, (y1 - y0) * 0.5), e);
}
float2 opU(float2 a, float2 b) { return a.x < b.x ? a : b; }
float fbm2(float2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { s += a * snoise(float3(p, 0.37 * float(i))); p = p * 2.1 + float2(1.7, 9.2); a *= 0.5; } return s; }
float tri(float x) { return abs(frac(x) - 0.5) * 2.0; }        // 1 at integers, 0 halfway
// polynomial smooth min / max: blends a and b over a band k wide
float smin(float a, float b, float k) { float h = max(k - abs(a - b), 0.0) / k; return min(a, b) - h * h * k * 0.25; }
float smax(float a, float b, float k) { return -smin(-a, -b, k); }
float ease(float x) { x = saturate(x); return x * x * (3.0 - 2.0 * x); }

// ------------------------------------------------------------------ materials
#define M_SILVER 1.0
#define M_KNURL 2.0
#define M_BLACK 3.0
#define M_CHROME 4.0
#define M_GLASS 5.0
#define M_FLOCK 6.0
#define M_IRIS 7.0
#define M_FLOOR 8.0
#define M_EDGE 9.0
#define M_RIDGE 10.0
#define M_GOLD 11.0
#define M_ORANGE 12.0
#define M_GROUND 13.0

// ------------------------------------------------------------------ per-pixel camera state
static float3 gEye;
static float gPix;      // world size of one pixel at unit distance

float tilt() { return radians(param(14)); }
float spin() { return radians(param(15)); }
float explode() { return param(10); }

static const float3 LENS_ORIGIN = float3(0.0, 0.52, 0.0);   // the mount flange, in the world
static const float PIVOT_Y = 3.3;                            // where the lens turns when it tilts
float3 toLens(float3 p) {
  float3 q = p - LENS_ORIGIN - float3(0.0, PIVOT_Y, 0.0);
  q = rotZ(q, -tilt());
  q.y += PIVOT_Y;
  return rotY(q, -spin());
}
float3 lensToWorldDir(float3 v) { return rotZ(rotY(v, spin()), tilt()); }

// ------------------------------------------------------------------ the optics
// Eight elements in six groups, front to back. Each: centre height, centre
// thickness, front radius (+ convex), back radius (+ convex), clear radius.
// Exploded, each group slides forward to its own place on the axis.
static const float EXPLODE_BARREL = 3.4;
float groupShift(int g) {
  // front groups leave first; each eases out on its own beat
  static const float DY[7] = { 13.6, 11.9, 10.3, 9.0, 7.7, 6.6, 5.4 };
  float e = explode();
  float k = ease(e * 1.45 - float(g) * 0.075);
  return DY[g] * k;
}
float barrelShift() { return -EXPLODE_BARREL * ease(explode() * 1.3); }

// a spherical surface: + convex toward its side, - concave
float surfFront(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv - R)) - R;
  return max(-R - length(ry - float2(0.0, yv - R)), ry.y - (yv - R));
}
float surfBack(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv + R)) - R;
  return max(-R - length(ry - float2(0.0, yv + R)), (yv + R) - ry.y);
}
float element(float2 ry, float yc, float t, float Rf, float Rb, float a, out float edge) {
  float f = surfFront(ry, yc + t * 0.5, Rf);
  float b = surfBack(ry, yc - t * 0.5, Rb);
  float c = ry.x - a;
  float d = max(max(f, b), c);
  edge = c > max(f, b) - 0.002 ? 1.0 : 0.0;
  return d;
}

// The glass alone (for marching inside it). id = 5 glass, 9 inked edge.
float2 glassMap(float3 q) {
  float r = length(q.xz);
#ifdef CLEAR_EDGES
  const float EDGE_ID = M_GROUND;
#else
  const float EDGE_ID = M_EDGE;
#endif
  if (r > 2.3) return float2(r - 2.2, M_GLASS);
  float2 res = float2(1e5, M_GLASS);
  float edge;
  float y;
  // G1: E1 positive meniscus
  y = q.y - groupShift(0);
  float d = element(float2(r, y), 6.75, 0.5, 4.8, -9.0, 2.12, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G2: E2 + E3 cemented
  y = q.y - groupShift(1);
  d = element(float2(r, y), 6.0, 0.5, 3.4, -6.0, 1.85, edge);
  float e3 = max(max(max(length(float2(r, y) - float2(0.0, -0.25)) - 6.0, 2.4 - length(float2(r, y) - float2(0.0, 3.05))), r - 1.85), 3.05 - y);
  float edge3 = (r - 1.85) > -0.002 ? 1.0 : 0.0;
  d = min(d, e3);
  res = opU(res, float2(d, (edge > 0.5 || edge3 > 0.5) && r > 1.83 ? EDGE_ID : M_GLASS));
  // G3: E4 meniscus
  y = q.y - groupShift(2);
  d = element(float2(r, y), 5.0, 0.4, 2.6, -2.0, 1.5, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G4: E5 + E6 cemented (concave toward the iris)
  y = q.y - groupShift(4);
  float e5 = max(max(2.2 - length(float2(r, y) - float2(0.0, 5.5)), length(float2(r, y) - float2(0.0, 8.05)) - 5.0), r - 1.45);
  float e6 = max(max(5.0 - length(float2(r, y) - float2(0.0, 8.05)), length(float2(r, y) - float2(0.0, 5.7)) - 3.2), r - 1.45);
  e5 = max(e5, y - 3.95);
  d = min(e5, e6);
  res = opU(res, float2(d, r > 1.43 ? EDGE_ID : M_GLASS));
  // G5: E7 biconvex
  y = q.y - groupShift(5);
  d = element(float2(r, y), 1.6, 0.9, 4.0, 3.5, 1.55, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G6: E8, the rear element: its back face aspherical (a fourth-order term
  // flattens it toward the edge)
  y = q.y - groupShift(6);
  float f8 = surfFront(float2(r, y), 0.75, -6.0);
  float b8 = length(float2(r, y) - float2(0.0, 2.35)) - 2.2 + 0.012 * r * r * r * r;
  float c8 = r - 1.4;
  d = max(max(f8, b8), c8);
  res = opU(res, float2(d, c8 > max(f8, b8) - 0.002 ? EDGE_ID : M_GLASS));
  return res;
}

// The iris: eleven rounded blades between G3 and G4.
float irisRadius() { return 1.0 * 1.4 / (1.4 * pow(2.0, param(12) * 0.5)); }
float irisHole(float2 xz) {
  float a = irisRadius();
  float ang = atan2(xz.y, xz.x) + param(12) * 0.06;
  float sec = TAU / 11.0;
  float f = (frac(ang / sec) - 0.5) * sec;
  float rr = length(xz);
  float poly = rr * cos(f) - a;
  return lerp(poly, rr - a * 1.04, 0.55);     // blades are curved: rounder than a polygon
}
float irisMap(float3 q) {
  float y = q.y - 3.95 - groupShift(3);
  float r = length(q.xz);
  float disc = max(abs(y) - 0.022, r - 2.08);
  return max(disc, -irisHole(q.xz));
}

// ------------------------------------------------------------------ the barrel
// Diamond knurl on the focus ring, straight ridges on the aperture ring; both
// fade into a flat average where a pixel is wider than their pitch.
float knurlH(float3 q, float y, float fade) {
  float th = atan2(q.z, q.x) + radians(param(11));
  float u = th * (96.0 / TAU);
  float v = y / 0.2;
  // rolled, not cut: the crests, the valleys and the edges between facets are
  // rounded, so a crest catches the light as a soft line a few pixels wide
  // rather than a sub-pixel glint that flickers as the ring turns
  float h = smin(tri(u + v), tri(u - v), 0.08);
  h = smax(smin(h, 0.93, 0.12), 0.04, 0.08);
  return (h * 0.9 - 0.45) * 0.05 * fade;
}
float ridgeH(float3 q, float fade) {
  float th = atan2(q.z, q.x) + radians(param(12) * 12.0);
  float u = th * (180.0 / TAU);
  float h = smoothstep(0.0, 1.0, tri(u));
  return (h - 0.5) * 0.016 * fade;
}
float lodFade(float3 q, float pitch) {
  float3 e = toLens(gEye) - q;
  float d = length(e);
  float graze = abs(dot(normalize(float3(q.x, 0.0, q.z)), e / d));
  float foot = d * gPix / max(graze, 0.12);
  return smoothstep(pitch * 1.1, pitch * 0.45, foot);
}

float2 barrelMap(float3 q) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float2 ry = float2(r, y);
  float bound = ring(ry, 1.85, 3.25, -0.62, 7.3, 0.0);
  if (bound > 0.25) return float2(bound, M_SILVER);
  float2 res = float2(1e5, M_SILVER);
  // mount: chrome tube, flange and three bayonet lugs
  float th = atan2(q.z, q.x);
  float sector = abs(frac(th * 3.0 / TAU + 0.083) - 0.5) * (TAU / 3.0) * r;
  float lug = max(ring(ry, 1.98, 2.44, -0.52, -0.40, 0.02), sector - 0.95);
  float tube = ring(ry, 1.95, 2.33, -0.40, 0.02, 0.03);
  float flange = ring(ry, 2.2, 2.6, -0.09, 0.0, 0.02);
  res = opU(res, float2(min(min(lug, tube), flange), M_CHROME));
  // rear barrel: narrower than the rings above it, its foot broken wide
  res = opU(res, float2(ring(ry, 2.2, 2.78, 0.03, 1.36, 0.1), M_SILVER));
  // aperture ring with its ridged grip
  float ar = ring(ry, 2.25, 2.95, 1.42, 2.52, 0.05);
  if (y > 1.5 && y < 1.98 && r > 2.75) ar += ridgeH(q, lodFade(q, 0.105)) * smoothstep(1.5, 1.56, y) * smoothstep(1.98, 1.92, y);
  res = opU(res, float2(ar, (y > 1.49 && y < 1.99 && r > 2.85) ? M_RIDGE : M_SILVER));
  // the fixed scale ring (black anodised)
  res = opU(res, float2(ring(ry, 2.25, 2.84, 2.58, 3.04, 0.035), M_BLACK));
  // focus ring: a smooth scale band, a step, the knurl: the widest part
  float fr = ring(ry, 2.25, 3.08, 3.10, 5.62, 0.06);
  float step = ring(ry, 2.25, 3.13, 3.80, 5.46, 0.05);
  fr = min(fr, step);
  if (y > 3.8 && y < 5.46 && r > 2.95) fr += knurlH(q, y, lodFade(q, 0.2)) * smoothstep(3.84, 3.9, y) * smoothstep(5.42, 5.36, y);
  res = opU(res, float2(fr, (y > 3.83 && y < 5.43 && r > 3.03) ? M_KNURL : M_SILVER));
  // front barrel: tapering toward the front, two fine turned grooves
  float R = 3.0 - (clamp(y, 5.68, 6.96) - 5.68) * 0.055;
  float fb = box2(ry - float2((2.2 + R) * 0.5, 6.32), float2((R - 2.2) * 0.5, 0.64), 0.06);
  float gr = min(box2(ry - float2(R, 6.5), float2(0.02, 0.012), 0.008), box2(ry - float2(R, 6.64), float2(0.02, 0.012), 0.008));
  fb = max(fb, -gr);
  res = opU(res, float2(fb, M_SILVER));
  // a thin ring of orange anodising under the name ring
  res = opU(res, float2(ring(ry, 2.6, 2.935, 6.965, 7.055, 0.012), M_ORANGE));
  // the name ring: black, its front face engraved
  float nr = ring(ry, 2.22, 2.92, 7.06, 7.24, 0.04);
  res = opU(res, float2(nr, M_BLACK));
  // the inside: a light trap lining the metal (the innermost surface)
  float inner = ring(ry, 2.15, 2.27, 0.05, 7.2, 0.01);
  res = opU(res, float2(inner, M_FLOCK));
  return res;
}

// ------------------------------------------------------------------ the scene
static const float FLOOR_Y = 0.0;
float2 mapScene(float3 p, bool withGlass) {
  float2 res = float2(p.y - FLOOR_Y, M_FLOOR);
#ifdef NO_FLOOR
  res.x = 1e5;
#endif
  float3 q = toLens(p);
  res = opU(res, barrelMap(q));
  float rq = length(q.xz);
  if (rq < 2.4) {
    res = opU(res, float2(irisMap(q), M_IRIS));
    // the G1 retaining ring travels with the front element
    float y1 = q.y - groupShift(0);
    res = opU(res, float2(ring(float2(rq, y1), 2.02, 2.2, 6.58, 6.68, 0.01), M_FLOCK));
    if (withGlass) res = opU(res, glassMap(q));
  } else if (withGlass) {
    res = opU(res, float2(rq - 2.3, M_GLASS));
  }
  return res;
}
float2 map(float3 p) { return mapScene(p, true); }

float3 calcNormal(float3 p) {
  float2 e = float2(0.0007, -0.0007);
  return normalize(e.xyy * map(p + e.xyy).x + e.yyx * map(p + e.yyx).x + e.yxy * map(p + e.yxy).x + e.xxx * map(p + e.xxx).x);
}
float3 glassNormal(float3 p) {
  float2 e = float2(0.0006, -0.0006);
  float3 q = toLens(p);
  // gradient in lens space, turned back to the world
  float3 n = e.xyy * glassMap(q + e.xyy).x + e.yyx * glassMap(q + e.yyx).x + e.yxy * glassMap(q + e.yxy).x + e.xxx * glassMap(q + e.xxx).x;
  return normalize(lensToWorldDir(n));
}
float2 march(float3 ro, float3 rd, float maxd, bool withGlass) {
  float t = 0.0;
  for (int i = 0; i < 200; i++) {
    float2 h = mapScene(ro + rd * t, withGlass);
    if (abs(h.x) < 0.00025 * t + 0.0004) return float2(t, h.y);
    t += h.x * 0.85;
    if (t > maxd) break;
  }
  return float2(-1.0, 0.0);
}

// ------------------------------------------------------------------ the studio
// A softbox seen in direction d: a rounded rectangle on the plane facing the
// lens, its edges softened by `blur` (roughness widens it, keeping its energy).
float window1(float x, float a, float e) { return smoothstep(-a - e, -a + e, x) - smoothstep(a - e, a + e, x); }
// A softbox seen in direction d: a rectangle on the plane facing the lens,
// brighter at its centre, its edges softened by `blur` (roughness widens
// them, keeping the energy).
float softbox(float3 d, float3 c, float3 up, float2 half_, float blur) {
  float k = dot(d, c);
  if (k <= 0.02) return 0.0;
  float3 rt = normalize(cross(up, c));
  float3 u2 = cross(c, rt);
  float2 uv = float2(dot(d, rt), dot(d, u2)) / k;
  float fall = 1.0 - 0.45 * dot(uv / half_, uv / half_) * 0.5;
  return window1(uv.x, half_.x, 0.012 + blur) * window1(uv.y, half_.y, 0.012 + blur) * max(fall, 0.3);
}
// The light cue (param 13): 0..1 the rim strips outline the lens, 1..2 a
// strip sweeps across its front, 1.8..3 the studio comes up (overlapping it).
float rimAmt() { return saturate(param(13)); }
float sweepAmt() { return saturate(param(13) - 1.0); }
float studioAmt() { return saturate((param(13) - 1.8) / 1.2); }
#ifndef ENV_YAW
#define ENV_YAW 0.0
#endif
float3 env(float3 d, float blur) {
  d = rotY(d, radians(ENV_YAW));
  float s = studioAmt();
  float rim = rimAmt();
#ifdef STUDIO_SCALE
  float big = s * STUDIO_SCALE;
#else
  float big = s;
#endif
#ifdef RIM_SCALE
  rim *= RIM_SCALE;
#endif
  // the dark room: a little light up high, nearly black low down
  float3 c = lerp(float3(0.004, 0.004, 0.0042), float3(0.02, 0.0195, 0.019), saturate(d.y * 0.8 + 0.3)) * (0.15 + 0.85 * s);
  // key: a big box front left, high
  c += float3(1.0, 0.975, 0.94) * 2.6 * big * softbox(d, normalize(float3(-0.62, 0.5, 0.6)), float3(0, 1, 0), float2(0.55, 0.62), blur);
  // overhead scrim: broad and soft
  c += float3(0.95, 0.965, 1.0) * 1.5 * big * softbox(d, float3(0.0, 1.0, 0.0), float3(0, 0, -1), float2(1.1, 0.8), blur);
  // fill: a white card front right
  c += float3(1.0, 0.99, 0.97) * 0.75 * big * softbox(d, normalize(float3(0.7, 0.12, 0.7)), float3(0, 1, 0), float2(0.42, 0.55), blur);
  // two tall strips behind, one each side: the rims
  c += float3(0.93, 0.96, 1.0) * 6.5 * rim * softbox(d, normalize(float3(-0.9, 0.1, -0.42)), float3(0, 1, 0), float2(0.07, 1.0), blur);
  c += float3(1.0, 0.97, 0.94) * 5.5 * rim * softbox(d, normalize(float3(0.88, 0.14, -0.46)), float3(0, 1, 0), float2(0.055, 1.0), blur);
#ifdef LIGHTBOX
  // a small square box just over the camera's shoulder: the glints in the glass
  c += float3(1.0, 0.98, 0.95) * LIGHTBOX * softbox(d, normalize(LIGHTBOX_DIR), float3(0, 1, 0), float2(0.085, 0.085), blur);
#endif
#ifdef BACKLIGHT
#ifndef BACKLIGHT_COLOR
#define BACKLIGHT_COLOR float3(1.0, 0.9, 0.78)
#endif
  // a round light hidden behind the lens: seen only through it
  float bl = dot(d, normalize(BACKLIGHT_DIR));
  c += BACKLIGHT_COLOR * BACKLIGHT * smoothstep(0.3, 0.85, bl) * (0.6 + 0.4 * smoothstep(0.85, 1.0, bl));
#endif
  // the sweep: one strip that travels round the front of the lens
  float sw = sweepAmt();
  if (sw > 0.0 && sw < 1.0) {
    float a = lerp(-1.9, 1.6, sw);
    float3 sd = normalize(float3(sin(a), 0.22, cos(a)));
    c += float3(1.0, 0.98, 0.95) * 9.0 * softbox(d, sd, float3(0, 1, 0), float2(0.07, 1.2), blur) * smoothstep(0.0, 0.1, sw) * smoothstep(1.0, 0.8, sw) * (1.0 - s);
  }
  return c;
}
float3 envKeyDir() { return rotY(normalize(float3(-0.62, 0.5, 0.6)), -radians(ENV_YAW)); }

// What the camera sees past everything: a dark seamless sweep with a soft
// pool of light behind the lens.
float3 backdrop(float3 rd) {
  float s = max(studioAmt(), rimAmt() * 0.25);
  float3 base = float3(0.006, 0.0062, 0.0068);
  float3 toL = normalize(float3(0.0, 4.6, 0.0) - gEye);
  float halo = exp(-(1.0 - dot(rd, toL)) * 7.0);
  float3 c = base * (0.35 + 0.65 * s) + float3(0.03, 0.029, 0.028) * halo * s;
#ifdef BACKLIGHT
  // the panel behind lights the wall a little too
  c += float3(0.92, 0.93, 0.95) * BACKLIGHT * 0.03 * exp(-(1.0 - dot(rd, toL)) * 4.0);
#endif
  return c;
}

// ------------------------------------------------------------------ engravings
// Input 0 is an atlas of the engraved scales, drawn as ordinary text: four
// bands, each a range of ring angles across the frame's width and a range of
// heights (or radii) down its rows (BANDS in product.py holds the same numbers).
float wrapInto(float a, float a0) { return a0 + fmod(fmod(a - a0, 360.0) + 360.0, 360.0); }
float4 atlasBand(float alpha, float h, float a0, float a1, float h0, float h1, float r0, float r1, bool ltr) {
  float a = wrapInto(alpha, a0);
  if (a > a1) return float4(0.0, 0.0, 0.0, 0.0);
  float t = (h0 - h) / (h0 - h1);
  if (t < 0.0 || t > 1.0) return float4(0.0, 0.0, 0.0, 0.0);
  float x = ltr ? (a - a0) / (a1 - a0) : (a1 - a) / (a1 - a0);
  return input(0, float2(x * 1920.0, r0 + t * (r1 - r0)));
}
float4 engraving(float3 q, float3 n, float id) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float th = degrees(atan2(q.z, q.x));
  if (id < 1.5) {
    if (r > 3.0 && y > 3.12 && y < 3.78) return atlasBand(th + param(11), y, 60.0, 260.0, 3.76, 3.14, 0.0, 111.0, false);
    if (r > 2.92 && y > 2.0 && y < 2.5) return atlasBand(th + param(12) * 12.0, y, 70.0, 200.0, 2.47, 2.02, 130.0, 257.0, false);
  } else if (id < 3.5) {
    if (r > 2.8 && y > 2.58 && y < 3.04) return atlasBand(th, y, 50.0, 130.0, 3.02, 2.60, 300.0, 521.0, false);
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    if (y > 7.15 && ax > 0.9) return atlasBand(th, r, 150.0, 390.0, 2.88, 2.40, 540.0, 620.0, true);
  }
  return float4(0.0, 0.0, 0.0, 0.0);
}

// ------------------------------------------------------------------ surfaces
struct Surf { float3 albedo; float metal; float rough; float aniso; float cavity; };

Surf surface(float id, float3 p, float3 q, float3 n) {
  Surf s;
  s.albedo = float3(0.8, 0.8, 0.8); s.metal = 0.0; s.rough = 0.5; s.aniso = 0.0; s.cavity = 0.0;
  float r = length(q.xz);
  float y = q.y - barrelShift();
  if (id < 1.5) {               // turned, bead-blasted aluminium, clear anodised
    // bead-blasted, clear anodised; the edges are diamond-cut and polished
    s.albedo = float3(0.9, 0.905, 0.91); s.metal = 1.0; s.aniso = 0.8;
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    float chamfer = smoothstep(0.12, 0.3, ax) * smoothstep(0.995, 0.95, ax);
    s.rough = lerp(0.5 + 0.06 * snoise(q * 40.0), 0.12, chamfer);
    s.aniso = lerp(0.8, 0.2, chamfer);
    // the mounting index: an orange dot on the rear barrel, facing the scales
    float dotd = length(float2((atan2(q.z, q.x) - 1.5708) * r, y - 0.72));
    float dotc = smoothstep(0.075, 0.062, dotd) * step(r, 2.8) * step(2.7, r);
    s.albedo = lerp(s.albedo, float3(0.8, 0.14, 0.035), dotc); s.metal = lerp(s.metal, 0.0, dotc); s.rough = lerp(s.rough, 0.6, dotc);
  } else if (id < 2.5) {        // knurl: same metal, sharper facets
    s.albedo = float3(0.86, 0.865, 0.87); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.2));
  } else if (id < 3.5) {        // black anodised: a dielectric skin over metal
    s.albedo = float3(0.02, 0.02, 0.022); s.metal = 0.0; s.rough = 0.42 + 0.04 * snoise(q * 30.0);
  } else if (id < 4.5) {        // chrome-plated brass mount
    s.albedo = float3(0.95, 0.95, 0.96); s.metal = 1.0; s.rough = 0.06;
  } else if (id < 5.5) {        // glass (handled by the glass path)
    s.albedo = float3(1.0, 1.0, 1.0); s.metal = -1.0; s.rough = 0.0;
  } else if (id < 6.5) {        // flocking: the inside eats light
    s.albedo = float3(0.006, 0.006, 0.007); s.metal = 0.0; s.rough = 0.9;
  } else if (id < 7.5) {        // iris blades: blackened steel with a sheen
    s.albedo = float3(0.035, 0.035, 0.04); s.metal = 0.0; s.rough = 0.26;
    float ang = atan2(q.z, q.x);
    float x = (ang / TAU) * 11.0 + log(max(r, 0.05)) * 1.9;
    float seam = tri(x);
    float blade = floor(x + 0.5);
    s.albedo = float3(0.03, 0.03, 0.034) * (0.6 + 0.8 * frac(sin(blade * 12.9898) * 43758.5453));
    s.rough = 0.22;
    s.albedo *= 0.35 + 0.65 * smoothstep(0.0, 0.1, seam);
  } else if (id < 8.5) {        // black acrylic floor
    s.albedo = float3(0.014, 0.014, 0.015) * (0.9 + 0.1 * fbm2(p.xz * 0.6)); s.metal = 0.0; s.rough = 0.28;
  } else if (id < 9.5) {        // inked edges of the glass
    s.albedo = float3(0.012, 0.012, 0.013); s.metal = 0.0; s.rough = 0.6;
  } else if (id > 12.5 && id < 13.5) {  // a ground glass edge, milky
    s.albedo = float3(0.42, 0.45, 0.44); s.metal = 0.0; s.rough = 0.55;
  } else if (id > 11.5 && id < 12.5) {  // orange anodised aluminium
    s.albedo = float3(0.92, 0.3, 0.085); s.metal = 1.0; s.rough = 0.3; s.aniso = 0.5;
  } else if (id < 10.5) {       // ridges of the aperture ring
    s.albedo = float3(0.88, 0.885, 0.89); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.105));
  }
  // engraved and filled with paint
  if (id < 3.5 && id != 2.0) {
    float4 e = engraving(q, n, id);
    if (e.a > 0.002) {
      // white in the atlas is the primary fill: black on silver, white on black
      float3 ink = e.rgb / e.a;
      float white = saturate((ink.b - 0.5) * 4.0);
      float3 primary = id < 1.5 ? float3(0.005, 0.005, 0.0055) : float3(0.78, 0.78, 0.76);
      ink = lerp(ink * 0.85, primary, white);
      s.albedo = lerp(s.albedo, ink, e.a);
      s.metal = lerp(s.metal, 0.0, e.a);
      s.rough = lerp(s.rough, 0.85, e.a);
      s.aniso *= 1.0 - e.a;
      s.cavity = e.a;
      s.albedo *= 1.0 - 2.0 * e.a * (1.0 - e.a);     // the walls of the cut
    }
  }
  return s;
}

// ------------------------------------------------------------------ light
float softShadow(float3 ro, float3 rd, float k) {
  float res = 1.0, t = 0.02;
  for (int i = 0; i < 48; i++) {
    float h = mapScene(ro + rd * t, false).x;
    res = min(res, k * h / t);
    t += clamp(h, 0.02, 0.6);
    if (res < 0.002 || t > 30.0) break;
  }
  return saturate(res);
}
float ambientOcc(float3 p, float3 n) {
  float occ = 0.0, sca = 1.0;
  for (int i = 0; i < 5; i++) {
    float h = 0.02 + 0.12 * float(i);
    occ += (h - map(p + n * h).x) * sca;
    sca *= 0.7;
  }
  return saturate(1.0 - 1.6 * occ);
}
float3 fresnelS(float3 f0, float nv, float rough) {
  return f0 + (max(float3(1.0 - rough, 1.0 - rough, 1.0 - rough), f0) - f0) * pow(1.0 - nv, 5.0);
}

// Light reflected by a surface (one bounce of the studio): simple, for what
// glass and mirrors see.
float3 shadeSimple(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float3 r = reflect(-v, n);
  float3 kd = s.albedo * (1.0 - max(s.metal, 0.0));
  float key = studioAmt() * saturate(dot(n, envKeyDir()));
  if (id > 7.5 && id < 8.5 && abs(param(14)) < 1.0) kd *= smoothstep(2.4, 3.4, length(p.xz - LENS_ORIGIN.xz));
  if (id > 7.5 && id < 8.5 && key > 0.0) key *= softShadow(p + n * 0.01, envKeyDir(), 6.0);
  float3 diff = kd * (env(n, 0.9) * 1.2 + float3(1.0, 0.97, 0.94) * 2.2 * key);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, max(s.metal, 0.0));
  float3 spec = env(r, s.rough * s.rough * 3.2) * fresnelS(f0, saturate(dot(n, v)), s.rough);
  return diff + spec;
}

// Thin-film anti-reflection coating: a faint reflection that leans green
// head-on and magenta toward the edge, a different cast on each surface.
float3 coatF(float cosi, float k) {
  float h = frac(k * 0.37 + (1.0 - cosi) * 0.6);
  float3 tint = h < 0.5 ? lerp(float3(0.3, 1.0, 0.5), float3(0.9, 0.4, 1.0), h * 2.0) : lerp(float3(0.9, 0.4, 1.0), float3(0.3, 1.0, 0.5), h * 2.0 - 1.0);
  float3 r0 = 0.004 + 0.02 * tint;
  return r0 + (1.0 - r0) * pow(1.0 - cosi, 5.0);
}

#define GLASS_IOR 1.62
// Light through the optics: refract in, cross each element, refract out,
// gathering each surface's coated reflection of the studio on the way.
float3 glassPath(float3 pos, float3 dir, float3 n) {
  float3 col = float3(0.0, 0.0, 0.0);
  float3 thr = float3(1.0, 1.0, 1.0);
  float3 dir0 = dir;
  bool inside = false;
  float3 nn = n;                 // faces against the ray
  float3 axis = lensToWorldDir(float3(0.0, 1.0, 0.0));
  float open = ease(explode() * 3.0);
  for (int k = 0; k < 16; k++) {
    float cosi = saturate(-dot(dir, nn));
    float3 F = coatF(cosi, float(k));
    float3 rdir = reflect(dir, nn);
    // inside the barrel a reflection only sees the studio through the front
    float esc = k == 0 ? 1.0 : lerp(smoothstep(0.8, 0.97, dot(rdir, axis)), 1.0, open);
    col += thr * F * (inside ? 0.35 : 1.0) * env(rdir, 0.0) * esc;
    thr *= 1.0 - F;
    float3 t = refract(dir, nn, inside ? GLASS_IOR : 1.0 / GLASS_IOR);
    bool tir = dot(t, t) < 1e-5;
    if (tir) { dir = rdir; } else { dir = t; inside = !inside; }
    // step off the surface to the side the ray now travels
    pos += (dot(dir, nn) < 0.0 ? -nn : nn) * 0.0025;
    if (inside) {
      // through the glass to where the ray leaves it
      float s = 0.0;
      float2 g = float2(-1.0, M_GLASS);
      for (int i = 0; i < 80; i++) {
        g = glassMap(toLens(pos + dir * s));
        if (-g.x < 0.0003 || s > 8.0) break;
        s += max(-g.x, 0.0015);
      }
      pos += dir * s;
      if (g.y > 8.5) return col;          // out through an edge: lost
      nn = -glassNormal(pos);
      thr *= float3(0.985, 0.99, 0.982);  // a whisper of green from the glass itself
#ifndef FULL_TRACE
      if (explode() < 0.001) {
        // leave the front element, then the inside of the lens; light
        // trapped in the glass is lost
        float3 t2 = refract(dir, nn, GLASS_IOR);
        if (dot(t2, t2) < 1e-5) return col;
        float c2 = saturate(-dot(dir, nn));
        float3 F2 = coatF(c2, 1.0);
        col += thr * min(F2, float3(0.03, 0.03, 0.03)) * 0.35 * env(reflect(dir, nn), 0.0) * smoothstep(0.8, 0.97, dot(reflect(dir, nn), axis));
        return col + thr * (1.0 - F2) * lensInterior(pos - nn * 0.003, t2);
      }
#endif
    } else {
      float2 h = march(pos, dir, 60.0, true);
      if (h.x < 0.0) {
        // out of the lens into the studio, split by wavelength
        float3 dev = (dir - dir0) * 0.06;
        col += thr * float3(env(dir - dev, 0.0).r, env(dir, 0.0).g, env(dir + dev, 0.0).b);
        return col;
      }
      pos = pos + dir * h.x;
      if (h.y > 4.5 && h.y < 5.5) {
        nn = glassNormal(pos);
      } else {
        col += thr * shadeSimple(pos, calcNormal(pos), -dir, h.y);
        return col;
      }
    }
  }
  return col;
}


// ------------------------------------------------------------------ inside the assembled lens
// Past the front element the light is followed along a straight line: every
// inner surface it crosses adds its coated ghost of the studio, the iris
// stops it or lets it through, the barrel's black walls swallow the rest.
// (A full trace through eight curved elements is correct and unreadable.)
float3 dirToLens(float3 v) { return rotY(rotZ(v, -tilt()), -spin()); }
// sphere surfaces of the inner elements: centre height, radius, clear radius, coating hue
static const float4 GHOSTS[10] = {
  float4(2.85, 3.4, 1.85, 0.1), float4(3.05, 2.4, 1.85, 0.55), float4(2.6, 2.6, 1.5, 0.8), float4(2.8, 2.0, 1.5, 0.3),
  float4(5.5, 2.2, 1.45, 0.65), float4(5.7, 3.2, 1.45, 0.2), float4(-1.95, 4.0, 1.55, 0.9), float4(4.65, 3.5, 1.55, 0.45),
  float4(6.75, 6.0, 1.4, 0.7), float4(2.35, 2.2, 1.4, 0.05) };
static const float2 GHOST_Y[10] = {           // the y range each surface occupies
  float2(5.7, 6.26), float2(4.57, 5.46), float2(4.7, 5.21), float2(4.1, 4.81),
  float2(3.29, 3.86), float2(2.49, 2.86), float2(1.73, 2.06), float2(1.14, 1.52), float2(0.74, 0.93), float2(0.14, 0.66) };
float3 lensInterior(float3 pw, float3 dw) {
  float3 o = toLens(pw);
  float3 d = normalize(dirToLens(dw));
  float3 col = float3(0.0, 0.0, 0.0);
  float yIris = 3.95;
  // where the ray meets the black inner wall (r = 2.12)
  float a = dot(d.xz, d.xz), b = dot(o.xz, d.xz), c = dot(o.xz, o.xz) - 2.12 * 2.12;
  float tWall = a > 1e-6 ? (-b + sqrt(max(b * b - a * c, 0.0))) / a : 1e5;
  float tIris = d.y < -1e-4 ? (yIris - o.y) / d.y : 1e5;
  float3 axisW = lensToWorldDir(float3(0.0, 1.0, 0.0));
  for (int i = 0; i < 10; i++) {
    float4 g = GHOSTS[i];
    float3 oc = o - float3(0.0, g.x, 0.0);
    float bb = dot(oc, d), cc = dot(oc, oc) - g.y * g.y;
    float disc = bb * bb - cc;
    if (disc < 0.0) continue;
    float sq = sqrt(disc);
    for (int k = 0; k < 2; k++) {
      float t = -bb + (k == 0 ? -sq : sq);
      if (t <= 0.0 || t > tWall) continue;
      float3 h = o + d * t;
      if (h.y < GHOST_Y[i].x || h.y > GHOST_Y[i].y || length(h.xz) > g.z) continue;
      // behind the iris only what the iris lets through counts
      if (h.y < yIris && (t > tIris && irisHole(o.xz + d.xz * tIris) > 0.0)) continue;
      float3 n = normalize(h - float3(0.0, g.x, 0.0));
      if (dot(n, d) > 0.0) n = -n;
      float3 rw = lensToWorldDir(reflect(d, n));
      float cosi = saturate(-dot(d, n));
      // coatings leave green, magenta or amber, shifting a little with angle
      float hue = frac(g.w + (1.0 - cosi) * 0.25);
      float3 tint = hue < 0.33 ? lerp(float3(0.25, 1.0, 0.45), float3(0.95, 0.35, 1.0), hue * 3.0)
                  : hue < 0.66 ? lerp(float3(0.95, 0.35, 1.0), float3(1.0, 0.62, 0.22), hue * 3.0 - 1.0)
                               : lerp(float3(1.0, 0.62, 0.22), float3(0.25, 1.0, 0.45), hue * 3.0 - 2.0);
      float esc = smoothstep(0.82, 0.97, dot(rw, axisW));
      col += tint * 0.022 * env(rw, 0.035) * esc;
    }
  }
  if (tIris < tWall) {
    float3 h = o + d * tIris;
    if (irisHole(h.xz) > 0.0) {
      // a blade: blackened steel, lit by what comes in through the front
      float3 hw = LENS_ORIGIN + float3(0.0, PIVOT_Y, 0.0) + rotZ(rotY(h, spin()) - float3(0.0, PIVOT_Y, 0.0), tilt());
      float blade = floor(atan2(h.z, h.x) / TAU * 11.0 + log(max(length(h.xz), 0.05)) * 1.9 + 0.5);
      float3 rad = normalize(float3(h.x, 0.0, h.z) + 1e-5);
      float3 tan_ = float3(-rad.z, 0.0, rad.x);
      float3 nb = normalize(float3(0.0, 1.0, 0.0) + tan_ * (0.16 * sin(blade * 2.39)) + rad * 0.07);
      return col + shadeSimple(hw, lensToWorldDir(nb), -dw, M_IRIS) * 0.9;
    }
    // through the opening and out of the back: the floor under a standing
    // lens is dark; otherwise whatever lies behind
    if (abs(param(14)) < 1.0) return col;
    float3 dd = dw * 1.0;
    return col + env(dd, 0.0) * 0.9;
  }
  return col;     // the inner wall
}

// The full light at a surface the camera sees.
float3 shadeFull(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float nv = saturate(dot(n, v));
  float occ = ambientOcc(p, n);
  float3 kd = s.albedo * (1.0 - s.metal);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, s.metal);
  float3 F = fresnelS(f0, nv, s.rough);
  // diffuse: the key box (with its shadow) and the room
  float3 L = envKeyDir();
  float nl = saturate(dot(n, L));
  float sh = nl > 0.0 ? softShadow(p + n * 0.004, L, 6.0) : 0.0;
  float pool = id > 7.5 && id < 8.5 ? exp(-dot(p.xz, p.xz) / 260.0) : 1.0;
  float3 diff = kd * (float3(1.0, 0.975, 0.94) * 2.4 * studioAmt() * nl * sh + env(n, 0.9) * 1.3 * occ) * pool;
  // specular: the studio, blurred by roughness; turned metal smears it
  // along the axis of the lens
  float3 r = reflect(-v, n);
  float blur = s.rough * s.rough * 3.2;
  float3 spec;
  if (s.aniso > 0.0) {
    float3 ax = lensToWorldDir(float3(0.0, 1.0, 0.0));
    float3 rad = lensToWorldDir(normalize(float3(q.x, 0.0, q.z) + 1e-5));
    float3 tg = normalize(cross(ax, rad));
    float3 b = normalize(cross(n, tg) + 1e-5);
    spec = float3(0.0, 0.0, 0.0);
    for (int i = -2; i <= 2; i++) {
      float3 nn = normalize(n + b * (float(i) * 0.09 * s.aniso));
      spec += env(reflect(-v, nn), blur * 0.7);
    }
    spec *= 0.2;
  } else {
    spec = env(r, blur);
  }
  // glossy things see the scene, not just the studio
  if (s.rough < 0.3 || (id > 7.5 && id < 8.5)) {
    float2 h = march(p + n * 0.006, r, 40.0, true);
    if (h.x > 0.0) {
      float3 hp = p + n * 0.006 + r * h.x;
      float3 hn = calcNormal(hp);
      float3 hit = (h.y > 4.5 && h.y < 5.5) ? env(reflect(r, hn), 0.0) * 0.1 : shadeSimple(hp, hn, -r, h.y);
      // a rough floor blurs what it reflects the farther it is
      float keep = id > 7.5 && id < 8.5 ? exp(-h.x * 1.1) * 0.35 : 1.0;
      spec = lerp(spec, hit, keep);
    }
  }
  float specOcc = lerp(occ, 1.0, 0.35) * (1.0 - 0.7 * s.cavity);
  return diff * (1.0 - 0.5 * s.cavity) + spec * F * specOcc;
}

// ------------------------------------------------------------------ camera, samples, focus
#ifndef SAMPLES
#define SAMPLES 2
#endif
#ifndef FILTER_SIGMA
#define FILTER_SIGMA 0.5
#endif
// filmic tone curve
float3 filmic(float3 c) {
  return saturate((c * (2.51 * c + 0.03)) / (c * (2.43 * c + 0.59) + 0.14));
}
float4 shade(float2 pos, float px) {
  float2 sz = size();
  float3 target = float3(param(3), param(4), param(5));
  float az = radians(param(0)), el = radians(param(1));
  float3 eye = target + param(2) * float3(sin(az) * cos(el), sin(el), cos(az) * cos(el));
  gEye = eye;
  float3 fw = normalize(target - eye);
  float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
  float3 up = cross(rt, fw);
  float focal = 1.0 / tan(radians(param(6)) * 0.5);
  gPix = 2.0 / (focal * sz.y);
  float3 acc = float3(0.0, 0.0, 0.0);
  float depth = 1e4;
  float jit = hash12(pos * 0.37 + frac(time() * 7.13));
  // The pixel's footprint is a Gaussian (sigma FILTER_SIGMA px, cut at 3 sigma),
  // sampled on a golden-angle spiral with radii drawn from its distribution:
  // edges roll off over about a pixel, as through real glass and a sensor's
  // low-pass filter, instead of stepping. Each sample is tone-mapped before
  // the average, so a sub-pixel glint on a knurl ridge adds its share of the
  // pixel instead of flashing the whole pixel white from one frame to the next.
  float cut = 1.0 - exp(-4.5);
  for (int s = 0; s < SAMPLES; s++) {
    float u = (float(s) + 0.5) / float(SAMPLES);
    float rr = FILTER_SIGMA * sqrt(-2.0 * log(1.0 - u * cut));
    float a = float(s) * 2.39996323 + jit * TAU;
    float2 o = SAMPLES > 1 ? float2(cos(a), sin(a)) * rr : float2(0.0, 0.0);
    float2 qq = (pos + o - sz * 0.5) / (sz.y * 0.5);
    float3 rd = normalize(fw * focal + rt * qq.x - up * qq.y);
    float2 hit = march(eye, rd, 400.0, true);
    float3 c;
    if (hit.x < 0.0) {
      c = backdrop(rd);
    } else {
      float3 p = eye + rd * hit.x;
      if (s == 0) depth = hit.x;
      if (hit.y > 4.5 && hit.y < 5.5) {
        c = glassPath(p, rd, glassNormal(p));
      } else {
        float3 n = calcNormal(p);
        c = shadeFull(p, n, -rd, hit.y);
        // the floor melts into the backdrop with distance
        if (hit.y > 7.5 && hit.y < 8.5) c = lerp(c, backdrop(rd), saturate((hit.x - 40.0) / 80.0));
      }
    }
    acc += filmic(c * param(9));
  }
  float3 col = acc / float(SAMPLES);
  float coc = param(8) * (1.0 - param(7) / max(depth, 0.01));
  return float4(col, clamp(coc, -48.0, 48.0));
}

// Depth of field after the render: the scene's alpha is its signed circle of
// confusion in px (+ behind the focus plane, - in front of it). Each pixel
// gathers the pixels whose discs reach it, on a golden-angle spiral; what lies
// behind may not bleed over what is sharper in front. Bright points open into
// discs, as through a fast lens.
static const float GOLDEN = 2.39996323;
static const float TAU = 6.28318531;
float4 shade(float2 pos, float px) {
  float4 c0 = input(0, pos);
  float coc0 = abs(c0.a);
  // How far this pixel must look: its own disc, or a neighbour's that reaches it.
  float reach = coc0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * (TAU / 16.0) + 0.3;
    float d = (i & 1) == 0 ? 14.0 : 30.0;
    float n = input(0, pos + float2(cos(a), sin(a)) * d).a;
    float c = n > c0.a ? min(abs(n), coc0 * 2.0) : abs(n);
    if (c > d * 0.6) reach = max(reach, c);
  }
  if (reach < 0.75) return float4(c0.rgb, 1.0);
  float3 acc = c0.rgb;
  float tot = 1.0;
  float ang = frac(sin(dot(pos, float2(12.9898, 78.233))) * 43758.5453) * TAU;
  float r = 0.75;
  float scale = reach > 20.0 ? 1.6 : 0.9;
  for (int k = 0; k < 420; k++) {
    if (r > reach + 0.5) break;
    float2 tp = pos + float2(cos(ang), sin(ang)) * r;
    float4 s = input(0, tp);
    float sc = abs(s.a);
    if (s.a > c0.a) sc = min(sc, coc0 * 2.0);
    float m = smoothstep(r - 0.75, r + 0.75, sc);
    // wide discs of bright points carry more weight: bokeh
    float hot = smoothstep(0.8, 1.0, max(s.r, max(s.g, s.b))) * smoothstep(6.0, 16.0, sc);
    float w = m * (1.0 + 2.0 * hot);
    acc += s.rgb * w;
    tot += w;
    ang += GOLDEN;
    r += scale / r;
  }
  float3 col = acc / tot;
  return float4(min(col, float3(1.0, 1.0, 1.0)), 1.0);
}

#define SAMPLES 4
#define NO_FLOOR
#define RIM_SCALE 0.3
#define STUDIO_SCALE 0.3
#define LIGHTBOX 16.0
#define LIGHTBOX_DIR float3(-1.0, 0.42, 0.36)
// HOLM 35 f/1.4: a camera lens in a photographer's studio, raymarched.
// Units are centimetres. The lens stands on its mount at the origin with its
// optical axis up (+y); the studio is three softboxes, two strip lights and a
// black acrylic floor. Every animated value is a param:
//    0  1  2   camera orbit: azimuth, elevation (degrees), distance
//    3  4  5   camera target
//    6         vertical field of view (degrees)
//    7         focus distance (cm)        8  blur: CoC in px at twice the focus distance
//    9         exposure                   10 explode 0..1 (the optics slide out)
//    11        focus ring turn (degrees)  12 iris, stops closed from f/1.4 (0..7)
//    13        light: 0 dark, 1 the sweep crosses, 2 full studio
//    14        lens tilt about z (deg)    15 lens spin about its axis (deg)
// The image's alpha carries the signed circle of confusion for the dof pass.

static const float PI = 3.14159265;
static const float TAU = 6.28318531;

// ------------------------------------------------------------------ helpers
float3 rotY(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }
float3 rotZ(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x - s * p.y, s * p.x + c * p.y, p.z); }
float hash12(float2 p) { float3 p3 = frac(float3(p.x, p.y, p.x) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return frac((p3.x + p3.y) * p3.z); }
float box2(float2 p, float2 b, float r) { float2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
// A ring turned on a lathe: radii r0..r1, heights y0..y1, its edges broken by e.
float ring(float2 ry, float r0, float r1, float y0, float y1, float e) {
  return box2(ry - float2((r0 + r1) * 0.5, (y0 + y1) * 0.5), float2((r1 - r0) * 0.5, (y1 - y0) * 0.5), e);
}
float2 opU(float2 a, float2 b) { return a.x < b.x ? a : b; }
float fbm2(float2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { s += a * snoise(float3(p, 0.37 * float(i))); p = p * 2.1 + float2(1.7, 9.2); a *= 0.5; } return s; }
float tri(float x) { return abs(frac(x) - 0.5) * 2.0; }        // 1 at integers, 0 halfway
// polynomial smooth min / max: blends a and b over a band k wide
float smin(float a, float b, float k) { float h = max(k - abs(a - b), 0.0) / k; return min(a, b) - h * h * k * 0.25; }
float smax(float a, float b, float k) { return -smin(-a, -b, k); }
float ease(float x) { x = saturate(x); return x * x * (3.0 - 2.0 * x); }

// ------------------------------------------------------------------ materials
#define M_SILVER 1.0
#define M_KNURL 2.0
#define M_BLACK 3.0
#define M_CHROME 4.0
#define M_GLASS 5.0
#define M_FLOCK 6.0
#define M_IRIS 7.0
#define M_FLOOR 8.0
#define M_EDGE 9.0
#define M_RIDGE 10.0
#define M_GOLD 11.0
#define M_ORANGE 12.0
#define M_GROUND 13.0

// ------------------------------------------------------------------ per-pixel camera state
static float3 gEye;
static float gPix;      // world size of one pixel at unit distance

float tilt() { return radians(param(14)); }
float spin() { return radians(param(15)); }
float explode() { return param(10); }

static const float3 LENS_ORIGIN = float3(0.0, 0.52, 0.0);   // the mount flange, in the world
static const float PIVOT_Y = 3.3;                            // where the lens turns when it tilts
float3 toLens(float3 p) {
  float3 q = p - LENS_ORIGIN - float3(0.0, PIVOT_Y, 0.0);
  q = rotZ(q, -tilt());
  q.y += PIVOT_Y;
  return rotY(q, -spin());
}
float3 lensToWorldDir(float3 v) { return rotZ(rotY(v, spin()), tilt()); }

// ------------------------------------------------------------------ the optics
// Eight elements in six groups, front to back. Each: centre height, centre
// thickness, front radius (+ convex), back radius (+ convex), clear radius.
// Exploded, each group slides forward to its own place on the axis.
static const float EXPLODE_BARREL = 3.4;
float groupShift(int g) {
  // front groups leave first; each eases out on its own beat
  static const float DY[7] = { 13.6, 11.9, 10.3, 9.0, 7.7, 6.6, 5.4 };
  float e = explode();
  float k = ease(e * 1.45 - float(g) * 0.075);
  return DY[g] * k;
}
float barrelShift() { return -EXPLODE_BARREL * ease(explode() * 1.3); }

// a spherical surface: + convex toward its side, - concave
float surfFront(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv - R)) - R;
  return max(-R - length(ry - float2(0.0, yv - R)), ry.y - (yv - R));
}
float surfBack(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv + R)) - R;
  return max(-R - length(ry - float2(0.0, yv + R)), (yv + R) - ry.y);
}
float element(float2 ry, float yc, float t, float Rf, float Rb, float a, out float edge) {
  float f = surfFront(ry, yc + t * 0.5, Rf);
  float b = surfBack(ry, yc - t * 0.5, Rb);
  float c = ry.x - a;
  float d = max(max(f, b), c);
  edge = c > max(f, b) - 0.002 ? 1.0 : 0.0;
  return d;
}

// The glass alone (for marching inside it). id = 5 glass, 9 inked edge.
float2 glassMap(float3 q) {
  float r = length(q.xz);
#ifdef CLEAR_EDGES
  const float EDGE_ID = M_GROUND;
#else
  const float EDGE_ID = M_EDGE;
#endif
  if (r > 2.3) return float2(r - 2.2, M_GLASS);
  float2 res = float2(1e5, M_GLASS);
  float edge;
  float y;
  // G1: E1 positive meniscus
  y = q.y - groupShift(0);
  float d = element(float2(r, y), 6.75, 0.5, 4.8, -9.0, 2.12, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G2: E2 + E3 cemented
  y = q.y - groupShift(1);
  d = element(float2(r, y), 6.0, 0.5, 3.4, -6.0, 1.85, edge);
  float e3 = max(max(max(length(float2(r, y) - float2(0.0, -0.25)) - 6.0, 2.4 - length(float2(r, y) - float2(0.0, 3.05))), r - 1.85), 3.05 - y);
  float edge3 = (r - 1.85) > -0.002 ? 1.0 : 0.0;
  d = min(d, e3);
  res = opU(res, float2(d, (edge > 0.5 || edge3 > 0.5) && r > 1.83 ? EDGE_ID : M_GLASS));
  // G3: E4 meniscus
  y = q.y - groupShift(2);
  d = element(float2(r, y), 5.0, 0.4, 2.6, -2.0, 1.5, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G4: E5 + E6 cemented (concave toward the iris)
  y = q.y - groupShift(4);
  float e5 = max(max(2.2 - length(float2(r, y) - float2(0.0, 5.5)), length(float2(r, y) - float2(0.0, 8.05)) - 5.0), r - 1.45);
  float e6 = max(max(5.0 - length(float2(r, y) - float2(0.0, 8.05)), length(float2(r, y) - float2(0.0, 5.7)) - 3.2), r - 1.45);
  e5 = max(e5, y - 3.95);
  d = min(e5, e6);
  res = opU(res, float2(d, r > 1.43 ? EDGE_ID : M_GLASS));
  // G5: E7 biconvex
  y = q.y - groupShift(5);
  d = element(float2(r, y), 1.6, 0.9, 4.0, 3.5, 1.55, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G6: E8, the rear element: its back face aspherical (a fourth-order term
  // flattens it toward the edge)
  y = q.y - groupShift(6);
  float f8 = surfFront(float2(r, y), 0.75, -6.0);
  float b8 = length(float2(r, y) - float2(0.0, 2.35)) - 2.2 + 0.012 * r * r * r * r;
  float c8 = r - 1.4;
  d = max(max(f8, b8), c8);
  res = opU(res, float2(d, c8 > max(f8, b8) - 0.002 ? EDGE_ID : M_GLASS));
  return res;
}

// The iris: eleven rounded blades between G3 and G4.
float irisRadius() { return 1.0 * 1.4 / (1.4 * pow(2.0, param(12) * 0.5)); }
float irisHole(float2 xz) {
  float a = irisRadius();
  float ang = atan2(xz.y, xz.x) + param(12) * 0.06;
  float sec = TAU / 11.0;
  float f = (frac(ang / sec) - 0.5) * sec;
  float rr = length(xz);
  float poly = rr * cos(f) - a;
  return lerp(poly, rr - a * 1.04, 0.55);     // blades are curved: rounder than a polygon
}
float irisMap(float3 q) {
  float y = q.y - 3.95 - groupShift(3);
  float r = length(q.xz);
  float disc = max(abs(y) - 0.022, r - 2.08);
  return max(disc, -irisHole(q.xz));
}

// ------------------------------------------------------------------ the barrel
// Diamond knurl on the focus ring, straight ridges on the aperture ring; both
// fade into a flat average where a pixel is wider than their pitch.
float knurlH(float3 q, float y, float fade) {
  float th = atan2(q.z, q.x) + radians(param(11));
  float u = th * (96.0 / TAU);
  float v = y / 0.2;
  // rolled, not cut: the crests, the valleys and the edges between facets are
  // rounded, so a crest catches the light as a soft line a few pixels wide
  // rather than a sub-pixel glint that flickers as the ring turns
  float h = smin(tri(u + v), tri(u - v), 0.08);
  h = smax(smin(h, 0.93, 0.12), 0.04, 0.08);
  return (h * 0.9 - 0.45) * 0.05 * fade;
}
float ridgeH(float3 q, float fade) {
  float th = atan2(q.z, q.x) + radians(param(12) * 12.0);
  float u = th * (180.0 / TAU);
  float h = smoothstep(0.0, 1.0, tri(u));
  return (h - 0.5) * 0.016 * fade;
}
float lodFade(float3 q, float pitch) {
  float3 e = toLens(gEye) - q;
  float d = length(e);
  float graze = abs(dot(normalize(float3(q.x, 0.0, q.z)), e / d));
  float foot = d * gPix / max(graze, 0.12);
  return smoothstep(pitch * 1.1, pitch * 0.45, foot);
}

float2 barrelMap(float3 q) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float2 ry = float2(r, y);
  float bound = ring(ry, 1.85, 3.25, -0.62, 7.3, 0.0);
  if (bound > 0.25) return float2(bound, M_SILVER);
  float2 res = float2(1e5, M_SILVER);
  // mount: chrome tube, flange and three bayonet lugs
  float th = atan2(q.z, q.x);
  float sector = abs(frac(th * 3.0 / TAU + 0.083) - 0.5) * (TAU / 3.0) * r;
  float lug = max(ring(ry, 1.98, 2.44, -0.52, -0.40, 0.02), sector - 0.95);
  float tube = ring(ry, 1.95, 2.33, -0.40, 0.02, 0.03);
  float flange = ring(ry, 2.2, 2.6, -0.09, 0.0, 0.02);
  res = opU(res, float2(min(min(lug, tube), flange), M_CHROME));
  // rear barrel: narrower than the rings above it, its foot broken wide
  res = opU(res, float2(ring(ry, 2.2, 2.78, 0.03, 1.36, 0.1), M_SILVER));
  // aperture ring with its ridged grip
  float ar = ring(ry, 2.25, 2.95, 1.42, 2.52, 0.05);
  if (y > 1.5 && y < 1.98 && r > 2.75) ar += ridgeH(q, lodFade(q, 0.105)) * smoothstep(1.5, 1.56, y) * smoothstep(1.98, 1.92, y);
  res = opU(res, float2(ar, (y > 1.49 && y < 1.99 && r > 2.85) ? M_RIDGE : M_SILVER));
  // the fixed scale ring (black anodised)
  res = opU(res, float2(ring(ry, 2.25, 2.84, 2.58, 3.04, 0.035), M_BLACK));
  // focus ring: a smooth scale band, a step, the knurl: the widest part
  float fr = ring(ry, 2.25, 3.08, 3.10, 5.62, 0.06);
  float step = ring(ry, 2.25, 3.13, 3.80, 5.46, 0.05);
  fr = min(fr, step);
  if (y > 3.8 && y < 5.46 && r > 2.95) fr += knurlH(q, y, lodFade(q, 0.2)) * smoothstep(3.84, 3.9, y) * smoothstep(5.42, 5.36, y);
  res = opU(res, float2(fr, (y > 3.83 && y < 5.43 && r > 3.03) ? M_KNURL : M_SILVER));
  // front barrel: tapering toward the front, two fine turned grooves
  float R = 3.0 - (clamp(y, 5.68, 6.96) - 5.68) * 0.055;
  float fb = box2(ry - float2((2.2 + R) * 0.5, 6.32), float2((R - 2.2) * 0.5, 0.64), 0.06);
  float gr = min(box2(ry - float2(R, 6.5), float2(0.02, 0.012), 0.008), box2(ry - float2(R, 6.64), float2(0.02, 0.012), 0.008));
  fb = max(fb, -gr);
  res = opU(res, float2(fb, M_SILVER));
  // a thin ring of orange anodising under the name ring
  res = opU(res, float2(ring(ry, 2.6, 2.935, 6.965, 7.055, 0.012), M_ORANGE));
  // the name ring: black, its front face engraved
  float nr = ring(ry, 2.22, 2.92, 7.06, 7.24, 0.04);
  res = opU(res, float2(nr, M_BLACK));
  // the inside: a light trap lining the metal (the innermost surface)
  float inner = ring(ry, 2.15, 2.27, 0.05, 7.2, 0.01);
  res = opU(res, float2(inner, M_FLOCK));
  return res;
}

// ------------------------------------------------------------------ the scene
static const float FLOOR_Y = 0.0;
float2 mapScene(float3 p, bool withGlass) {
  float2 res = float2(p.y - FLOOR_Y, M_FLOOR);
#ifdef NO_FLOOR
  res.x = 1e5;
#endif
  float3 q = toLens(p);
  res = opU(res, barrelMap(q));
  float rq = length(q.xz);
  if (rq < 2.4) {
    res = opU(res, float2(irisMap(q), M_IRIS));
    // the G1 retaining ring travels with the front element
    float y1 = q.y - groupShift(0);
    res = opU(res, float2(ring(float2(rq, y1), 2.02, 2.2, 6.58, 6.68, 0.01), M_FLOCK));
    if (withGlass) res = opU(res, glassMap(q));
  } else if (withGlass) {
    res = opU(res, float2(rq - 2.3, M_GLASS));
  }
  return res;
}
float2 map(float3 p) { return mapScene(p, true); }

float3 calcNormal(float3 p) {
  float2 e = float2(0.0007, -0.0007);
  return normalize(e.xyy * map(p + e.xyy).x + e.yyx * map(p + e.yyx).x + e.yxy * map(p + e.yxy).x + e.xxx * map(p + e.xxx).x);
}
float3 glassNormal(float3 p) {
  float2 e = float2(0.0006, -0.0006);
  float3 q = toLens(p);
  // gradient in lens space, turned back to the world
  float3 n = e.xyy * glassMap(q + e.xyy).x + e.yyx * glassMap(q + e.yyx).x + e.yxy * glassMap(q + e.yxy).x + e.xxx * glassMap(q + e.xxx).x;
  return normalize(lensToWorldDir(n));
}
float2 march(float3 ro, float3 rd, float maxd, bool withGlass) {
  float t = 0.0;
  for (int i = 0; i < 200; i++) {
    float2 h = mapScene(ro + rd * t, withGlass);
    if (abs(h.x) < 0.00025 * t + 0.0004) return float2(t, h.y);
    t += h.x * 0.85;
    if (t > maxd) break;
  }
  return float2(-1.0, 0.0);
}

// ------------------------------------------------------------------ the studio
// A softbox seen in direction d: a rounded rectangle on the plane facing the
// lens, its edges softened by `blur` (roughness widens it, keeping its energy).
float window1(float x, float a, float e) { return smoothstep(-a - e, -a + e, x) - smoothstep(a - e, a + e, x); }
// A softbox seen in direction d: a rectangle on the plane facing the lens,
// brighter at its centre, its edges softened by `blur` (roughness widens
// them, keeping the energy).
float softbox(float3 d, float3 c, float3 up, float2 half_, float blur) {
  float k = dot(d, c);
  if (k <= 0.02) return 0.0;
  float3 rt = normalize(cross(up, c));
  float3 u2 = cross(c, rt);
  float2 uv = float2(dot(d, rt), dot(d, u2)) / k;
  float fall = 1.0 - 0.45 * dot(uv / half_, uv / half_) * 0.5;
  return window1(uv.x, half_.x, 0.012 + blur) * window1(uv.y, half_.y, 0.012 + blur) * max(fall, 0.3);
}
// The light cue (param 13): 0..1 the rim strips outline the lens, 1..2 a
// strip sweeps across its front, 1.8..3 the studio comes up (overlapping it).
float rimAmt() { return saturate(param(13)); }
float sweepAmt() { return saturate(param(13) - 1.0); }
float studioAmt() { return saturate((param(13) - 1.8) / 1.2); }
#ifndef ENV_YAW
#define ENV_YAW 0.0
#endif
float3 env(float3 d, float blur) {
  d = rotY(d, radians(ENV_YAW));
  float s = studioAmt();
  float rim = rimAmt();
#ifdef STUDIO_SCALE
  float big = s * STUDIO_SCALE;
#else
  float big = s;
#endif
#ifdef RIM_SCALE
  rim *= RIM_SCALE;
#endif
  // the dark room: a little light up high, nearly black low down
  float3 c = lerp(float3(0.004, 0.004, 0.0042), float3(0.02, 0.0195, 0.019), saturate(d.y * 0.8 + 0.3)) * (0.15 + 0.85 * s);
  // key: a big box front left, high
  c += float3(1.0, 0.975, 0.94) * 2.6 * big * softbox(d, normalize(float3(-0.62, 0.5, 0.6)), float3(0, 1, 0), float2(0.55, 0.62), blur);
  // overhead scrim: broad and soft
  c += float3(0.95, 0.965, 1.0) * 1.5 * big * softbox(d, float3(0.0, 1.0, 0.0), float3(0, 0, -1), float2(1.1, 0.8), blur);
  // fill: a white card front right
  c += float3(1.0, 0.99, 0.97) * 0.75 * big * softbox(d, normalize(float3(0.7, 0.12, 0.7)), float3(0, 1, 0), float2(0.42, 0.55), blur);
  // two tall strips behind, one each side: the rims
  c += float3(0.93, 0.96, 1.0) * 6.5 * rim * softbox(d, normalize(float3(-0.9, 0.1, -0.42)), float3(0, 1, 0), float2(0.07, 1.0), blur);
  c += float3(1.0, 0.97, 0.94) * 5.5 * rim * softbox(d, normalize(float3(0.88, 0.14, -0.46)), float3(0, 1, 0), float2(0.055, 1.0), blur);
#ifdef LIGHTBOX
  // a small square box just over the camera's shoulder: the glints in the glass
  c += float3(1.0, 0.98, 0.95) * LIGHTBOX * softbox(d, normalize(LIGHTBOX_DIR), float3(0, 1, 0), float2(0.085, 0.085), blur);
#endif
#ifdef BACKLIGHT
#ifndef BACKLIGHT_COLOR
#define BACKLIGHT_COLOR float3(1.0, 0.9, 0.78)
#endif
  // a round light hidden behind the lens: seen only through it
  float bl = dot(d, normalize(BACKLIGHT_DIR));
  c += BACKLIGHT_COLOR * BACKLIGHT * smoothstep(0.3, 0.85, bl) * (0.6 + 0.4 * smoothstep(0.85, 1.0, bl));
#endif
  // the sweep: one strip that travels round the front of the lens
  float sw = sweepAmt();
  if (sw > 0.0 && sw < 1.0) {
    float a = lerp(-1.9, 1.6, sw);
    float3 sd = normalize(float3(sin(a), 0.22, cos(a)));
    c += float3(1.0, 0.98, 0.95) * 9.0 * softbox(d, sd, float3(0, 1, 0), float2(0.07, 1.2), blur) * smoothstep(0.0, 0.1, sw) * smoothstep(1.0, 0.8, sw) * (1.0 - s);
  }
  return c;
}
float3 envKeyDir() { return rotY(normalize(float3(-0.62, 0.5, 0.6)), -radians(ENV_YAW)); }

// What the camera sees past everything: a dark seamless sweep with a soft
// pool of light behind the lens.
float3 backdrop(float3 rd) {
  float s = max(studioAmt(), rimAmt() * 0.25);
  float3 base = float3(0.006, 0.0062, 0.0068);
  float3 toL = normalize(float3(0.0, 4.6, 0.0) - gEye);
  float halo = exp(-(1.0 - dot(rd, toL)) * 7.0);
  float3 c = base * (0.35 + 0.65 * s) + float3(0.03, 0.029, 0.028) * halo * s;
#ifdef BACKLIGHT
  // the panel behind lights the wall a little too
  c += float3(0.92, 0.93, 0.95) * BACKLIGHT * 0.03 * exp(-(1.0 - dot(rd, toL)) * 4.0);
#endif
  return c;
}

// ------------------------------------------------------------------ engravings
// Input 0 is an atlas of the engraved scales, drawn as ordinary text: four
// bands, each a range of ring angles across the frame's width and a range of
// heights (or radii) down its rows (BANDS in product.py holds the same numbers).
float wrapInto(float a, float a0) { return a0 + fmod(fmod(a - a0, 360.0) + 360.0, 360.0); }
float4 atlasBand(float alpha, float h, float a0, float a1, float h0, float h1, float r0, float r1, bool ltr) {
  float a = wrapInto(alpha, a0);
  if (a > a1) return float4(0.0, 0.0, 0.0, 0.0);
  float t = (h0 - h) / (h0 - h1);
  if (t < 0.0 || t > 1.0) return float4(0.0, 0.0, 0.0, 0.0);
  float x = ltr ? (a - a0) / (a1 - a0) : (a1 - a) / (a1 - a0);
  return input(0, float2(x * 1920.0, r0 + t * (r1 - r0)));
}
float4 engraving(float3 q, float3 n, float id) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float th = degrees(atan2(q.z, q.x));
  if (id < 1.5) {
    if (r > 3.0 && y > 3.12 && y < 3.78) return atlasBand(th + param(11), y, 60.0, 260.0, 3.76, 3.14, 0.0, 111.0, false);
    if (r > 2.92 && y > 2.0 && y < 2.5) return atlasBand(th + param(12) * 12.0, y, 70.0, 200.0, 2.47, 2.02, 130.0, 257.0, false);
  } else if (id < 3.5) {
    if (r > 2.8 && y > 2.58 && y < 3.04) return atlasBand(th, y, 50.0, 130.0, 3.02, 2.60, 300.0, 521.0, false);
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    if (y > 7.15 && ax > 0.9) return atlasBand(th, r, 150.0, 390.0, 2.88, 2.40, 540.0, 620.0, true);
  }
  return float4(0.0, 0.0, 0.0, 0.0);
}

// ------------------------------------------------------------------ surfaces
struct Surf { float3 albedo; float metal; float rough; float aniso; float cavity; };

Surf surface(float id, float3 p, float3 q, float3 n) {
  Surf s;
  s.albedo = float3(0.8, 0.8, 0.8); s.metal = 0.0; s.rough = 0.5; s.aniso = 0.0; s.cavity = 0.0;
  float r = length(q.xz);
  float y = q.y - barrelShift();
  if (id < 1.5) {               // turned, bead-blasted aluminium, clear anodised
    // bead-blasted, clear anodised; the edges are diamond-cut and polished
    s.albedo = float3(0.9, 0.905, 0.91); s.metal = 1.0; s.aniso = 0.8;
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    float chamfer = smoothstep(0.12, 0.3, ax) * smoothstep(0.995, 0.95, ax);
    s.rough = lerp(0.5 + 0.06 * snoise(q * 40.0), 0.12, chamfer);
    s.aniso = lerp(0.8, 0.2, chamfer);
    // the mounting index: an orange dot on the rear barrel, facing the scales
    float dotd = length(float2((atan2(q.z, q.x) - 1.5708) * r, y - 0.72));
    float dotc = smoothstep(0.075, 0.062, dotd) * step(r, 2.8) * step(2.7, r);
    s.albedo = lerp(s.albedo, float3(0.8, 0.14, 0.035), dotc); s.metal = lerp(s.metal, 0.0, dotc); s.rough = lerp(s.rough, 0.6, dotc);
  } else if (id < 2.5) {        // knurl: same metal, sharper facets
    s.albedo = float3(0.86, 0.865, 0.87); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.2));
  } else if (id < 3.5) {        // black anodised: a dielectric skin over metal
    s.albedo = float3(0.02, 0.02, 0.022); s.metal = 0.0; s.rough = 0.42 + 0.04 * snoise(q * 30.0);
  } else if (id < 4.5) {        // chrome-plated brass mount
    s.albedo = float3(0.95, 0.95, 0.96); s.metal = 1.0; s.rough = 0.06;
  } else if (id < 5.5) {        // glass (handled by the glass path)
    s.albedo = float3(1.0, 1.0, 1.0); s.metal = -1.0; s.rough = 0.0;
  } else if (id < 6.5) {        // flocking: the inside eats light
    s.albedo = float3(0.006, 0.006, 0.007); s.metal = 0.0; s.rough = 0.9;
  } else if (id < 7.5) {        // iris blades: blackened steel with a sheen
    s.albedo = float3(0.035, 0.035, 0.04); s.metal = 0.0; s.rough = 0.26;
    float ang = atan2(q.z, q.x);
    float x = (ang / TAU) * 11.0 + log(max(r, 0.05)) * 1.9;
    float seam = tri(x);
    float blade = floor(x + 0.5);
    s.albedo = float3(0.03, 0.03, 0.034) * (0.6 + 0.8 * frac(sin(blade * 12.9898) * 43758.5453));
    s.rough = 0.22;
    s.albedo *= 0.35 + 0.65 * smoothstep(0.0, 0.1, seam);
  } else if (id < 8.5) {        // black acrylic floor
    s.albedo = float3(0.014, 0.014, 0.015) * (0.9 + 0.1 * fbm2(p.xz * 0.6)); s.metal = 0.0; s.rough = 0.28;
  } else if (id < 9.5) {        // inked edges of the glass
    s.albedo = float3(0.012, 0.012, 0.013); s.metal = 0.0; s.rough = 0.6;
  } else if (id > 12.5 && id < 13.5) {  // a ground glass edge, milky
    s.albedo = float3(0.42, 0.45, 0.44); s.metal = 0.0; s.rough = 0.55;
  } else if (id > 11.5 && id < 12.5) {  // orange anodised aluminium
    s.albedo = float3(0.92, 0.3, 0.085); s.metal = 1.0; s.rough = 0.3; s.aniso = 0.5;
  } else if (id < 10.5) {       // ridges of the aperture ring
    s.albedo = float3(0.88, 0.885, 0.89); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.105));
  }
  // engraved and filled with paint
  if (id < 3.5 && id != 2.0) {
    float4 e = engraving(q, n, id);
    if (e.a > 0.002) {
      // white in the atlas is the primary fill: black on silver, white on black
      float3 ink = e.rgb / e.a;
      float white = saturate((ink.b - 0.5) * 4.0);
      float3 primary = id < 1.5 ? float3(0.005, 0.005, 0.0055) : float3(0.78, 0.78, 0.76);
      ink = lerp(ink * 0.85, primary, white);
      s.albedo = lerp(s.albedo, ink, e.a);
      s.metal = lerp(s.metal, 0.0, e.a);
      s.rough = lerp(s.rough, 0.85, e.a);
      s.aniso *= 1.0 - e.a;
      s.cavity = e.a;
      s.albedo *= 1.0 - 2.0 * e.a * (1.0 - e.a);     // the walls of the cut
    }
  }
  return s;
}

// ------------------------------------------------------------------ light
float softShadow(float3 ro, float3 rd, float k) {
  float res = 1.0, t = 0.02;
  for (int i = 0; i < 48; i++) {
    float h = mapScene(ro + rd * t, false).x;
    res = min(res, k * h / t);
    t += clamp(h, 0.02, 0.6);
    if (res < 0.002 || t > 30.0) break;
  }
  return saturate(res);
}
float ambientOcc(float3 p, float3 n) {
  float occ = 0.0, sca = 1.0;
  for (int i = 0; i < 5; i++) {
    float h = 0.02 + 0.12 * float(i);
    occ += (h - map(p + n * h).x) * sca;
    sca *= 0.7;
  }
  return saturate(1.0 - 1.6 * occ);
}
float3 fresnelS(float3 f0, float nv, float rough) {
  return f0 + (max(float3(1.0 - rough, 1.0 - rough, 1.0 - rough), f0) - f0) * pow(1.0 - nv, 5.0);
}

// Light reflected by a surface (one bounce of the studio): simple, for what
// glass and mirrors see.
float3 shadeSimple(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float3 r = reflect(-v, n);
  float3 kd = s.albedo * (1.0 - max(s.metal, 0.0));
  float key = studioAmt() * saturate(dot(n, envKeyDir()));
  if (id > 7.5 && id < 8.5 && abs(param(14)) < 1.0) kd *= smoothstep(2.4, 3.4, length(p.xz - LENS_ORIGIN.xz));
  if (id > 7.5 && id < 8.5 && key > 0.0) key *= softShadow(p + n * 0.01, envKeyDir(), 6.0);
  float3 diff = kd * (env(n, 0.9) * 1.2 + float3(1.0, 0.97, 0.94) * 2.2 * key);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, max(s.metal, 0.0));
  float3 spec = env(r, s.rough * s.rough * 3.2) * fresnelS(f0, saturate(dot(n, v)), s.rough);
  return diff + spec;
}

// Thin-film anti-reflection coating: a faint reflection that leans green
// head-on and magenta toward the edge, a different cast on each surface.
float3 coatF(float cosi, float k) {
  float h = frac(k * 0.37 + (1.0 - cosi) * 0.6);
  float3 tint = h < 0.5 ? lerp(float3(0.3, 1.0, 0.5), float3(0.9, 0.4, 1.0), h * 2.0) : lerp(float3(0.9, 0.4, 1.0), float3(0.3, 1.0, 0.5), h * 2.0 - 1.0);
  float3 r0 = 0.004 + 0.02 * tint;
  return r0 + (1.0 - r0) * pow(1.0 - cosi, 5.0);
}

#define GLASS_IOR 1.62
// Light through the optics: refract in, cross each element, refract out,
// gathering each surface's coated reflection of the studio on the way.
float3 glassPath(float3 pos, float3 dir, float3 n) {
  float3 col = float3(0.0, 0.0, 0.0);
  float3 thr = float3(1.0, 1.0, 1.0);
  float3 dir0 = dir;
  bool inside = false;
  float3 nn = n;                 // faces against the ray
  float3 axis = lensToWorldDir(float3(0.0, 1.0, 0.0));
  float open = ease(explode() * 3.0);
  for (int k = 0; k < 16; k++) {
    float cosi = saturate(-dot(dir, nn));
    float3 F = coatF(cosi, float(k));
    float3 rdir = reflect(dir, nn);
    // inside the barrel a reflection only sees the studio through the front
    float esc = k == 0 ? 1.0 : lerp(smoothstep(0.8, 0.97, dot(rdir, axis)), 1.0, open);
    col += thr * F * (inside ? 0.35 : 1.0) * env(rdir, 0.0) * esc;
    thr *= 1.0 - F;
    float3 t = refract(dir, nn, inside ? GLASS_IOR : 1.0 / GLASS_IOR);
    bool tir = dot(t, t) < 1e-5;
    if (tir) { dir = rdir; } else { dir = t; inside = !inside; }
    // step off the surface to the side the ray now travels
    pos += (dot(dir, nn) < 0.0 ? -nn : nn) * 0.0025;
    if (inside) {
      // through the glass to where the ray leaves it
      float s = 0.0;
      float2 g = float2(-1.0, M_GLASS);
      for (int i = 0; i < 80; i++) {
        g = glassMap(toLens(pos + dir * s));
        if (-g.x < 0.0003 || s > 8.0) break;
        s += max(-g.x, 0.0015);
      }
      pos += dir * s;
      if (g.y > 8.5) return col;          // out through an edge: lost
      nn = -glassNormal(pos);
      thr *= float3(0.985, 0.99, 0.982);  // a whisper of green from the glass itself
#ifndef FULL_TRACE
      if (explode() < 0.001) {
        // leave the front element, then the inside of the lens; light
        // trapped in the glass is lost
        float3 t2 = refract(dir, nn, GLASS_IOR);
        if (dot(t2, t2) < 1e-5) return col;
        float c2 = saturate(-dot(dir, nn));
        float3 F2 = coatF(c2, 1.0);
        col += thr * min(F2, float3(0.03, 0.03, 0.03)) * 0.35 * env(reflect(dir, nn), 0.0) * smoothstep(0.8, 0.97, dot(reflect(dir, nn), axis));
        return col + thr * (1.0 - F2) * lensInterior(pos - nn * 0.003, t2);
      }
#endif
    } else {
      float2 h = march(pos, dir, 60.0, true);
      if (h.x < 0.0) {
        // out of the lens into the studio, split by wavelength
        float3 dev = (dir - dir0) * 0.06;
        col += thr * float3(env(dir - dev, 0.0).r, env(dir, 0.0).g, env(dir + dev, 0.0).b);
        return col;
      }
      pos = pos + dir * h.x;
      if (h.y > 4.5 && h.y < 5.5) {
        nn = glassNormal(pos);
      } else {
        col += thr * shadeSimple(pos, calcNormal(pos), -dir, h.y);
        return col;
      }
    }
  }
  return col;
}


// ------------------------------------------------------------------ inside the assembled lens
// Past the front element the light is followed along a straight line: every
// inner surface it crosses adds its coated ghost of the studio, the iris
// stops it or lets it through, the barrel's black walls swallow the rest.
// (A full trace through eight curved elements is correct and unreadable.)
float3 dirToLens(float3 v) { return rotY(rotZ(v, -tilt()), -spin()); }
// sphere surfaces of the inner elements: centre height, radius, clear radius, coating hue
static const float4 GHOSTS[10] = {
  float4(2.85, 3.4, 1.85, 0.1), float4(3.05, 2.4, 1.85, 0.55), float4(2.6, 2.6, 1.5, 0.8), float4(2.8, 2.0, 1.5, 0.3),
  float4(5.5, 2.2, 1.45, 0.65), float4(5.7, 3.2, 1.45, 0.2), float4(-1.95, 4.0, 1.55, 0.9), float4(4.65, 3.5, 1.55, 0.45),
  float4(6.75, 6.0, 1.4, 0.7), float4(2.35, 2.2, 1.4, 0.05) };
static const float2 GHOST_Y[10] = {           // the y range each surface occupies
  float2(5.7, 6.26), float2(4.57, 5.46), float2(4.7, 5.21), float2(4.1, 4.81),
  float2(3.29, 3.86), float2(2.49, 2.86), float2(1.73, 2.06), float2(1.14, 1.52), float2(0.74, 0.93), float2(0.14, 0.66) };
float3 lensInterior(float3 pw, float3 dw) {
  float3 o = toLens(pw);
  float3 d = normalize(dirToLens(dw));
  float3 col = float3(0.0, 0.0, 0.0);
  float yIris = 3.95;
  // where the ray meets the black inner wall (r = 2.12)
  float a = dot(d.xz, d.xz), b = dot(o.xz, d.xz), c = dot(o.xz, o.xz) - 2.12 * 2.12;
  float tWall = a > 1e-6 ? (-b + sqrt(max(b * b - a * c, 0.0))) / a : 1e5;
  float tIris = d.y < -1e-4 ? (yIris - o.y) / d.y : 1e5;
  float3 axisW = lensToWorldDir(float3(0.0, 1.0, 0.0));
  for (int i = 0; i < 10; i++) {
    float4 g = GHOSTS[i];
    float3 oc = o - float3(0.0, g.x, 0.0);
    float bb = dot(oc, d), cc = dot(oc, oc) - g.y * g.y;
    float disc = bb * bb - cc;
    if (disc < 0.0) continue;
    float sq = sqrt(disc);
    for (int k = 0; k < 2; k++) {
      float t = -bb + (k == 0 ? -sq : sq);
      if (t <= 0.0 || t > tWall) continue;
      float3 h = o + d * t;
      if (h.y < GHOST_Y[i].x || h.y > GHOST_Y[i].y || length(h.xz) > g.z) continue;
      // behind the iris only what the iris lets through counts
      if (h.y < yIris && (t > tIris && irisHole(o.xz + d.xz * tIris) > 0.0)) continue;
      float3 n = normalize(h - float3(0.0, g.x, 0.0));
      if (dot(n, d) > 0.0) n = -n;
      float3 rw = lensToWorldDir(reflect(d, n));
      float cosi = saturate(-dot(d, n));
      // coatings leave green, magenta or amber, shifting a little with angle
      float hue = frac(g.w + (1.0 - cosi) * 0.25);
      float3 tint = hue < 0.33 ? lerp(float3(0.25, 1.0, 0.45), float3(0.95, 0.35, 1.0), hue * 3.0)
                  : hue < 0.66 ? lerp(float3(0.95, 0.35, 1.0), float3(1.0, 0.62, 0.22), hue * 3.0 - 1.0)
                               : lerp(float3(1.0, 0.62, 0.22), float3(0.25, 1.0, 0.45), hue * 3.0 - 2.0);
      float esc = smoothstep(0.82, 0.97, dot(rw, axisW));
      col += tint * 0.022 * env(rw, 0.035) * esc;
    }
  }
  if (tIris < tWall) {
    float3 h = o + d * tIris;
    if (irisHole(h.xz) > 0.0) {
      // a blade: blackened steel, lit by what comes in through the front
      float3 hw = LENS_ORIGIN + float3(0.0, PIVOT_Y, 0.0) + rotZ(rotY(h, spin()) - float3(0.0, PIVOT_Y, 0.0), tilt());
      float blade = floor(atan2(h.z, h.x) / TAU * 11.0 + log(max(length(h.xz), 0.05)) * 1.9 + 0.5);
      float3 rad = normalize(float3(h.x, 0.0, h.z) + 1e-5);
      float3 tan_ = float3(-rad.z, 0.0, rad.x);
      float3 nb = normalize(float3(0.0, 1.0, 0.0) + tan_ * (0.16 * sin(blade * 2.39)) + rad * 0.07);
      return col + shadeSimple(hw, lensToWorldDir(nb), -dw, M_IRIS) * 0.9;
    }
    // through the opening and out of the back: the floor under a standing
    // lens is dark; otherwise whatever lies behind
    if (abs(param(14)) < 1.0) return col;
    float3 dd = dw * 1.0;
    return col + env(dd, 0.0) * 0.9;
  }
  return col;     // the inner wall
}

// The full light at a surface the camera sees.
float3 shadeFull(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float nv = saturate(dot(n, v));
  float occ = ambientOcc(p, n);
  float3 kd = s.albedo * (1.0 - s.metal);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, s.metal);
  float3 F = fresnelS(f0, nv, s.rough);
  // diffuse: the key box (with its shadow) and the room
  float3 L = envKeyDir();
  float nl = saturate(dot(n, L));
  float sh = nl > 0.0 ? softShadow(p + n * 0.004, L, 6.0) : 0.0;
  float pool = id > 7.5 && id < 8.5 ? exp(-dot(p.xz, p.xz) / 260.0) : 1.0;
  float3 diff = kd * (float3(1.0, 0.975, 0.94) * 2.4 * studioAmt() * nl * sh + env(n, 0.9) * 1.3 * occ) * pool;
  // specular: the studio, blurred by roughness; turned metal smears it
  // along the axis of the lens
  float3 r = reflect(-v, n);
  float blur = s.rough * s.rough * 3.2;
  float3 spec;
  if (s.aniso > 0.0) {
    float3 ax = lensToWorldDir(float3(0.0, 1.0, 0.0));
    float3 rad = lensToWorldDir(normalize(float3(q.x, 0.0, q.z) + 1e-5));
    float3 tg = normalize(cross(ax, rad));
    float3 b = normalize(cross(n, tg) + 1e-5);
    spec = float3(0.0, 0.0, 0.0);
    for (int i = -2; i <= 2; i++) {
      float3 nn = normalize(n + b * (float(i) * 0.09 * s.aniso));
      spec += env(reflect(-v, nn), blur * 0.7);
    }
    spec *= 0.2;
  } else {
    spec = env(r, blur);
  }
  // glossy things see the scene, not just the studio
  if (s.rough < 0.3 || (id > 7.5 && id < 8.5)) {
    float2 h = march(p + n * 0.006, r, 40.0, true);
    if (h.x > 0.0) {
      float3 hp = p + n * 0.006 + r * h.x;
      float3 hn = calcNormal(hp);
      float3 hit = (h.y > 4.5 && h.y < 5.5) ? env(reflect(r, hn), 0.0) * 0.1 : shadeSimple(hp, hn, -r, h.y);
      // a rough floor blurs what it reflects the farther it is
      float keep = id > 7.5 && id < 8.5 ? exp(-h.x * 1.1) * 0.35 : 1.0;
      spec = lerp(spec, hit, keep);
    }
  }
  float specOcc = lerp(occ, 1.0, 0.35) * (1.0 - 0.7 * s.cavity);
  return diff * (1.0 - 0.5 * s.cavity) + spec * F * specOcc;
}

// ------------------------------------------------------------------ camera, samples, focus
#ifndef SAMPLES
#define SAMPLES 2
#endif
#ifndef FILTER_SIGMA
#define FILTER_SIGMA 0.5
#endif
// filmic tone curve
float3 filmic(float3 c) {
  return saturate((c * (2.51 * c + 0.03)) / (c * (2.43 * c + 0.59) + 0.14));
}
float4 shade(float2 pos, float px) {
  float2 sz = size();
  float3 target = float3(param(3), param(4), param(5));
  float az = radians(param(0)), el = radians(param(1));
  float3 eye = target + param(2) * float3(sin(az) * cos(el), sin(el), cos(az) * cos(el));
  gEye = eye;
  float3 fw = normalize(target - eye);
  float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
  float3 up = cross(rt, fw);
  float focal = 1.0 / tan(radians(param(6)) * 0.5);
  gPix = 2.0 / (focal * sz.y);
  float3 acc = float3(0.0, 0.0, 0.0);
  float depth = 1e4;
  float jit = hash12(pos * 0.37 + frac(time() * 7.13));
  // The pixel's footprint is a Gaussian (sigma FILTER_SIGMA px, cut at 3 sigma),
  // sampled on a golden-angle spiral with radii drawn from its distribution:
  // edges roll off over about a pixel, as through real glass and a sensor's
  // low-pass filter, instead of stepping. Each sample is tone-mapped before
  // the average, so a sub-pixel glint on a knurl ridge adds its share of the
  // pixel instead of flashing the whole pixel white from one frame to the next.
  float cut = 1.0 - exp(-4.5);
  for (int s = 0; s < SAMPLES; s++) {
    float u = (float(s) + 0.5) / float(SAMPLES);
    float rr = FILTER_SIGMA * sqrt(-2.0 * log(1.0 - u * cut));
    float a = float(s) * 2.39996323 + jit * TAU;
    float2 o = SAMPLES > 1 ? float2(cos(a), sin(a)) * rr : float2(0.0, 0.0);
    float2 qq = (pos + o - sz * 0.5) / (sz.y * 0.5);
    float3 rd = normalize(fw * focal + rt * qq.x - up * qq.y);
    float2 hit = march(eye, rd, 400.0, true);
    float3 c;
    if (hit.x < 0.0) {
      c = backdrop(rd);
    } else {
      float3 p = eye + rd * hit.x;
      if (s == 0) depth = hit.x;
      if (hit.y > 4.5 && hit.y < 5.5) {
        c = glassPath(p, rd, glassNormal(p));
      } else {
        float3 n = calcNormal(p);
        c = shadeFull(p, n, -rd, hit.y);
        // the floor melts into the backdrop with distance
        if (hit.y > 7.5 && hit.y < 8.5) c = lerp(c, backdrop(rd), saturate((hit.x - 40.0) / 80.0));
      }
    }
    acc += filmic(c * param(9));
  }
  float3 col = acc / float(SAMPLES);
  float coc = param(8) * (1.0 - param(7) / max(depth, 0.01));
  return float4(col, clamp(coc, -48.0, 48.0));
}

// Depth of field after the render: the scene's alpha is its signed circle of
// confusion in px (+ behind the focus plane, - in front of it). Each pixel
// gathers the pixels whose discs reach it, on a golden-angle spiral; what lies
// behind may not bleed over what is sharper in front. Bright points open into
// discs, as through a fast lens.
static const float GOLDEN = 2.39996323;
static const float TAU = 6.28318531;
float4 shade(float2 pos, float px) {
  float4 c0 = input(0, pos);
  float coc0 = abs(c0.a);
  // How far this pixel must look: its own disc, or a neighbour's that reaches it.
  float reach = coc0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * (TAU / 16.0) + 0.3;
    float d = (i & 1) == 0 ? 14.0 : 30.0;
    float n = input(0, pos + float2(cos(a), sin(a)) * d).a;
    float c = n > c0.a ? min(abs(n), coc0 * 2.0) : abs(n);
    if (c > d * 0.6) reach = max(reach, c);
  }
  if (reach < 0.75) return float4(c0.rgb, 1.0);
  float3 acc = c0.rgb;
  float tot = 1.0;
  float ang = frac(sin(dot(pos, float2(12.9898, 78.233))) * 43758.5453) * TAU;
  float r = 0.75;
  float scale = reach > 20.0 ? 1.6 : 0.9;
  for (int k = 0; k < 420; k++) {
    if (r > reach + 0.5) break;
    float2 tp = pos + float2(cos(ang), sin(ang)) * r;
    float4 s = input(0, tp);
    float sc = abs(s.a);
    if (s.a > c0.a) sc = min(sc, coc0 * 2.0);
    float m = smoothstep(r - 0.75, r + 0.75, sc);
    // wide discs of bright points carry more weight: bokeh
    float hot = smoothstep(0.8, 1.0, max(s.r, max(s.g, s.b))) * smoothstep(6.0, 16.0, sc);
    float w = m * (1.0 + 2.0 * hot);
    acc += s.rgb * w;
    tot += w;
    ang += GOLDEN;
    r += scale / r;
  }
  float3 col = acc / tot;
  return float4(min(col, float3(1.0, 1.0, 1.0)), 1.0);
}

#define SAMPLES 4
#define NO_FLOOR
#define FULL_TRACE
#define CLEAR_EDGES
#define BACKLIGHT 0.55
#define BACKLIGHT_DIR float3(-0.68, 0.12, -0.73)
#define BACKLIGHT_COLOR float3(0.95, 0.96, 1.0)
// HOLM 35 f/1.4: a camera lens in a photographer's studio, raymarched.
// Units are centimetres. The lens stands on its mount at the origin with its
// optical axis up (+y); the studio is three softboxes, two strip lights and a
// black acrylic floor. Every animated value is a param:
//    0  1  2   camera orbit: azimuth, elevation (degrees), distance
//    3  4  5   camera target
//    6         vertical field of view (degrees)
//    7         focus distance (cm)        8  blur: CoC in px at twice the focus distance
//    9         exposure                   10 explode 0..1 (the optics slide out)
//    11        focus ring turn (degrees)  12 iris, stops closed from f/1.4 (0..7)
//    13        light: 0 dark, 1 the sweep crosses, 2 full studio
//    14        lens tilt about z (deg)    15 lens spin about its axis (deg)
// The image's alpha carries the signed circle of confusion for the dof pass.

static const float PI = 3.14159265;
static const float TAU = 6.28318531;

// ------------------------------------------------------------------ helpers
float3 rotY(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }
float3 rotZ(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x - s * p.y, s * p.x + c * p.y, p.z); }
float hash12(float2 p) { float3 p3 = frac(float3(p.x, p.y, p.x) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return frac((p3.x + p3.y) * p3.z); }
float box2(float2 p, float2 b, float r) { float2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
// A ring turned on a lathe: radii r0..r1, heights y0..y1, its edges broken by e.
float ring(float2 ry, float r0, float r1, float y0, float y1, float e) {
  return box2(ry - float2((r0 + r1) * 0.5, (y0 + y1) * 0.5), float2((r1 - r0) * 0.5, (y1 - y0) * 0.5), e);
}
float2 opU(float2 a, float2 b) { return a.x < b.x ? a : b; }
float fbm2(float2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { s += a * snoise(float3(p, 0.37 * float(i))); p = p * 2.1 + float2(1.7, 9.2); a *= 0.5; } return s; }
float tri(float x) { return abs(frac(x) - 0.5) * 2.0; }        // 1 at integers, 0 halfway
// polynomial smooth min / max: blends a and b over a band k wide
float smin(float a, float b, float k) { float h = max(k - abs(a - b), 0.0) / k; return min(a, b) - h * h * k * 0.25; }
float smax(float a, float b, float k) { return -smin(-a, -b, k); }
float ease(float x) { x = saturate(x); return x * x * (3.0 - 2.0 * x); }

// ------------------------------------------------------------------ materials
#define M_SILVER 1.0
#define M_KNURL 2.0
#define M_BLACK 3.0
#define M_CHROME 4.0
#define M_GLASS 5.0
#define M_FLOCK 6.0
#define M_IRIS 7.0
#define M_FLOOR 8.0
#define M_EDGE 9.0
#define M_RIDGE 10.0
#define M_GOLD 11.0
#define M_ORANGE 12.0
#define M_GROUND 13.0

// ------------------------------------------------------------------ per-pixel camera state
static float3 gEye;
static float gPix;      // world size of one pixel at unit distance

float tilt() { return radians(param(14)); }
float spin() { return radians(param(15)); }
float explode() { return param(10); }

static const float3 LENS_ORIGIN = float3(0.0, 0.52, 0.0);   // the mount flange, in the world
static const float PIVOT_Y = 3.3;                            // where the lens turns when it tilts
float3 toLens(float3 p) {
  float3 q = p - LENS_ORIGIN - float3(0.0, PIVOT_Y, 0.0);
  q = rotZ(q, -tilt());
  q.y += PIVOT_Y;
  return rotY(q, -spin());
}
float3 lensToWorldDir(float3 v) { return rotZ(rotY(v, spin()), tilt()); }

// ------------------------------------------------------------------ the optics
// Eight elements in six groups, front to back. Each: centre height, centre
// thickness, front radius (+ convex), back radius (+ convex), clear radius.
// Exploded, each group slides forward to its own place on the axis.
static const float EXPLODE_BARREL = 3.4;
float groupShift(int g) {
  // front groups leave first; each eases out on its own beat
  static const float DY[7] = { 13.6, 11.9, 10.3, 9.0, 7.7, 6.6, 5.4 };
  float e = explode();
  float k = ease(e * 1.45 - float(g) * 0.075);
  return DY[g] * k;
}
float barrelShift() { return -EXPLODE_BARREL * ease(explode() * 1.3); }

// a spherical surface: + convex toward its side, - concave
float surfFront(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv - R)) - R;
  return max(-R - length(ry - float2(0.0, yv - R)), ry.y - (yv - R));
}
float surfBack(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv + R)) - R;
  return max(-R - length(ry - float2(0.0, yv + R)), (yv + R) - ry.y);
}
float element(float2 ry, float yc, float t, float Rf, float Rb, float a, out float edge) {
  float f = surfFront(ry, yc + t * 0.5, Rf);
  float b = surfBack(ry, yc - t * 0.5, Rb);
  float c = ry.x - a;
  float d = max(max(f, b), c);
  edge = c > max(f, b) - 0.002 ? 1.0 : 0.0;
  return d;
}

// The glass alone (for marching inside it). id = 5 glass, 9 inked edge.
float2 glassMap(float3 q) {
  float r = length(q.xz);
#ifdef CLEAR_EDGES
  const float EDGE_ID = M_GROUND;
#else
  const float EDGE_ID = M_EDGE;
#endif
  if (r > 2.3) return float2(r - 2.2, M_GLASS);
  float2 res = float2(1e5, M_GLASS);
  float edge;
  float y;
  // G1: E1 positive meniscus
  y = q.y - groupShift(0);
  float d = element(float2(r, y), 6.75, 0.5, 4.8, -9.0, 2.12, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G2: E2 + E3 cemented
  y = q.y - groupShift(1);
  d = element(float2(r, y), 6.0, 0.5, 3.4, -6.0, 1.85, edge);
  float e3 = max(max(max(length(float2(r, y) - float2(0.0, -0.25)) - 6.0, 2.4 - length(float2(r, y) - float2(0.0, 3.05))), r - 1.85), 3.05 - y);
  float edge3 = (r - 1.85) > -0.002 ? 1.0 : 0.0;
  d = min(d, e3);
  res = opU(res, float2(d, (edge > 0.5 || edge3 > 0.5) && r > 1.83 ? EDGE_ID : M_GLASS));
  // G3: E4 meniscus
  y = q.y - groupShift(2);
  d = element(float2(r, y), 5.0, 0.4, 2.6, -2.0, 1.5, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G4: E5 + E6 cemented (concave toward the iris)
  y = q.y - groupShift(4);
  float e5 = max(max(2.2 - length(float2(r, y) - float2(0.0, 5.5)), length(float2(r, y) - float2(0.0, 8.05)) - 5.0), r - 1.45);
  float e6 = max(max(5.0 - length(float2(r, y) - float2(0.0, 8.05)), length(float2(r, y) - float2(0.0, 5.7)) - 3.2), r - 1.45);
  e5 = max(e5, y - 3.95);
  d = min(e5, e6);
  res = opU(res, float2(d, r > 1.43 ? EDGE_ID : M_GLASS));
  // G5: E7 biconvex
  y = q.y - groupShift(5);
  d = element(float2(r, y), 1.6, 0.9, 4.0, 3.5, 1.55, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G6: E8, the rear element: its back face aspherical (a fourth-order term
  // flattens it toward the edge)
  y = q.y - groupShift(6);
  float f8 = surfFront(float2(r, y), 0.75, -6.0);
  float b8 = length(float2(r, y) - float2(0.0, 2.35)) - 2.2 + 0.012 * r * r * r * r;
  float c8 = r - 1.4;
  d = max(max(f8, b8), c8);
  res = opU(res, float2(d, c8 > max(f8, b8) - 0.002 ? EDGE_ID : M_GLASS));
  return res;
}

// The iris: eleven rounded blades between G3 and G4.
float irisRadius() { return 1.0 * 1.4 / (1.4 * pow(2.0, param(12) * 0.5)); }
float irisHole(float2 xz) {
  float a = irisRadius();
  float ang = atan2(xz.y, xz.x) + param(12) * 0.06;
  float sec = TAU / 11.0;
  float f = (frac(ang / sec) - 0.5) * sec;
  float rr = length(xz);
  float poly = rr * cos(f) - a;
  return lerp(poly, rr - a * 1.04, 0.55);     // blades are curved: rounder than a polygon
}
float irisMap(float3 q) {
  float y = q.y - 3.95 - groupShift(3);
  float r = length(q.xz);
  float disc = max(abs(y) - 0.022, r - 2.08);
  return max(disc, -irisHole(q.xz));
}

// ------------------------------------------------------------------ the barrel
// Diamond knurl on the focus ring, straight ridges on the aperture ring; both
// fade into a flat average where a pixel is wider than their pitch.
float knurlH(float3 q, float y, float fade) {
  float th = atan2(q.z, q.x) + radians(param(11));
  float u = th * (96.0 / TAU);
  float v = y / 0.2;
  // rolled, not cut: the crests, the valleys and the edges between facets are
  // rounded, so a crest catches the light as a soft line a few pixels wide
  // rather than a sub-pixel glint that flickers as the ring turns
  float h = smin(tri(u + v), tri(u - v), 0.08);
  h = smax(smin(h, 0.93, 0.12), 0.04, 0.08);
  return (h * 0.9 - 0.45) * 0.05 * fade;
}
float ridgeH(float3 q, float fade) {
  float th = atan2(q.z, q.x) + radians(param(12) * 12.0);
  float u = th * (180.0 / TAU);
  float h = smoothstep(0.0, 1.0, tri(u));
  return (h - 0.5) * 0.016 * fade;
}
float lodFade(float3 q, float pitch) {
  float3 e = toLens(gEye) - q;
  float d = length(e);
  float graze = abs(dot(normalize(float3(q.x, 0.0, q.z)), e / d));
  float foot = d * gPix / max(graze, 0.12);
  return smoothstep(pitch * 1.1, pitch * 0.45, foot);
}

float2 barrelMap(float3 q) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float2 ry = float2(r, y);
  float bound = ring(ry, 1.85, 3.25, -0.62, 7.3, 0.0);
  if (bound > 0.25) return float2(bound, M_SILVER);
  float2 res = float2(1e5, M_SILVER);
  // mount: chrome tube, flange and three bayonet lugs
  float th = atan2(q.z, q.x);
  float sector = abs(frac(th * 3.0 / TAU + 0.083) - 0.5) * (TAU / 3.0) * r;
  float lug = max(ring(ry, 1.98, 2.44, -0.52, -0.40, 0.02), sector - 0.95);
  float tube = ring(ry, 1.95, 2.33, -0.40, 0.02, 0.03);
  float flange = ring(ry, 2.2, 2.6, -0.09, 0.0, 0.02);
  res = opU(res, float2(min(min(lug, tube), flange), M_CHROME));
  // rear barrel: narrower than the rings above it, its foot broken wide
  res = opU(res, float2(ring(ry, 2.2, 2.78, 0.03, 1.36, 0.1), M_SILVER));
  // aperture ring with its ridged grip
  float ar = ring(ry, 2.25, 2.95, 1.42, 2.52, 0.05);
  if (y > 1.5 && y < 1.98 && r > 2.75) ar += ridgeH(q, lodFade(q, 0.105)) * smoothstep(1.5, 1.56, y) * smoothstep(1.98, 1.92, y);
  res = opU(res, float2(ar, (y > 1.49 && y < 1.99 && r > 2.85) ? M_RIDGE : M_SILVER));
  // the fixed scale ring (black anodised)
  res = opU(res, float2(ring(ry, 2.25, 2.84, 2.58, 3.04, 0.035), M_BLACK));
  // focus ring: a smooth scale band, a step, the knurl: the widest part
  float fr = ring(ry, 2.25, 3.08, 3.10, 5.62, 0.06);
  float step = ring(ry, 2.25, 3.13, 3.80, 5.46, 0.05);
  fr = min(fr, step);
  if (y > 3.8 && y < 5.46 && r > 2.95) fr += knurlH(q, y, lodFade(q, 0.2)) * smoothstep(3.84, 3.9, y) * smoothstep(5.42, 5.36, y);
  res = opU(res, float2(fr, (y > 3.83 && y < 5.43 && r > 3.03) ? M_KNURL : M_SILVER));
  // front barrel: tapering toward the front, two fine turned grooves
  float R = 3.0 - (clamp(y, 5.68, 6.96) - 5.68) * 0.055;
  float fb = box2(ry - float2((2.2 + R) * 0.5, 6.32), float2((R - 2.2) * 0.5, 0.64), 0.06);
  float gr = min(box2(ry - float2(R, 6.5), float2(0.02, 0.012), 0.008), box2(ry - float2(R, 6.64), float2(0.02, 0.012), 0.008));
  fb = max(fb, -gr);
  res = opU(res, float2(fb, M_SILVER));
  // a thin ring of orange anodising under the name ring
  res = opU(res, float2(ring(ry, 2.6, 2.935, 6.965, 7.055, 0.012), M_ORANGE));
  // the name ring: black, its front face engraved
  float nr = ring(ry, 2.22, 2.92, 7.06, 7.24, 0.04);
  res = opU(res, float2(nr, M_BLACK));
  // the inside: a light trap lining the metal (the innermost surface)
  float inner = ring(ry, 2.15, 2.27, 0.05, 7.2, 0.01);
  res = opU(res, float2(inner, M_FLOCK));
  return res;
}

// ------------------------------------------------------------------ the scene
static const float FLOOR_Y = 0.0;
float2 mapScene(float3 p, bool withGlass) {
  float2 res = float2(p.y - FLOOR_Y, M_FLOOR);
#ifdef NO_FLOOR
  res.x = 1e5;
#endif
  float3 q = toLens(p);
  res = opU(res, barrelMap(q));
  float rq = length(q.xz);
  if (rq < 2.4) {
    res = opU(res, float2(irisMap(q), M_IRIS));
    // the G1 retaining ring travels with the front element
    float y1 = q.y - groupShift(0);
    res = opU(res, float2(ring(float2(rq, y1), 2.02, 2.2, 6.58, 6.68, 0.01), M_FLOCK));
    if (withGlass) res = opU(res, glassMap(q));
  } else if (withGlass) {
    res = opU(res, float2(rq - 2.3, M_GLASS));
  }
  return res;
}
float2 map(float3 p) { return mapScene(p, true); }

float3 calcNormal(float3 p) {
  float2 e = float2(0.0007, -0.0007);
  return normalize(e.xyy * map(p + e.xyy).x + e.yyx * map(p + e.yyx).x + e.yxy * map(p + e.yxy).x + e.xxx * map(p + e.xxx).x);
}
float3 glassNormal(float3 p) {
  float2 e = float2(0.0006, -0.0006);
  float3 q = toLens(p);
  // gradient in lens space, turned back to the world
  float3 n = e.xyy * glassMap(q + e.xyy).x + e.yyx * glassMap(q + e.yyx).x + e.yxy * glassMap(q + e.yxy).x + e.xxx * glassMap(q + e.xxx).x;
  return normalize(lensToWorldDir(n));
}
float2 march(float3 ro, float3 rd, float maxd, bool withGlass) {
  float t = 0.0;
  for (int i = 0; i < 200; i++) {
    float2 h = mapScene(ro + rd * t, withGlass);
    if (abs(h.x) < 0.00025 * t + 0.0004) return float2(t, h.y);
    t += h.x * 0.85;
    if (t > maxd) break;
  }
  return float2(-1.0, 0.0);
}

// ------------------------------------------------------------------ the studio
// A softbox seen in direction d: a rounded rectangle on the plane facing the
// lens, its edges softened by `blur` (roughness widens it, keeping its energy).
float window1(float x, float a, float e) { return smoothstep(-a - e, -a + e, x) - smoothstep(a - e, a + e, x); }
// A softbox seen in direction d: a rectangle on the plane facing the lens,
// brighter at its centre, its edges softened by `blur` (roughness widens
// them, keeping the energy).
float softbox(float3 d, float3 c, float3 up, float2 half_, float blur) {
  float k = dot(d, c);
  if (k <= 0.02) return 0.0;
  float3 rt = normalize(cross(up, c));
  float3 u2 = cross(c, rt);
  float2 uv = float2(dot(d, rt), dot(d, u2)) / k;
  float fall = 1.0 - 0.45 * dot(uv / half_, uv / half_) * 0.5;
  return window1(uv.x, half_.x, 0.012 + blur) * window1(uv.y, half_.y, 0.012 + blur) * max(fall, 0.3);
}
// The light cue (param 13): 0..1 the rim strips outline the lens, 1..2 a
// strip sweeps across its front, 1.8..3 the studio comes up (overlapping it).
float rimAmt() { return saturate(param(13)); }
float sweepAmt() { return saturate(param(13) - 1.0); }
float studioAmt() { return saturate((param(13) - 1.8) / 1.2); }
#ifndef ENV_YAW
#define ENV_YAW 0.0
#endif
float3 env(float3 d, float blur) {
  d = rotY(d, radians(ENV_YAW));
  float s = studioAmt();
  float rim = rimAmt();
#ifdef STUDIO_SCALE
  float big = s * STUDIO_SCALE;
#else
  float big = s;
#endif
#ifdef RIM_SCALE
  rim *= RIM_SCALE;
#endif
  // the dark room: a little light up high, nearly black low down
  float3 c = lerp(float3(0.004, 0.004, 0.0042), float3(0.02, 0.0195, 0.019), saturate(d.y * 0.8 + 0.3)) * (0.15 + 0.85 * s);
  // key: a big box front left, high
  c += float3(1.0, 0.975, 0.94) * 2.6 * big * softbox(d, normalize(float3(-0.62, 0.5, 0.6)), float3(0, 1, 0), float2(0.55, 0.62), blur);
  // overhead scrim: broad and soft
  c += float3(0.95, 0.965, 1.0) * 1.5 * big * softbox(d, float3(0.0, 1.0, 0.0), float3(0, 0, -1), float2(1.1, 0.8), blur);
  // fill: a white card front right
  c += float3(1.0, 0.99, 0.97) * 0.75 * big * softbox(d, normalize(float3(0.7, 0.12, 0.7)), float3(0, 1, 0), float2(0.42, 0.55), blur);
  // two tall strips behind, one each side: the rims
  c += float3(0.93, 0.96, 1.0) * 6.5 * rim * softbox(d, normalize(float3(-0.9, 0.1, -0.42)), float3(0, 1, 0), float2(0.07, 1.0), blur);
  c += float3(1.0, 0.97, 0.94) * 5.5 * rim * softbox(d, normalize(float3(0.88, 0.14, -0.46)), float3(0, 1, 0), float2(0.055, 1.0), blur);
#ifdef LIGHTBOX
  // a small square box just over the camera's shoulder: the glints in the glass
  c += float3(1.0, 0.98, 0.95) * LIGHTBOX * softbox(d, normalize(LIGHTBOX_DIR), float3(0, 1, 0), float2(0.085, 0.085), blur);
#endif
#ifdef BACKLIGHT
#ifndef BACKLIGHT_COLOR
#define BACKLIGHT_COLOR float3(1.0, 0.9, 0.78)
#endif
  // a round light hidden behind the lens: seen only through it
  float bl = dot(d, normalize(BACKLIGHT_DIR));
  c += BACKLIGHT_COLOR * BACKLIGHT * smoothstep(0.3, 0.85, bl) * (0.6 + 0.4 * smoothstep(0.85, 1.0, bl));
#endif
  // the sweep: one strip that travels round the front of the lens
  float sw = sweepAmt();
  if (sw > 0.0 && sw < 1.0) {
    float a = lerp(-1.9, 1.6, sw);
    float3 sd = normalize(float3(sin(a), 0.22, cos(a)));
    c += float3(1.0, 0.98, 0.95) * 9.0 * softbox(d, sd, float3(0, 1, 0), float2(0.07, 1.2), blur) * smoothstep(0.0, 0.1, sw) * smoothstep(1.0, 0.8, sw) * (1.0 - s);
  }
  return c;
}
float3 envKeyDir() { return rotY(normalize(float3(-0.62, 0.5, 0.6)), -radians(ENV_YAW)); }

// What the camera sees past everything: a dark seamless sweep with a soft
// pool of light behind the lens.
float3 backdrop(float3 rd) {
  float s = max(studioAmt(), rimAmt() * 0.25);
  float3 base = float3(0.006, 0.0062, 0.0068);
  float3 toL = normalize(float3(0.0, 4.6, 0.0) - gEye);
  float halo = exp(-(1.0 - dot(rd, toL)) * 7.0);
  float3 c = base * (0.35 + 0.65 * s) + float3(0.03, 0.029, 0.028) * halo * s;
#ifdef BACKLIGHT
  // the panel behind lights the wall a little too
  c += float3(0.92, 0.93, 0.95) * BACKLIGHT * 0.03 * exp(-(1.0 - dot(rd, toL)) * 4.0);
#endif
  return c;
}

// ------------------------------------------------------------------ engravings
// Input 0 is an atlas of the engraved scales, drawn as ordinary text: four
// bands, each a range of ring angles across the frame's width and a range of
// heights (or radii) down its rows (BANDS in product.py holds the same numbers).
float wrapInto(float a, float a0) { return a0 + fmod(fmod(a - a0, 360.0) + 360.0, 360.0); }
float4 atlasBand(float alpha, float h, float a0, float a1, float h0, float h1, float r0, float r1, bool ltr) {
  float a = wrapInto(alpha, a0);
  if (a > a1) return float4(0.0, 0.0, 0.0, 0.0);
  float t = (h0 - h) / (h0 - h1);
  if (t < 0.0 || t > 1.0) return float4(0.0, 0.0, 0.0, 0.0);
  float x = ltr ? (a - a0) / (a1 - a0) : (a1 - a) / (a1 - a0);
  return input(0, float2(x * 1920.0, r0 + t * (r1 - r0)));
}
float4 engraving(float3 q, float3 n, float id) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float th = degrees(atan2(q.z, q.x));
  if (id < 1.5) {
    if (r > 3.0 && y > 3.12 && y < 3.78) return atlasBand(th + param(11), y, 60.0, 260.0, 3.76, 3.14, 0.0, 111.0, false);
    if (r > 2.92 && y > 2.0 && y < 2.5) return atlasBand(th + param(12) * 12.0, y, 70.0, 200.0, 2.47, 2.02, 130.0, 257.0, false);
  } else if (id < 3.5) {
    if (r > 2.8 && y > 2.58 && y < 3.04) return atlasBand(th, y, 50.0, 130.0, 3.02, 2.60, 300.0, 521.0, false);
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    if (y > 7.15 && ax > 0.9) return atlasBand(th, r, 150.0, 390.0, 2.88, 2.40, 540.0, 620.0, true);
  }
  return float4(0.0, 0.0, 0.0, 0.0);
}

// ------------------------------------------------------------------ surfaces
struct Surf { float3 albedo; float metal; float rough; float aniso; float cavity; };

Surf surface(float id, float3 p, float3 q, float3 n) {
  Surf s;
  s.albedo = float3(0.8, 0.8, 0.8); s.metal = 0.0; s.rough = 0.5; s.aniso = 0.0; s.cavity = 0.0;
  float r = length(q.xz);
  float y = q.y - barrelShift();
  if (id < 1.5) {               // turned, bead-blasted aluminium, clear anodised
    // bead-blasted, clear anodised; the edges are diamond-cut and polished
    s.albedo = float3(0.9, 0.905, 0.91); s.metal = 1.0; s.aniso = 0.8;
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    float chamfer = smoothstep(0.12, 0.3, ax) * smoothstep(0.995, 0.95, ax);
    s.rough = lerp(0.5 + 0.06 * snoise(q * 40.0), 0.12, chamfer);
    s.aniso = lerp(0.8, 0.2, chamfer);
    // the mounting index: an orange dot on the rear barrel, facing the scales
    float dotd = length(float2((atan2(q.z, q.x) - 1.5708) * r, y - 0.72));
    float dotc = smoothstep(0.075, 0.062, dotd) * step(r, 2.8) * step(2.7, r);
    s.albedo = lerp(s.albedo, float3(0.8, 0.14, 0.035), dotc); s.metal = lerp(s.metal, 0.0, dotc); s.rough = lerp(s.rough, 0.6, dotc);
  } else if (id < 2.5) {        // knurl: same metal, sharper facets
    s.albedo = float3(0.86, 0.865, 0.87); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.2));
  } else if (id < 3.5) {        // black anodised: a dielectric skin over metal
    s.albedo = float3(0.02, 0.02, 0.022); s.metal = 0.0; s.rough = 0.42 + 0.04 * snoise(q * 30.0);
  } else if (id < 4.5) {        // chrome-plated brass mount
    s.albedo = float3(0.95, 0.95, 0.96); s.metal = 1.0; s.rough = 0.06;
  } else if (id < 5.5) {        // glass (handled by the glass path)
    s.albedo = float3(1.0, 1.0, 1.0); s.metal = -1.0; s.rough = 0.0;
  } else if (id < 6.5) {        // flocking: the inside eats light
    s.albedo = float3(0.006, 0.006, 0.007); s.metal = 0.0; s.rough = 0.9;
  } else if (id < 7.5) {        // iris blades: blackened steel with a sheen
    s.albedo = float3(0.035, 0.035, 0.04); s.metal = 0.0; s.rough = 0.26;
    float ang = atan2(q.z, q.x);
    float x = (ang / TAU) * 11.0 + log(max(r, 0.05)) * 1.9;
    float seam = tri(x);
    float blade = floor(x + 0.5);
    s.albedo = float3(0.03, 0.03, 0.034) * (0.6 + 0.8 * frac(sin(blade * 12.9898) * 43758.5453));
    s.rough = 0.22;
    s.albedo *= 0.35 + 0.65 * smoothstep(0.0, 0.1, seam);
  } else if (id < 8.5) {        // black acrylic floor
    s.albedo = float3(0.014, 0.014, 0.015) * (0.9 + 0.1 * fbm2(p.xz * 0.6)); s.metal = 0.0; s.rough = 0.28;
  } else if (id < 9.5) {        // inked edges of the glass
    s.albedo = float3(0.012, 0.012, 0.013); s.metal = 0.0; s.rough = 0.6;
  } else if (id > 12.5 && id < 13.5) {  // a ground glass edge, milky
    s.albedo = float3(0.42, 0.45, 0.44); s.metal = 0.0; s.rough = 0.55;
  } else if (id > 11.5 && id < 12.5) {  // orange anodised aluminium
    s.albedo = float3(0.92, 0.3, 0.085); s.metal = 1.0; s.rough = 0.3; s.aniso = 0.5;
  } else if (id < 10.5) {       // ridges of the aperture ring
    s.albedo = float3(0.88, 0.885, 0.89); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.105));
  }
  // engraved and filled with paint
  if (id < 3.5 && id != 2.0) {
    float4 e = engraving(q, n, id);
    if (e.a > 0.002) {
      // white in the atlas is the primary fill: black on silver, white on black
      float3 ink = e.rgb / e.a;
      float white = saturate((ink.b - 0.5) * 4.0);
      float3 primary = id < 1.5 ? float3(0.005, 0.005, 0.0055) : float3(0.78, 0.78, 0.76);
      ink = lerp(ink * 0.85, primary, white);
      s.albedo = lerp(s.albedo, ink, e.a);
      s.metal = lerp(s.metal, 0.0, e.a);
      s.rough = lerp(s.rough, 0.85, e.a);
      s.aniso *= 1.0 - e.a;
      s.cavity = e.a;
      s.albedo *= 1.0 - 2.0 * e.a * (1.0 - e.a);     // the walls of the cut
    }
  }
  return s;
}

// ------------------------------------------------------------------ light
float softShadow(float3 ro, float3 rd, float k) {
  float res = 1.0, t = 0.02;
  for (int i = 0; i < 48; i++) {
    float h = mapScene(ro + rd * t, false).x;
    res = min(res, k * h / t);
    t += clamp(h, 0.02, 0.6);
    if (res < 0.002 || t > 30.0) break;
  }
  return saturate(res);
}
float ambientOcc(float3 p, float3 n) {
  float occ = 0.0, sca = 1.0;
  for (int i = 0; i < 5; i++) {
    float h = 0.02 + 0.12 * float(i);
    occ += (h - map(p + n * h).x) * sca;
    sca *= 0.7;
  }
  return saturate(1.0 - 1.6 * occ);
}
float3 fresnelS(float3 f0, float nv, float rough) {
  return f0 + (max(float3(1.0 - rough, 1.0 - rough, 1.0 - rough), f0) - f0) * pow(1.0 - nv, 5.0);
}

// Light reflected by a surface (one bounce of the studio): simple, for what
// glass and mirrors see.
float3 shadeSimple(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float3 r = reflect(-v, n);
  float3 kd = s.albedo * (1.0 - max(s.metal, 0.0));
  float key = studioAmt() * saturate(dot(n, envKeyDir()));
  if (id > 7.5 && id < 8.5 && abs(param(14)) < 1.0) kd *= smoothstep(2.4, 3.4, length(p.xz - LENS_ORIGIN.xz));
  if (id > 7.5 && id < 8.5 && key > 0.0) key *= softShadow(p + n * 0.01, envKeyDir(), 6.0);
  float3 diff = kd * (env(n, 0.9) * 1.2 + float3(1.0, 0.97, 0.94) * 2.2 * key);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, max(s.metal, 0.0));
  float3 spec = env(r, s.rough * s.rough * 3.2) * fresnelS(f0, saturate(dot(n, v)), s.rough);
  return diff + spec;
}

// Thin-film anti-reflection coating: a faint reflection that leans green
// head-on and magenta toward the edge, a different cast on each surface.
float3 coatF(float cosi, float k) {
  float h = frac(k * 0.37 + (1.0 - cosi) * 0.6);
  float3 tint = h < 0.5 ? lerp(float3(0.3, 1.0, 0.5), float3(0.9, 0.4, 1.0), h * 2.0) : lerp(float3(0.9, 0.4, 1.0), float3(0.3, 1.0, 0.5), h * 2.0 - 1.0);
  float3 r0 = 0.004 + 0.02 * tint;
  return r0 + (1.0 - r0) * pow(1.0 - cosi, 5.0);
}

#define GLASS_IOR 1.62
// Light through the optics: refract in, cross each element, refract out,
// gathering each surface's coated reflection of the studio on the way.
float3 glassPath(float3 pos, float3 dir, float3 n) {
  float3 col = float3(0.0, 0.0, 0.0);
  float3 thr = float3(1.0, 1.0, 1.0);
  float3 dir0 = dir;
  bool inside = false;
  float3 nn = n;                 // faces against the ray
  float3 axis = lensToWorldDir(float3(0.0, 1.0, 0.0));
  float open = ease(explode() * 3.0);
  for (int k = 0; k < 16; k++) {
    float cosi = saturate(-dot(dir, nn));
    float3 F = coatF(cosi, float(k));
    float3 rdir = reflect(dir, nn);
    // inside the barrel a reflection only sees the studio through the front
    float esc = k == 0 ? 1.0 : lerp(smoothstep(0.8, 0.97, dot(rdir, axis)), 1.0, open);
    col += thr * F * (inside ? 0.35 : 1.0) * env(rdir, 0.0) * esc;
    thr *= 1.0 - F;
    float3 t = refract(dir, nn, inside ? GLASS_IOR : 1.0 / GLASS_IOR);
    bool tir = dot(t, t) < 1e-5;
    if (tir) { dir = rdir; } else { dir = t; inside = !inside; }
    // step off the surface to the side the ray now travels
    pos += (dot(dir, nn) < 0.0 ? -nn : nn) * 0.0025;
    if (inside) {
      // through the glass to where the ray leaves it
      float s = 0.0;
      float2 g = float2(-1.0, M_GLASS);
      for (int i = 0; i < 80; i++) {
        g = glassMap(toLens(pos + dir * s));
        if (-g.x < 0.0003 || s > 8.0) break;
        s += max(-g.x, 0.0015);
      }
      pos += dir * s;
      if (g.y > 8.5) return col;          // out through an edge: lost
      nn = -glassNormal(pos);
      thr *= float3(0.985, 0.99, 0.982);  // a whisper of green from the glass itself
#ifndef FULL_TRACE
      if (explode() < 0.001) {
        // leave the front element, then the inside of the lens; light
        // trapped in the glass is lost
        float3 t2 = refract(dir, nn, GLASS_IOR);
        if (dot(t2, t2) < 1e-5) return col;
        float c2 = saturate(-dot(dir, nn));
        float3 F2 = coatF(c2, 1.0);
        col += thr * min(F2, float3(0.03, 0.03, 0.03)) * 0.35 * env(reflect(dir, nn), 0.0) * smoothstep(0.8, 0.97, dot(reflect(dir, nn), axis));
        return col + thr * (1.0 - F2) * lensInterior(pos - nn * 0.003, t2);
      }
#endif
    } else {
      float2 h = march(pos, dir, 60.0, true);
      if (h.x < 0.0) {
        // out of the lens into the studio, split by wavelength
        float3 dev = (dir - dir0) * 0.06;
        col += thr * float3(env(dir - dev, 0.0).r, env(dir, 0.0).g, env(dir + dev, 0.0).b);
        return col;
      }
      pos = pos + dir * h.x;
      if (h.y > 4.5 && h.y < 5.5) {
        nn = glassNormal(pos);
      } else {
        col += thr * shadeSimple(pos, calcNormal(pos), -dir, h.y);
        return col;
      }
    }
  }
  return col;
}


// ------------------------------------------------------------------ inside the assembled lens
// Past the front element the light is followed along a straight line: every
// inner surface it crosses adds its coated ghost of the studio, the iris
// stops it or lets it through, the barrel's black walls swallow the rest.
// (A full trace through eight curved elements is correct and unreadable.)
float3 dirToLens(float3 v) { return rotY(rotZ(v, -tilt()), -spin()); }
// sphere surfaces of the inner elements: centre height, radius, clear radius, coating hue
static const float4 GHOSTS[10] = {
  float4(2.85, 3.4, 1.85, 0.1), float4(3.05, 2.4, 1.85, 0.55), float4(2.6, 2.6, 1.5, 0.8), float4(2.8, 2.0, 1.5, 0.3),
  float4(5.5, 2.2, 1.45, 0.65), float4(5.7, 3.2, 1.45, 0.2), float4(-1.95, 4.0, 1.55, 0.9), float4(4.65, 3.5, 1.55, 0.45),
  float4(6.75, 6.0, 1.4, 0.7), float4(2.35, 2.2, 1.4, 0.05) };
static const float2 GHOST_Y[10] = {           // the y range each surface occupies
  float2(5.7, 6.26), float2(4.57, 5.46), float2(4.7, 5.21), float2(4.1, 4.81),
  float2(3.29, 3.86), float2(2.49, 2.86), float2(1.73, 2.06), float2(1.14, 1.52), float2(0.74, 0.93), float2(0.14, 0.66) };
float3 lensInterior(float3 pw, float3 dw) {
  float3 o = toLens(pw);
  float3 d = normalize(dirToLens(dw));
  float3 col = float3(0.0, 0.0, 0.0);
  float yIris = 3.95;
  // where the ray meets the black inner wall (r = 2.12)
  float a = dot(d.xz, d.xz), b = dot(o.xz, d.xz), c = dot(o.xz, o.xz) - 2.12 * 2.12;
  float tWall = a > 1e-6 ? (-b + sqrt(max(b * b - a * c, 0.0))) / a : 1e5;
  float tIris = d.y < -1e-4 ? (yIris - o.y) / d.y : 1e5;
  float3 axisW = lensToWorldDir(float3(0.0, 1.0, 0.0));
  for (int i = 0; i < 10; i++) {
    float4 g = GHOSTS[i];
    float3 oc = o - float3(0.0, g.x, 0.0);
    float bb = dot(oc, d), cc = dot(oc, oc) - g.y * g.y;
    float disc = bb * bb - cc;
    if (disc < 0.0) continue;
    float sq = sqrt(disc);
    for (int k = 0; k < 2; k++) {
      float t = -bb + (k == 0 ? -sq : sq);
      if (t <= 0.0 || t > tWall) continue;
      float3 h = o + d * t;
      if (h.y < GHOST_Y[i].x || h.y > GHOST_Y[i].y || length(h.xz) > g.z) continue;
      // behind the iris only what the iris lets through counts
      if (h.y < yIris && (t > tIris && irisHole(o.xz + d.xz * tIris) > 0.0)) continue;
      float3 n = normalize(h - float3(0.0, g.x, 0.0));
      if (dot(n, d) > 0.0) n = -n;
      float3 rw = lensToWorldDir(reflect(d, n));
      float cosi = saturate(-dot(d, n));
      // coatings leave green, magenta or amber, shifting a little with angle
      float hue = frac(g.w + (1.0 - cosi) * 0.25);
      float3 tint = hue < 0.33 ? lerp(float3(0.25, 1.0, 0.45), float3(0.95, 0.35, 1.0), hue * 3.0)
                  : hue < 0.66 ? lerp(float3(0.95, 0.35, 1.0), float3(1.0, 0.62, 0.22), hue * 3.0 - 1.0)
                               : lerp(float3(1.0, 0.62, 0.22), float3(0.25, 1.0, 0.45), hue * 3.0 - 2.0);
      float esc = smoothstep(0.82, 0.97, dot(rw, axisW));
      col += tint * 0.022 * env(rw, 0.035) * esc;
    }
  }
  if (tIris < tWall) {
    float3 h = o + d * tIris;
    if (irisHole(h.xz) > 0.0) {
      // a blade: blackened steel, lit by what comes in through the front
      float3 hw = LENS_ORIGIN + float3(0.0, PIVOT_Y, 0.0) + rotZ(rotY(h, spin()) - float3(0.0, PIVOT_Y, 0.0), tilt());
      float blade = floor(atan2(h.z, h.x) / TAU * 11.0 + log(max(length(h.xz), 0.05)) * 1.9 + 0.5);
      float3 rad = normalize(float3(h.x, 0.0, h.z) + 1e-5);
      float3 tan_ = float3(-rad.z, 0.0, rad.x);
      float3 nb = normalize(float3(0.0, 1.0, 0.0) + tan_ * (0.16 * sin(blade * 2.39)) + rad * 0.07);
      return col + shadeSimple(hw, lensToWorldDir(nb), -dw, M_IRIS) * 0.9;
    }
    // through the opening and out of the back: the floor under a standing
    // lens is dark; otherwise whatever lies behind
    if (abs(param(14)) < 1.0) return col;
    float3 dd = dw * 1.0;
    return col + env(dd, 0.0) * 0.9;
  }
  return col;     // the inner wall
}

// The full light at a surface the camera sees.
float3 shadeFull(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float nv = saturate(dot(n, v));
  float occ = ambientOcc(p, n);
  float3 kd = s.albedo * (1.0 - s.metal);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, s.metal);
  float3 F = fresnelS(f0, nv, s.rough);
  // diffuse: the key box (with its shadow) and the room
  float3 L = envKeyDir();
  float nl = saturate(dot(n, L));
  float sh = nl > 0.0 ? softShadow(p + n * 0.004, L, 6.0) : 0.0;
  float pool = id > 7.5 && id < 8.5 ? exp(-dot(p.xz, p.xz) / 260.0) : 1.0;
  float3 diff = kd * (float3(1.0, 0.975, 0.94) * 2.4 * studioAmt() * nl * sh + env(n, 0.9) * 1.3 * occ) * pool;
  // specular: the studio, blurred by roughness; turned metal smears it
  // along the axis of the lens
  float3 r = reflect(-v, n);
  float blur = s.rough * s.rough * 3.2;
  float3 spec;
  if (s.aniso > 0.0) {
    float3 ax = lensToWorldDir(float3(0.0, 1.0, 0.0));
    float3 rad = lensToWorldDir(normalize(float3(q.x, 0.0, q.z) + 1e-5));
    float3 tg = normalize(cross(ax, rad));
    float3 b = normalize(cross(n, tg) + 1e-5);
    spec = float3(0.0, 0.0, 0.0);
    for (int i = -2; i <= 2; i++) {
      float3 nn = normalize(n + b * (float(i) * 0.09 * s.aniso));
      spec += env(reflect(-v, nn), blur * 0.7);
    }
    spec *= 0.2;
  } else {
    spec = env(r, blur);
  }
  // glossy things see the scene, not just the studio
  if (s.rough < 0.3 || (id > 7.5 && id < 8.5)) {
    float2 h = march(p + n * 0.006, r, 40.0, true);
    if (h.x > 0.0) {
      float3 hp = p + n * 0.006 + r * h.x;
      float3 hn = calcNormal(hp);
      float3 hit = (h.y > 4.5 && h.y < 5.5) ? env(reflect(r, hn), 0.0) * 0.1 : shadeSimple(hp, hn, -r, h.y);
      // a rough floor blurs what it reflects the farther it is
      float keep = id > 7.5 && id < 8.5 ? exp(-h.x * 1.1) * 0.35 : 1.0;
      spec = lerp(spec, hit, keep);
    }
  }
  float specOcc = lerp(occ, 1.0, 0.35) * (1.0 - 0.7 * s.cavity);
  return diff * (1.0 - 0.5 * s.cavity) + spec * F * specOcc;
}

// ------------------------------------------------------------------ camera, samples, focus
#ifndef SAMPLES
#define SAMPLES 2
#endif
#ifndef FILTER_SIGMA
#define FILTER_SIGMA 0.5
#endif
// filmic tone curve
float3 filmic(float3 c) {
  return saturate((c * (2.51 * c + 0.03)) / (c * (2.43 * c + 0.59) + 0.14));
}
float4 shade(float2 pos, float px) {
  float2 sz = size();
  float3 target = float3(param(3), param(4), param(5));
  float az = radians(param(0)), el = radians(param(1));
  float3 eye = target + param(2) * float3(sin(az) * cos(el), sin(el), cos(az) * cos(el));
  gEye = eye;
  float3 fw = normalize(target - eye);
  float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
  float3 up = cross(rt, fw);
  float focal = 1.0 / tan(radians(param(6)) * 0.5);
  gPix = 2.0 / (focal * sz.y);
  float3 acc = float3(0.0, 0.0, 0.0);
  float depth = 1e4;
  float jit = hash12(pos * 0.37 + frac(time() * 7.13));
  // The pixel's footprint is a Gaussian (sigma FILTER_SIGMA px, cut at 3 sigma),
  // sampled on a golden-angle spiral with radii drawn from its distribution:
  // edges roll off over about a pixel, as through real glass and a sensor's
  // low-pass filter, instead of stepping. Each sample is tone-mapped before
  // the average, so a sub-pixel glint on a knurl ridge adds its share of the
  // pixel instead of flashing the whole pixel white from one frame to the next.
  float cut = 1.0 - exp(-4.5);
  for (int s = 0; s < SAMPLES; s++) {
    float u = (float(s) + 0.5) / float(SAMPLES);
    float rr = FILTER_SIGMA * sqrt(-2.0 * log(1.0 - u * cut));
    float a = float(s) * 2.39996323 + jit * TAU;
    float2 o = SAMPLES > 1 ? float2(cos(a), sin(a)) * rr : float2(0.0, 0.0);
    float2 qq = (pos + o - sz * 0.5) / (sz.y * 0.5);
    float3 rd = normalize(fw * focal + rt * qq.x - up * qq.y);
    float2 hit = march(eye, rd, 400.0, true);
    float3 c;
    if (hit.x < 0.0) {
      c = backdrop(rd);
    } else {
      float3 p = eye + rd * hit.x;
      if (s == 0) depth = hit.x;
      if (hit.y > 4.5 && hit.y < 5.5) {
        c = glassPath(p, rd, glassNormal(p));
      } else {
        float3 n = calcNormal(p);
        c = shadeFull(p, n, -rd, hit.y);
        // the floor melts into the backdrop with distance
        if (hit.y > 7.5 && hit.y < 8.5) c = lerp(c, backdrop(rd), saturate((hit.x - 40.0) / 80.0));
      }
    }
    acc += filmic(c * param(9));
  }
  float3 col = acc / float(SAMPLES);
  float coc = param(8) * (1.0 - param(7) / max(depth, 0.01));
  return float4(col, clamp(coc, -48.0, 48.0));
}

// Depth of field after the render: the scene's alpha is its signed circle of
// confusion in px (+ behind the focus plane, - in front of it). Each pixel
// gathers the pixels whose discs reach it, on a golden-angle spiral; what lies
// behind may not bleed over what is sharper in front. Bright points open into
// discs, as through a fast lens.
static const float GOLDEN = 2.39996323;
static const float TAU = 6.28318531;
float4 shade(float2 pos, float px) {
  float4 c0 = input(0, pos);
  float coc0 = abs(c0.a);
  // How far this pixel must look: its own disc, or a neighbour's that reaches it.
  float reach = coc0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * (TAU / 16.0) + 0.3;
    float d = (i & 1) == 0 ? 14.0 : 30.0;
    float n = input(0, pos + float2(cos(a), sin(a)) * d).a;
    float c = n > c0.a ? min(abs(n), coc0 * 2.0) : abs(n);
    if (c > d * 0.6) reach = max(reach, c);
  }
  if (reach < 0.75) return float4(c0.rgb, 1.0);
  float3 acc = c0.rgb;
  float tot = 1.0;
  float ang = frac(sin(dot(pos, float2(12.9898, 78.233))) * 43758.5453) * TAU;
  float r = 0.75;
  float scale = reach > 20.0 ? 1.6 : 0.9;
  for (int k = 0; k < 420; k++) {
    if (r > reach + 0.5) break;
    float2 tp = pos + float2(cos(ang), sin(ang)) * r;
    float4 s = input(0, tp);
    float sc = abs(s.a);
    if (s.a > c0.a) sc = min(sc, coc0 * 2.0);
    float m = smoothstep(r - 0.75, r + 0.75, sc);
    // wide discs of bright points carry more weight: bokeh
    float hot = smoothstep(0.8, 1.0, max(s.r, max(s.g, s.b))) * smoothstep(6.0, 16.0, sc);
    float w = m * (1.0 + 2.0 * hot);
    acc += s.rgb * w;
    tot += w;
    ang += GOLDEN;
    r += scale / r;
  }
  float3 col = acc / tot;
  return float4(min(col, float3(1.0, 1.0, 1.0)), 1.0);
}

#define SAMPLES 8
// HOLM 35 f/1.4: a camera lens in a photographer's studio, raymarched.
// Units are centimetres. The lens stands on its mount at the origin with its
// optical axis up (+y); the studio is three softboxes, two strip lights and a
// black acrylic floor. Every animated value is a param:
//    0  1  2   camera orbit: azimuth, elevation (degrees), distance
//    3  4  5   camera target
//    6         vertical field of view (degrees)
//    7         focus distance (cm)        8  blur: CoC in px at twice the focus distance
//    9         exposure                   10 explode 0..1 (the optics slide out)
//    11        focus ring turn (degrees)  12 iris, stops closed from f/1.4 (0..7)
//    13        light: 0 dark, 1 the sweep crosses, 2 full studio
//    14        lens tilt about z (deg)    15 lens spin about its axis (deg)
// The image's alpha carries the signed circle of confusion for the dof pass.

static const float PI = 3.14159265;
static const float TAU = 6.28318531;

// ------------------------------------------------------------------ helpers
float3 rotY(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }
float3 rotZ(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x - s * p.y, s * p.x + c * p.y, p.z); }
float hash12(float2 p) { float3 p3 = frac(float3(p.x, p.y, p.x) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return frac((p3.x + p3.y) * p3.z); }
float box2(float2 p, float2 b, float r) { float2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
// A ring turned on a lathe: radii r0..r1, heights y0..y1, its edges broken by e.
float ring(float2 ry, float r0, float r1, float y0, float y1, float e) {
  return box2(ry - float2((r0 + r1) * 0.5, (y0 + y1) * 0.5), float2((r1 - r0) * 0.5, (y1 - y0) * 0.5), e);
}
float2 opU(float2 a, float2 b) { return a.x < b.x ? a : b; }
float fbm2(float2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 4; i++) { s += a * snoise(float3(p, 0.37 * float(i))); p = p * 2.1 + float2(1.7, 9.2); a *= 0.5; } return s; }
float tri(float x) { return abs(frac(x) - 0.5) * 2.0; }        // 1 at integers, 0 halfway
// polynomial smooth min / max: blends a and b over a band k wide
float smin(float a, float b, float k) { float h = max(k - abs(a - b), 0.0) / k; return min(a, b) - h * h * k * 0.25; }
float smax(float a, float b, float k) { return -smin(-a, -b, k); }
float ease(float x) { x = saturate(x); return x * x * (3.0 - 2.0 * x); }

// ------------------------------------------------------------------ materials
#define M_SILVER 1.0
#define M_KNURL 2.0
#define M_BLACK 3.0
#define M_CHROME 4.0
#define M_GLASS 5.0
#define M_FLOCK 6.0
#define M_IRIS 7.0
#define M_FLOOR 8.0
#define M_EDGE 9.0
#define M_RIDGE 10.0
#define M_GOLD 11.0
#define M_ORANGE 12.0
#define M_GROUND 13.0

// ------------------------------------------------------------------ per-pixel camera state
static float3 gEye;
static float gPix;      // world size of one pixel at unit distance

float tilt() { return radians(param(14)); }
float spin() { return radians(param(15)); }
float explode() { return param(10); }

static const float3 LENS_ORIGIN = float3(0.0, 0.52, 0.0);   // the mount flange, in the world
static const float PIVOT_Y = 3.3;                            // where the lens turns when it tilts
float3 toLens(float3 p) {
  float3 q = p - LENS_ORIGIN - float3(0.0, PIVOT_Y, 0.0);
  q = rotZ(q, -tilt());
  q.y += PIVOT_Y;
  return rotY(q, -spin());
}
float3 lensToWorldDir(float3 v) { return rotZ(rotY(v, spin()), tilt()); }

// ------------------------------------------------------------------ the optics
// Eight elements in six groups, front to back. Each: centre height, centre
// thickness, front radius (+ convex), back radius (+ convex), clear radius.
// Exploded, each group slides forward to its own place on the axis.
static const float EXPLODE_BARREL = 3.4;
float groupShift(int g) {
  // front groups leave first; each eases out on its own beat
  static const float DY[7] = { 13.6, 11.9, 10.3, 9.0, 7.7, 6.6, 5.4 };
  float e = explode();
  float k = ease(e * 1.45 - float(g) * 0.075);
  return DY[g] * k;
}
float barrelShift() { return -EXPLODE_BARREL * ease(explode() * 1.3); }

// a spherical surface: + convex toward its side, - concave
float surfFront(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv - R)) - R;
  return max(-R - length(ry - float2(0.0, yv - R)), ry.y - (yv - R));
}
float surfBack(float2 ry, float yv, float R) {
  if (R > 0.0) return length(ry - float2(0.0, yv + R)) - R;
  return max(-R - length(ry - float2(0.0, yv + R)), (yv + R) - ry.y);
}
float element(float2 ry, float yc, float t, float Rf, float Rb, float a, out float edge) {
  float f = surfFront(ry, yc + t * 0.5, Rf);
  float b = surfBack(ry, yc - t * 0.5, Rb);
  float c = ry.x - a;
  float d = max(max(f, b), c);
  edge = c > max(f, b) - 0.002 ? 1.0 : 0.0;
  return d;
}

// The glass alone (for marching inside it). id = 5 glass, 9 inked edge.
float2 glassMap(float3 q) {
  float r = length(q.xz);
#ifdef CLEAR_EDGES
  const float EDGE_ID = M_GROUND;
#else
  const float EDGE_ID = M_EDGE;
#endif
  if (r > 2.3) return float2(r - 2.2, M_GLASS);
  float2 res = float2(1e5, M_GLASS);
  float edge;
  float y;
  // G1: E1 positive meniscus
  y = q.y - groupShift(0);
  float d = element(float2(r, y), 6.75, 0.5, 4.8, -9.0, 2.12, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G2: E2 + E3 cemented
  y = q.y - groupShift(1);
  d = element(float2(r, y), 6.0, 0.5, 3.4, -6.0, 1.85, edge);
  float e3 = max(max(max(length(float2(r, y) - float2(0.0, -0.25)) - 6.0, 2.4 - length(float2(r, y) - float2(0.0, 3.05))), r - 1.85), 3.05 - y);
  float edge3 = (r - 1.85) > -0.002 ? 1.0 : 0.0;
  d = min(d, e3);
  res = opU(res, float2(d, (edge > 0.5 || edge3 > 0.5) && r > 1.83 ? EDGE_ID : M_GLASS));
  // G3: E4 meniscus
  y = q.y - groupShift(2);
  d = element(float2(r, y), 5.0, 0.4, 2.6, -2.0, 1.5, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G4: E5 + E6 cemented (concave toward the iris)
  y = q.y - groupShift(4);
  float e5 = max(max(2.2 - length(float2(r, y) - float2(0.0, 5.5)), length(float2(r, y) - float2(0.0, 8.05)) - 5.0), r - 1.45);
  float e6 = max(max(5.0 - length(float2(r, y) - float2(0.0, 8.05)), length(float2(r, y) - float2(0.0, 5.7)) - 3.2), r - 1.45);
  e5 = max(e5, y - 3.95);
  d = min(e5, e6);
  res = opU(res, float2(d, r > 1.43 ? EDGE_ID : M_GLASS));
  // G5: E7 biconvex
  y = q.y - groupShift(5);
  d = element(float2(r, y), 1.6, 0.9, 4.0, 3.5, 1.55, edge);
  res = opU(res, float2(d, edge > 0.5 ? EDGE_ID : M_GLASS));
  // G6: E8, the rear element: its back face aspherical (a fourth-order term
  // flattens it toward the edge)
  y = q.y - groupShift(6);
  float f8 = surfFront(float2(r, y), 0.75, -6.0);
  float b8 = length(float2(r, y) - float2(0.0, 2.35)) - 2.2 + 0.012 * r * r * r * r;
  float c8 = r - 1.4;
  d = max(max(f8, b8), c8);
  res = opU(res, float2(d, c8 > max(f8, b8) - 0.002 ? EDGE_ID : M_GLASS));
  return res;
}

// The iris: eleven rounded blades between G3 and G4.
float irisRadius() { return 1.0 * 1.4 / (1.4 * pow(2.0, param(12) * 0.5)); }
float irisHole(float2 xz) {
  float a = irisRadius();
  float ang = atan2(xz.y, xz.x) + param(12) * 0.06;
  float sec = TAU / 11.0;
  float f = (frac(ang / sec) - 0.5) * sec;
  float rr = length(xz);
  float poly = rr * cos(f) - a;
  return lerp(poly, rr - a * 1.04, 0.55);     // blades are curved: rounder than a polygon
}
float irisMap(float3 q) {
  float y = q.y - 3.95 - groupShift(3);
  float r = length(q.xz);
  float disc = max(abs(y) - 0.022, r - 2.08);
  return max(disc, -irisHole(q.xz));
}

// ------------------------------------------------------------------ the barrel
// Diamond knurl on the focus ring, straight ridges on the aperture ring; both
// fade into a flat average where a pixel is wider than their pitch.
float knurlH(float3 q, float y, float fade) {
  float th = atan2(q.z, q.x) + radians(param(11));
  float u = th * (96.0 / TAU);
  float v = y / 0.2;
  // rolled, not cut: the crests, the valleys and the edges between facets are
  // rounded, so a crest catches the light as a soft line a few pixels wide
  // rather than a sub-pixel glint that flickers as the ring turns
  float h = smin(tri(u + v), tri(u - v), 0.08);
  h = smax(smin(h, 0.93, 0.12), 0.04, 0.08);
  return (h * 0.9 - 0.45) * 0.05 * fade;
}
float ridgeH(float3 q, float fade) {
  float th = atan2(q.z, q.x) + radians(param(12) * 12.0);
  float u = th * (180.0 / TAU);
  float h = smoothstep(0.0, 1.0, tri(u));
  return (h - 0.5) * 0.016 * fade;
}
float lodFade(float3 q, float pitch) {
  float3 e = toLens(gEye) - q;
  float d = length(e);
  float graze = abs(dot(normalize(float3(q.x, 0.0, q.z)), e / d));
  float foot = d * gPix / max(graze, 0.12);
  return smoothstep(pitch * 1.1, pitch * 0.45, foot);
}

float2 barrelMap(float3 q) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float2 ry = float2(r, y);
  float bound = ring(ry, 1.85, 3.25, -0.62, 7.3, 0.0);
  if (bound > 0.25) return float2(bound, M_SILVER);
  float2 res = float2(1e5, M_SILVER);
  // mount: chrome tube, flange and three bayonet lugs
  float th = atan2(q.z, q.x);
  float sector = abs(frac(th * 3.0 / TAU + 0.083) - 0.5) * (TAU / 3.0) * r;
  float lug = max(ring(ry, 1.98, 2.44, -0.52, -0.40, 0.02), sector - 0.95);
  float tube = ring(ry, 1.95, 2.33, -0.40, 0.02, 0.03);
  float flange = ring(ry, 2.2, 2.6, -0.09, 0.0, 0.02);
  res = opU(res, float2(min(min(lug, tube), flange), M_CHROME));
  // rear barrel: narrower than the rings above it, its foot broken wide
  res = opU(res, float2(ring(ry, 2.2, 2.78, 0.03, 1.36, 0.1), M_SILVER));
  // aperture ring with its ridged grip
  float ar = ring(ry, 2.25, 2.95, 1.42, 2.52, 0.05);
  if (y > 1.5 && y < 1.98 && r > 2.75) ar += ridgeH(q, lodFade(q, 0.105)) * smoothstep(1.5, 1.56, y) * smoothstep(1.98, 1.92, y);
  res = opU(res, float2(ar, (y > 1.49 && y < 1.99 && r > 2.85) ? M_RIDGE : M_SILVER));
  // the fixed scale ring (black anodised)
  res = opU(res, float2(ring(ry, 2.25, 2.84, 2.58, 3.04, 0.035), M_BLACK));
  // focus ring: a smooth scale band, a step, the knurl: the widest part
  float fr = ring(ry, 2.25, 3.08, 3.10, 5.62, 0.06);
  float step = ring(ry, 2.25, 3.13, 3.80, 5.46, 0.05);
  fr = min(fr, step);
  if (y > 3.8 && y < 5.46 && r > 2.95) fr += knurlH(q, y, lodFade(q, 0.2)) * smoothstep(3.84, 3.9, y) * smoothstep(5.42, 5.36, y);
  res = opU(res, float2(fr, (y > 3.83 && y < 5.43 && r > 3.03) ? M_KNURL : M_SILVER));
  // front barrel: tapering toward the front, two fine turned grooves
  float R = 3.0 - (clamp(y, 5.68, 6.96) - 5.68) * 0.055;
  float fb = box2(ry - float2((2.2 + R) * 0.5, 6.32), float2((R - 2.2) * 0.5, 0.64), 0.06);
  float gr = min(box2(ry - float2(R, 6.5), float2(0.02, 0.012), 0.008), box2(ry - float2(R, 6.64), float2(0.02, 0.012), 0.008));
  fb = max(fb, -gr);
  res = opU(res, float2(fb, M_SILVER));
  // a thin ring of orange anodising under the name ring
  res = opU(res, float2(ring(ry, 2.6, 2.935, 6.965, 7.055, 0.012), M_ORANGE));
  // the name ring: black, its front face engraved
  float nr = ring(ry, 2.22, 2.92, 7.06, 7.24, 0.04);
  res = opU(res, float2(nr, M_BLACK));
  // the inside: a light trap lining the metal (the innermost surface)
  float inner = ring(ry, 2.15, 2.27, 0.05, 7.2, 0.01);
  res = opU(res, float2(inner, M_FLOCK));
  return res;
}

// ------------------------------------------------------------------ the scene
static const float FLOOR_Y = 0.0;
float2 mapScene(float3 p, bool withGlass) {
  float2 res = float2(p.y - FLOOR_Y, M_FLOOR);
#ifdef NO_FLOOR
  res.x = 1e5;
#endif
  float3 q = toLens(p);
  res = opU(res, barrelMap(q));
  float rq = length(q.xz);
  if (rq < 2.4) {
    res = opU(res, float2(irisMap(q), M_IRIS));
    // the G1 retaining ring travels with the front element
    float y1 = q.y - groupShift(0);
    res = opU(res, float2(ring(float2(rq, y1), 2.02, 2.2, 6.58, 6.68, 0.01), M_FLOCK));
    if (withGlass) res = opU(res, glassMap(q));
  } else if (withGlass) {
    res = opU(res, float2(rq - 2.3, M_GLASS));
  }
  return res;
}
float2 map(float3 p) { return mapScene(p, true); }

float3 calcNormal(float3 p) {
  float2 e = float2(0.0007, -0.0007);
  return normalize(e.xyy * map(p + e.xyy).x + e.yyx * map(p + e.yyx).x + e.yxy * map(p + e.yxy).x + e.xxx * map(p + e.xxx).x);
}
float3 glassNormal(float3 p) {
  float2 e = float2(0.0006, -0.0006);
  float3 q = toLens(p);
  // gradient in lens space, turned back to the world
  float3 n = e.xyy * glassMap(q + e.xyy).x + e.yyx * glassMap(q + e.yyx).x + e.yxy * glassMap(q + e.yxy).x + e.xxx * glassMap(q + e.xxx).x;
  return normalize(lensToWorldDir(n));
}
float2 march(float3 ro, float3 rd, float maxd, bool withGlass) {
  float t = 0.0;
  for (int i = 0; i < 200; i++) {
    float2 h = mapScene(ro + rd * t, withGlass);
    if (abs(h.x) < 0.00025 * t + 0.0004) return float2(t, h.y);
    t += h.x * 0.85;
    if (t > maxd) break;
  }
  return float2(-1.0, 0.0);
}

// ------------------------------------------------------------------ the studio
// A softbox seen in direction d: a rounded rectangle on the plane facing the
// lens, its edges softened by `blur` (roughness widens it, keeping its energy).
float window1(float x, float a, float e) { return smoothstep(-a - e, -a + e, x) - smoothstep(a - e, a + e, x); }
// A softbox seen in direction d: a rectangle on the plane facing the lens,
// brighter at its centre, its edges softened by `blur` (roughness widens
// them, keeping the energy).
float softbox(float3 d, float3 c, float3 up, float2 half_, float blur) {
  float k = dot(d, c);
  if (k <= 0.02) return 0.0;
  float3 rt = normalize(cross(up, c));
  float3 u2 = cross(c, rt);
  float2 uv = float2(dot(d, rt), dot(d, u2)) / k;
  float fall = 1.0 - 0.45 * dot(uv / half_, uv / half_) * 0.5;
  return window1(uv.x, half_.x, 0.012 + blur) * window1(uv.y, half_.y, 0.012 + blur) * max(fall, 0.3);
}
// The light cue (param 13): 0..1 the rim strips outline the lens, 1..2 a
// strip sweeps across its front, 1.8..3 the studio comes up (overlapping it).
float rimAmt() { return saturate(param(13)); }
float sweepAmt() { return saturate(param(13) - 1.0); }
float studioAmt() { return saturate((param(13) - 1.8) / 1.2); }
#ifndef ENV_YAW
#define ENV_YAW 0.0
#endif
float3 env(float3 d, float blur) {
  d = rotY(d, radians(ENV_YAW));
  float s = studioAmt();
  float rim = rimAmt();
#ifdef STUDIO_SCALE
  float big = s * STUDIO_SCALE;
#else
  float big = s;
#endif
#ifdef RIM_SCALE
  rim *= RIM_SCALE;
#endif
  // the dark room: a little light up high, nearly black low down
  float3 c = lerp(float3(0.004, 0.004, 0.0042), float3(0.02, 0.0195, 0.019), saturate(d.y * 0.8 + 0.3)) * (0.15 + 0.85 * s);
  // key: a big box front left, high
  c += float3(1.0, 0.975, 0.94) * 2.6 * big * softbox(d, normalize(float3(-0.62, 0.5, 0.6)), float3(0, 1, 0), float2(0.55, 0.62), blur);
  // overhead scrim: broad and soft
  c += float3(0.95, 0.965, 1.0) * 1.5 * big * softbox(d, float3(0.0, 1.0, 0.0), float3(0, 0, -1), float2(1.1, 0.8), blur);
  // fill: a white card front right
  c += float3(1.0, 0.99, 0.97) * 0.75 * big * softbox(d, normalize(float3(0.7, 0.12, 0.7)), float3(0, 1, 0), float2(0.42, 0.55), blur);
  // two tall strips behind, one each side: the rims
  c += float3(0.93, 0.96, 1.0) * 6.5 * rim * softbox(d, normalize(float3(-0.9, 0.1, -0.42)), float3(0, 1, 0), float2(0.07, 1.0), blur);
  c += float3(1.0, 0.97, 0.94) * 5.5 * rim * softbox(d, normalize(float3(0.88, 0.14, -0.46)), float3(0, 1, 0), float2(0.055, 1.0), blur);
#ifdef LIGHTBOX
  // a small square box just over the camera's shoulder: the glints in the glass
  c += float3(1.0, 0.98, 0.95) * LIGHTBOX * softbox(d, normalize(LIGHTBOX_DIR), float3(0, 1, 0), float2(0.085, 0.085), blur);
#endif
#ifdef BACKLIGHT
#ifndef BACKLIGHT_COLOR
#define BACKLIGHT_COLOR float3(1.0, 0.9, 0.78)
#endif
  // a round light hidden behind the lens: seen only through it
  float bl = dot(d, normalize(BACKLIGHT_DIR));
  c += BACKLIGHT_COLOR * BACKLIGHT * smoothstep(0.3, 0.85, bl) * (0.6 + 0.4 * smoothstep(0.85, 1.0, bl));
#endif
  // the sweep: one strip that travels round the front of the lens
  float sw = sweepAmt();
  if (sw > 0.0 && sw < 1.0) {
    float a = lerp(-1.9, 1.6, sw);
    float3 sd = normalize(float3(sin(a), 0.22, cos(a)));
    c += float3(1.0, 0.98, 0.95) * 9.0 * softbox(d, sd, float3(0, 1, 0), float2(0.07, 1.2), blur) * smoothstep(0.0, 0.1, sw) * smoothstep(1.0, 0.8, sw) * (1.0 - s);
  }
  return c;
}
float3 envKeyDir() { return rotY(normalize(float3(-0.62, 0.5, 0.6)), -radians(ENV_YAW)); }

// What the camera sees past everything: a dark seamless sweep with a soft
// pool of light behind the lens.
float3 backdrop(float3 rd) {
  float s = max(studioAmt(), rimAmt() * 0.25);
  float3 base = float3(0.006, 0.0062, 0.0068);
  float3 toL = normalize(float3(0.0, 4.6, 0.0) - gEye);
  float halo = exp(-(1.0 - dot(rd, toL)) * 7.0);
  float3 c = base * (0.35 + 0.65 * s) + float3(0.03, 0.029, 0.028) * halo * s;
#ifdef BACKLIGHT
  // the panel behind lights the wall a little too
  c += float3(0.92, 0.93, 0.95) * BACKLIGHT * 0.03 * exp(-(1.0 - dot(rd, toL)) * 4.0);
#endif
  return c;
}

// ------------------------------------------------------------------ engravings
// Input 0 is an atlas of the engraved scales, drawn as ordinary text: four
// bands, each a range of ring angles across the frame's width and a range of
// heights (or radii) down its rows (BANDS in product.py holds the same numbers).
float wrapInto(float a, float a0) { return a0 + fmod(fmod(a - a0, 360.0) + 360.0, 360.0); }
float4 atlasBand(float alpha, float h, float a0, float a1, float h0, float h1, float r0, float r1, bool ltr) {
  float a = wrapInto(alpha, a0);
  if (a > a1) return float4(0.0, 0.0, 0.0, 0.0);
  float t = (h0 - h) / (h0 - h1);
  if (t < 0.0 || t > 1.0) return float4(0.0, 0.0, 0.0, 0.0);
  float x = ltr ? (a - a0) / (a1 - a0) : (a1 - a) / (a1 - a0);
  return input(0, float2(x * 1920.0, r0 + t * (r1 - r0)));
}
float4 engraving(float3 q, float3 n, float id) {
  float r = length(q.xz);
  float y = q.y - barrelShift();
  float th = degrees(atan2(q.z, q.x));
  if (id < 1.5) {
    if (r > 3.0 && y > 3.12 && y < 3.78) return atlasBand(th + param(11), y, 60.0, 260.0, 3.76, 3.14, 0.0, 111.0, false);
    if (r > 2.92 && y > 2.0 && y < 2.5) return atlasBand(th + param(12) * 12.0, y, 70.0, 200.0, 2.47, 2.02, 130.0, 257.0, false);
  } else if (id < 3.5) {
    if (r > 2.8 && y > 2.58 && y < 3.04) return atlasBand(th, y, 50.0, 130.0, 3.02, 2.60, 300.0, 521.0, false);
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    if (y > 7.15 && ax > 0.9) return atlasBand(th, r, 150.0, 390.0, 2.88, 2.40, 540.0, 620.0, true);
  }
  return float4(0.0, 0.0, 0.0, 0.0);
}

// ------------------------------------------------------------------ surfaces
struct Surf { float3 albedo; float metal; float rough; float aniso; float cavity; };

Surf surface(float id, float3 p, float3 q, float3 n) {
  Surf s;
  s.albedo = float3(0.8, 0.8, 0.8); s.metal = 0.0; s.rough = 0.5; s.aniso = 0.0; s.cavity = 0.0;
  float r = length(q.xz);
  float y = q.y - barrelShift();
  if (id < 1.5) {               // turned, bead-blasted aluminium, clear anodised
    // bead-blasted, clear anodised; the edges are diamond-cut and polished
    s.albedo = float3(0.9, 0.905, 0.91); s.metal = 1.0; s.aniso = 0.8;
    float ax = abs(dot(n, lensToWorldDir(float3(0.0, 1.0, 0.0))));
    float chamfer = smoothstep(0.12, 0.3, ax) * smoothstep(0.995, 0.95, ax);
    s.rough = lerp(0.5 + 0.06 * snoise(q * 40.0), 0.12, chamfer);
    s.aniso = lerp(0.8, 0.2, chamfer);
    // the mounting index: an orange dot on the rear barrel, facing the scales
    float dotd = length(float2((atan2(q.z, q.x) - 1.5708) * r, y - 0.72));
    float dotc = smoothstep(0.075, 0.062, dotd) * step(r, 2.8) * step(2.7, r);
    s.albedo = lerp(s.albedo, float3(0.8, 0.14, 0.035), dotc); s.metal = lerp(s.metal, 0.0, dotc); s.rough = lerp(s.rough, 0.6, dotc);
  } else if (id < 2.5) {        // knurl: same metal, sharper facets
    s.albedo = float3(0.86, 0.865, 0.87); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.2));
  } else if (id < 3.5) {        // black anodised: a dielectric skin over metal
    s.albedo = float3(0.02, 0.02, 0.022); s.metal = 0.0; s.rough = 0.42 + 0.04 * snoise(q * 30.0);
  } else if (id < 4.5) {        // chrome-plated brass mount
    s.albedo = float3(0.95, 0.95, 0.96); s.metal = 1.0; s.rough = 0.06;
  } else if (id < 5.5) {        // glass (handled by the glass path)
    s.albedo = float3(1.0, 1.0, 1.0); s.metal = -1.0; s.rough = 0.0;
  } else if (id < 6.5) {        // flocking: the inside eats light
    s.albedo = float3(0.006, 0.006, 0.007); s.metal = 0.0; s.rough = 0.9;
  } else if (id < 7.5) {        // iris blades: blackened steel with a sheen
    s.albedo = float3(0.035, 0.035, 0.04); s.metal = 0.0; s.rough = 0.26;
    float ang = atan2(q.z, q.x);
    float x = (ang / TAU) * 11.0 + log(max(r, 0.05)) * 1.9;
    float seam = tri(x);
    float blade = floor(x + 0.5);
    s.albedo = float3(0.03, 0.03, 0.034) * (0.6 + 0.8 * frac(sin(blade * 12.9898) * 43758.5453));
    s.rough = 0.22;
    s.albedo *= 0.35 + 0.65 * smoothstep(0.0, 0.1, seam);
  } else if (id < 8.5) {        // black acrylic floor
    s.albedo = float3(0.014, 0.014, 0.015) * (0.9 + 0.1 * fbm2(p.xz * 0.6)); s.metal = 0.0; s.rough = 0.28;
  } else if (id < 9.5) {        // inked edges of the glass
    s.albedo = float3(0.012, 0.012, 0.013); s.metal = 0.0; s.rough = 0.6;
  } else if (id > 12.5 && id < 13.5) {  // a ground glass edge, milky
    s.albedo = float3(0.42, 0.45, 0.44); s.metal = 0.0; s.rough = 0.55;
  } else if (id > 11.5 && id < 12.5) {  // orange anodised aluminium
    s.albedo = float3(0.92, 0.3, 0.085); s.metal = 1.0; s.rough = 0.3; s.aniso = 0.5;
  } else if (id < 10.5) {       // ridges of the aperture ring
    s.albedo = float3(0.88, 0.885, 0.89); s.metal = 1.0; s.rough = lerp(0.5, 0.3, lodFade(q, 0.105));
  }
  // engraved and filled with paint
  if (id < 3.5 && id != 2.0) {
    float4 e = engraving(q, n, id);
    if (e.a > 0.002) {
      // white in the atlas is the primary fill: black on silver, white on black
      float3 ink = e.rgb / e.a;
      float white = saturate((ink.b - 0.5) * 4.0);
      float3 primary = id < 1.5 ? float3(0.005, 0.005, 0.0055) : float3(0.78, 0.78, 0.76);
      ink = lerp(ink * 0.85, primary, white);
      s.albedo = lerp(s.albedo, ink, e.a);
      s.metal = lerp(s.metal, 0.0, e.a);
      s.rough = lerp(s.rough, 0.85, e.a);
      s.aniso *= 1.0 - e.a;
      s.cavity = e.a;
      s.albedo *= 1.0 - 2.0 * e.a * (1.0 - e.a);     // the walls of the cut
    }
  }
  return s;
}

// ------------------------------------------------------------------ light
float softShadow(float3 ro, float3 rd, float k) {
  float res = 1.0, t = 0.02;
  for (int i = 0; i < 48; i++) {
    float h = mapScene(ro + rd * t, false).x;
    res = min(res, k * h / t);
    t += clamp(h, 0.02, 0.6);
    if (res < 0.002 || t > 30.0) break;
  }
  return saturate(res);
}
float ambientOcc(float3 p, float3 n) {
  float occ = 0.0, sca = 1.0;
  for (int i = 0; i < 5; i++) {
    float h = 0.02 + 0.12 * float(i);
    occ += (h - map(p + n * h).x) * sca;
    sca *= 0.7;
  }
  return saturate(1.0 - 1.6 * occ);
}
float3 fresnelS(float3 f0, float nv, float rough) {
  return f0 + (max(float3(1.0 - rough, 1.0 - rough, 1.0 - rough), f0) - f0) * pow(1.0 - nv, 5.0);
}

// Light reflected by a surface (one bounce of the studio): simple, for what
// glass and mirrors see.
float3 shadeSimple(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float3 r = reflect(-v, n);
  float3 kd = s.albedo * (1.0 - max(s.metal, 0.0));
  float key = studioAmt() * saturate(dot(n, envKeyDir()));
  if (id > 7.5 && id < 8.5 && abs(param(14)) < 1.0) kd *= smoothstep(2.4, 3.4, length(p.xz - LENS_ORIGIN.xz));
  if (id > 7.5 && id < 8.5 && key > 0.0) key *= softShadow(p + n * 0.01, envKeyDir(), 6.0);
  float3 diff = kd * (env(n, 0.9) * 1.2 + float3(1.0, 0.97, 0.94) * 2.2 * key);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, max(s.metal, 0.0));
  float3 spec = env(r, s.rough * s.rough * 3.2) * fresnelS(f0, saturate(dot(n, v)), s.rough);
  return diff + spec;
}

// Thin-film anti-reflection coating: a faint reflection that leans green
// head-on and magenta toward the edge, a different cast on each surface.
float3 coatF(float cosi, float k) {
  float h = frac(k * 0.37 + (1.0 - cosi) * 0.6);
  float3 tint = h < 0.5 ? lerp(float3(0.3, 1.0, 0.5), float3(0.9, 0.4, 1.0), h * 2.0) : lerp(float3(0.9, 0.4, 1.0), float3(0.3, 1.0, 0.5), h * 2.0 - 1.0);
  float3 r0 = 0.004 + 0.02 * tint;
  return r0 + (1.0 - r0) * pow(1.0 - cosi, 5.0);
}

#define GLASS_IOR 1.62
// Light through the optics: refract in, cross each element, refract out,
// gathering each surface's coated reflection of the studio on the way.
float3 glassPath(float3 pos, float3 dir, float3 n) {
  float3 col = float3(0.0, 0.0, 0.0);
  float3 thr = float3(1.0, 1.0, 1.0);
  float3 dir0 = dir;
  bool inside = false;
  float3 nn = n;                 // faces against the ray
  float3 axis = lensToWorldDir(float3(0.0, 1.0, 0.0));
  float open = ease(explode() * 3.0);
  for (int k = 0; k < 16; k++) {
    float cosi = saturate(-dot(dir, nn));
    float3 F = coatF(cosi, float(k));
    float3 rdir = reflect(dir, nn);
    // inside the barrel a reflection only sees the studio through the front
    float esc = k == 0 ? 1.0 : lerp(smoothstep(0.8, 0.97, dot(rdir, axis)), 1.0, open);
    col += thr * F * (inside ? 0.35 : 1.0) * env(rdir, 0.0) * esc;
    thr *= 1.0 - F;
    float3 t = refract(dir, nn, inside ? GLASS_IOR : 1.0 / GLASS_IOR);
    bool tir = dot(t, t) < 1e-5;
    if (tir) { dir = rdir; } else { dir = t; inside = !inside; }
    // step off the surface to the side the ray now travels
    pos += (dot(dir, nn) < 0.0 ? -nn : nn) * 0.0025;
    if (inside) {
      // through the glass to where the ray leaves it
      float s = 0.0;
      float2 g = float2(-1.0, M_GLASS);
      for (int i = 0; i < 80; i++) {
        g = glassMap(toLens(pos + dir * s));
        if (-g.x < 0.0003 || s > 8.0) break;
        s += max(-g.x, 0.0015);
      }
      pos += dir * s;
      if (g.y > 8.5) return col;          // out through an edge: lost
      nn = -glassNormal(pos);
      thr *= float3(0.985, 0.99, 0.982);  // a whisper of green from the glass itself
#ifndef FULL_TRACE
      if (explode() < 0.001) {
        // leave the front element, then the inside of the lens; light
        // trapped in the glass is lost
        float3 t2 = refract(dir, nn, GLASS_IOR);
        if (dot(t2, t2) < 1e-5) return col;
        float c2 = saturate(-dot(dir, nn));
        float3 F2 = coatF(c2, 1.0);
        col += thr * min(F2, float3(0.03, 0.03, 0.03)) * 0.35 * env(reflect(dir, nn), 0.0) * smoothstep(0.8, 0.97, dot(reflect(dir, nn), axis));
        return col + thr * (1.0 - F2) * lensInterior(pos - nn * 0.003, t2);
      }
#endif
    } else {
      float2 h = march(pos, dir, 60.0, true);
      if (h.x < 0.0) {
        // out of the lens into the studio, split by wavelength
        float3 dev = (dir - dir0) * 0.06;
        col += thr * float3(env(dir - dev, 0.0).r, env(dir, 0.0).g, env(dir + dev, 0.0).b);
        return col;
      }
      pos = pos + dir * h.x;
      if (h.y > 4.5 && h.y < 5.5) {
        nn = glassNormal(pos);
      } else {
        col += thr * shadeSimple(pos, calcNormal(pos), -dir, h.y);
        return col;
      }
    }
  }
  return col;
}


// ------------------------------------------------------------------ inside the assembled lens
// Past the front element the light is followed along a straight line: every
// inner surface it crosses adds its coated ghost of the studio, the iris
// stops it or lets it through, the barrel's black walls swallow the rest.
// (A full trace through eight curved elements is correct and unreadable.)
float3 dirToLens(float3 v) { return rotY(rotZ(v, -tilt()), -spin()); }
// sphere surfaces of the inner elements: centre height, radius, clear radius, coating hue
static const float4 GHOSTS[10] = {
  float4(2.85, 3.4, 1.85, 0.1), float4(3.05, 2.4, 1.85, 0.55), float4(2.6, 2.6, 1.5, 0.8), float4(2.8, 2.0, 1.5, 0.3),
  float4(5.5, 2.2, 1.45, 0.65), float4(5.7, 3.2, 1.45, 0.2), float4(-1.95, 4.0, 1.55, 0.9), float4(4.65, 3.5, 1.55, 0.45),
  float4(6.75, 6.0, 1.4, 0.7), float4(2.35, 2.2, 1.4, 0.05) };
static const float2 GHOST_Y[10] = {           // the y range each surface occupies
  float2(5.7, 6.26), float2(4.57, 5.46), float2(4.7, 5.21), float2(4.1, 4.81),
  float2(3.29, 3.86), float2(2.49, 2.86), float2(1.73, 2.06), float2(1.14, 1.52), float2(0.74, 0.93), float2(0.14, 0.66) };
float3 lensInterior(float3 pw, float3 dw) {
  float3 o = toLens(pw);
  float3 d = normalize(dirToLens(dw));
  float3 col = float3(0.0, 0.0, 0.0);
  float yIris = 3.95;
  // where the ray meets the black inner wall (r = 2.12)
  float a = dot(d.xz, d.xz), b = dot(o.xz, d.xz), c = dot(o.xz, o.xz) - 2.12 * 2.12;
  float tWall = a > 1e-6 ? (-b + sqrt(max(b * b - a * c, 0.0))) / a : 1e5;
  float tIris = d.y < -1e-4 ? (yIris - o.y) / d.y : 1e5;
  float3 axisW = lensToWorldDir(float3(0.0, 1.0, 0.0));
  for (int i = 0; i < 10; i++) {
    float4 g = GHOSTS[i];
    float3 oc = o - float3(0.0, g.x, 0.0);
    float bb = dot(oc, d), cc = dot(oc, oc) - g.y * g.y;
    float disc = bb * bb - cc;
    if (disc < 0.0) continue;
    float sq = sqrt(disc);
    for (int k = 0; k < 2; k++) {
      float t = -bb + (k == 0 ? -sq : sq);
      if (t <= 0.0 || t > tWall) continue;
      float3 h = o + d * t;
      if (h.y < GHOST_Y[i].x || h.y > GHOST_Y[i].y || length(h.xz) > g.z) continue;
      // behind the iris only what the iris lets through counts
      if (h.y < yIris && (t > tIris && irisHole(o.xz + d.xz * tIris) > 0.0)) continue;
      float3 n = normalize(h - float3(0.0, g.x, 0.0));
      if (dot(n, d) > 0.0) n = -n;
      float3 rw = lensToWorldDir(reflect(d, n));
      float cosi = saturate(-dot(d, n));
      // coatings leave green, magenta or amber, shifting a little with angle
      float hue = frac(g.w + (1.0 - cosi) * 0.25);
      float3 tint = hue < 0.33 ? lerp(float3(0.25, 1.0, 0.45), float3(0.95, 0.35, 1.0), hue * 3.0)
                  : hue < 0.66 ? lerp(float3(0.95, 0.35, 1.0), float3(1.0, 0.62, 0.22), hue * 3.0 - 1.0)
                               : lerp(float3(1.0, 0.62, 0.22), float3(0.25, 1.0, 0.45), hue * 3.0 - 2.0);
      float esc = smoothstep(0.82, 0.97, dot(rw, axisW));
      col += tint * 0.022 * env(rw, 0.035) * esc;
    }
  }
  if (tIris < tWall) {
    float3 h = o + d * tIris;
    if (irisHole(h.xz) > 0.0) {
      // a blade: blackened steel, lit by what comes in through the front
      float3 hw = LENS_ORIGIN + float3(0.0, PIVOT_Y, 0.0) + rotZ(rotY(h, spin()) - float3(0.0, PIVOT_Y, 0.0), tilt());
      float blade = floor(atan2(h.z, h.x) / TAU * 11.0 + log(max(length(h.xz), 0.05)) * 1.9 + 0.5);
      float3 rad = normalize(float3(h.x, 0.0, h.z) + 1e-5);
      float3 tan_ = float3(-rad.z, 0.0, rad.x);
      float3 nb = normalize(float3(0.0, 1.0, 0.0) + tan_ * (0.16 * sin(blade * 2.39)) + rad * 0.07);
      return col + shadeSimple(hw, lensToWorldDir(nb), -dw, M_IRIS) * 0.9;
    }
    // through the opening and out of the back: the floor under a standing
    // lens is dark; otherwise whatever lies behind
    if (abs(param(14)) < 1.0) return col;
    float3 dd = dw * 1.0;
    return col + env(dd, 0.0) * 0.9;
  }
  return col;     // the inner wall
}

// The full light at a surface the camera sees.
float3 shadeFull(float3 p, float3 n, float3 v, float id) {
  float3 q = toLens(p);
  Surf s = surface(id, p, q, n);
  float nv = saturate(dot(n, v));
  float occ = ambientOcc(p, n);
  float3 kd = s.albedo * (1.0 - s.metal);
  float3 f0 = lerp(float3(0.04, 0.04, 0.04), s.albedo, s.metal);
  float3 F = fresnelS(f0, nv, s.rough);
  // diffuse: the key box (with its shadow) and the room
  float3 L = envKeyDir();
  float nl = saturate(dot(n, L));
  float sh = nl > 0.0 ? softShadow(p + n * 0.004, L, 6.0) : 0.0;
  float pool = id > 7.5 && id < 8.5 ? exp(-dot(p.xz, p.xz) / 260.0) : 1.0;
  float3 diff = kd * (float3(1.0, 0.975, 0.94) * 2.4 * studioAmt() * nl * sh + env(n, 0.9) * 1.3 * occ) * pool;
  // specular: the studio, blurred by roughness; turned metal smears it
  // along the axis of the lens
  float3 r = reflect(-v, n);
  float blur = s.rough * s.rough * 3.2;
  float3 spec;
  if (s.aniso > 0.0) {
    float3 ax = lensToWorldDir(float3(0.0, 1.0, 0.0));
    float3 rad = lensToWorldDir(normalize(float3(q.x, 0.0, q.z) + 1e-5));
    float3 tg = normalize(cross(ax, rad));
    float3 b = normalize(cross(n, tg) + 1e-5);
    spec = float3(0.0, 0.0, 0.0);
    for (int i = -2; i <= 2; i++) {
      float3 nn = normalize(n + b * (float(i) * 0.09 * s.aniso));
      spec += env(reflect(-v, nn), blur * 0.7);
    }
    spec *= 0.2;
  } else {
    spec = env(r, blur);
  }
  // glossy things see the scene, not just the studio
  if (s.rough < 0.3 || (id > 7.5 && id < 8.5)) {
    float2 h = march(p + n * 0.006, r, 40.0, true);
    if (h.x > 0.0) {
      float3 hp = p + n * 0.006 + r * h.x;
      float3 hn = calcNormal(hp);
      float3 hit = (h.y > 4.5 && h.y < 5.5) ? env(reflect(r, hn), 0.0) * 0.1 : shadeSimple(hp, hn, -r, h.y);
      // a rough floor blurs what it reflects the farther it is
      float keep = id > 7.5 && id < 8.5 ? exp(-h.x * 1.1) * 0.35 : 1.0;
      spec = lerp(spec, hit, keep);
    }
  }
  float specOcc = lerp(occ, 1.0, 0.35) * (1.0 - 0.7 * s.cavity);
  return diff * (1.0 - 0.5 * s.cavity) + spec * F * specOcc;
}

// ------------------------------------------------------------------ camera, samples, focus
#ifndef SAMPLES
#define SAMPLES 2
#endif
#ifndef FILTER_SIGMA
#define FILTER_SIGMA 0.5
#endif
// filmic tone curve
float3 filmic(float3 c) {
  return saturate((c * (2.51 * c + 0.03)) / (c * (2.43 * c + 0.59) + 0.14));
}
float4 shade(float2 pos, float px) {
  float2 sz = size();
  float3 target = float3(param(3), param(4), param(5));
  float az = radians(param(0)), el = radians(param(1));
  float3 eye = target + param(2) * float3(sin(az) * cos(el), sin(el), cos(az) * cos(el));
  gEye = eye;
  float3 fw = normalize(target - eye);
  float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
  float3 up = cross(rt, fw);
  float focal = 1.0 / tan(radians(param(6)) * 0.5);
  gPix = 2.0 / (focal * sz.y);
  float3 acc = float3(0.0, 0.0, 0.0);
  float depth = 1e4;
  float jit = hash12(pos * 0.37 + frac(time() * 7.13));
  // The pixel's footprint is a Gaussian (sigma FILTER_SIGMA px, cut at 3 sigma),
  // sampled on a golden-angle spiral with radii drawn from its distribution:
  // edges roll off over about a pixel, as through real glass and a sensor's
  // low-pass filter, instead of stepping. Each sample is tone-mapped before
  // the average, so a sub-pixel glint on a knurl ridge adds its share of the
  // pixel instead of flashing the whole pixel white from one frame to the next.
  float cut = 1.0 - exp(-4.5);
  for (int s = 0; s < SAMPLES; s++) {
    float u = (float(s) + 0.5) / float(SAMPLES);
    float rr = FILTER_SIGMA * sqrt(-2.0 * log(1.0 - u * cut));
    float a = float(s) * 2.39996323 + jit * TAU;
    float2 o = SAMPLES > 1 ? float2(cos(a), sin(a)) * rr : float2(0.0, 0.0);
    float2 qq = (pos + o - sz * 0.5) / (sz.y * 0.5);
    float3 rd = normalize(fw * focal + rt * qq.x - up * qq.y);
    float2 hit = march(eye, rd, 400.0, true);
    float3 c;
    if (hit.x < 0.0) {
      c = backdrop(rd);
    } else {
      float3 p = eye + rd * hit.x;
      if (s == 0) depth = hit.x;
      if (hit.y > 4.5 && hit.y < 5.5) {
        c = glassPath(p, rd, glassNormal(p));
      } else {
        float3 n = calcNormal(p);
        c = shadeFull(p, n, -rd, hit.y);
        // the floor melts into the backdrop with distance
        if (hit.y > 7.5 && hit.y < 8.5) c = lerp(c, backdrop(rd), saturate((hit.x - 40.0) / 80.0));
      }
    }
    acc += filmic(c * param(9));
  }
  float3 col = acc / float(SAMPLES);
  float coc = param(8) * (1.0 - param(7) / max(depth, 0.01));
  return float4(col, clamp(coc, -48.0, 48.0));
}

// Depth of field after the render: the scene's alpha is its signed circle of
// confusion in px (+ behind the focus plane, - in front of it). Each pixel
// gathers the pixels whose discs reach it, on a golden-angle spiral; what lies
// behind may not bleed over what is sharper in front. Bright points open into
// discs, as through a fast lens.
static const float GOLDEN = 2.39996323;
static const float TAU = 6.28318531;
float4 shade(float2 pos, float px) {
  float4 c0 = input(0, pos);
  float coc0 = abs(c0.a);
  // How far this pixel must look: its own disc, or a neighbour's that reaches it.
  float reach = coc0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * (TAU / 16.0) + 0.3;
    float d = (i & 1) == 0 ? 14.0 : 30.0;
    float n = input(0, pos + float2(cos(a), sin(a)) * d).a;
    float c = n > c0.a ? min(abs(n), coc0 * 2.0) : abs(n);
    if (c > d * 0.6) reach = max(reach, c);
  }
  if (reach < 0.75) return float4(c0.rgb, 1.0);
  float3 acc = c0.rgb;
  float tot = 1.0;
  float ang = frac(sin(dot(pos, float2(12.9898, 78.233))) * 43758.5453) * TAU;
  float r = 0.75;
  float scale = reach > 20.0 ? 1.6 : 0.9;
  for (int k = 0; k < 420; k++) {
    if (r > reach + 0.5) break;
    float2 tp = pos + float2(cos(ang), sin(ang)) * r;
    float4 s = input(0, tp);
    float sc = abs(s.a);
    if (s.a > c0.a) sc = min(sc, coc0 * 2.0);
    float m = smoothstep(r - 0.75, r + 0.75, sc);
    // wide discs of bright points carry more weight: bokeh
    float hot = smoothstep(0.8, 1.0, max(s.r, max(s.g, s.b))) * smoothstep(6.0, 16.0, sc);
    float w = m * (1.0 + 2.0 * hot);
    acc += s.rgb * w;
    tot += w;
    ang += GOLDEN;
    r += scale / r;
  }
  float3 col = acc / tot;
  return float4(min(col, float3(1.0, 1.0, 1.0)), 1.0);
}
